def application_base_dir() -> Path:
    """Carpeta externa de la aplicación, estable para código fuente y EXE."""
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent


def resource_path(relative_path: str) -> str:
    """Ruta de recursos internos incluidos por PyInstaller."""
    bundle_dir = Path(getattr(sys, "_MEIPASS", application_base_dir()))
    return str(bundle_dir / relative_path)


# APP_DIR es externo y escribible; BUNDLE_DIR se reserva para recursos internos.
