# Este módulo factura únicamente ARS privadas. La clave elimina espacios,
# mayúsculas y variantes de escritura para que un valor antiguo no pueda
# reingresar al flujo operativo desde caché o Admisión.
MEDICATION_EXCLUDED_ARS_KEYS = frozenset({
    "SENASASUBSIDIADO",
    "SENASASUB",
})

# Estas exclusiones pertenecen a las vistas de enlace con AdmisiÃ³n. No cambian
# el catÃ¡logo clÃ­nico ni eliminan atenciones del repositorio de origen.
VALIDATION_EXCLUDED_ARS_KEYS = frozenset({
    "SENASASUBSIDIADO", "SENASASUB", "UNIVERSAL", "BANCOCENTRAL",
})
ADMISSION_HISTORY_EXCLUDED_ARS_KEYS = frozenset({
    *VALIDATION_EXCLUDED_ARS_KEYS, "YUNEN",
})


def medication_ars_key(value) -> str:
    normalized = str(normalize_key(value) or "").upper()
    return re.sub(r"[^A-Z0-9]+", "", normalized)


def is_excluded_billing_ars(value) -> bool:
    """Regla canónica única para ARS que no pertenecen a Facturación."""
    key = medication_ars_key(value)
    return bool(key) and any(
        key.startswith(excluded_key)
        for excluded_key in MEDICATION_EXCLUDED_ARS_KEYS
    )


def medication_ars_is_selectable(value) -> bool:
    return bool(str(value or "").strip()) and not is_excluded_billing_ars(value)


def require_medication_ars(value) -> str:
    name = str(value or "").strip()
    if not medication_ars_is_selectable(name):
        raise ValueError("SENASA SUBSIDIADO no se factura en este módulo.")
    return name


def medication_ars_sql_exclusion(column: str = "r.ars") -> str:
    """Filtro PostgreSQL para resultados operativos de medicamentos."""
    normalized = (
        "UPPER(REGEXP_REPLACE(COALESCE("
        f"{column},''), '[^A-Za-z0-9]+', '', 'g'))"
    )
    return f"{normalized} !~ '^SENASASUB'"


def admission_ars_is_visible(value, *, history: bool = False) -> bool:
    key = medication_ars_key(value)
    excluded = (
        ADMISSION_HISTORY_EXCLUDED_ARS_KEYS
        if history else VALIDATION_EXCLUDED_ARS_KEYS
    )
    return bool(key) and not any(key.startswith(item) for item in excluded)


def admission_ars_sql_exclusion(column: str, *, history: bool = False) -> str:
    normalized = (
        "UPPER(REGEXP_REPLACE(COALESCE("
        f"{column},''), '[^A-Za-z0-9]+', '', 'g'))"
    )
    excluded = (
        ADMISSION_HISTORY_EXCLUDED_ARS_KEYS
        if history else VALIDATION_EXCLUDED_ARS_KEYS
    )
    patterns = "|".join(sorted(excluded, key=len, reverse=True))
    return f"{normalized} !~ '^({patterns})'"


def normalize_batch_status(value) -> str:
    return str(value or BATCH_PENDING).strip().upper()


def batch_is_editable(batch_or_status) -> bool:
    value = (
        batch_or_status.get("status")
        if isinstance(batch_or_status, dict)
        else batch_or_status
    )
    return normalize_batch_status(value) in BATCH_EDITABLE_STATUSES


def batch_status_label(value) -> str:
    status = normalize_batch_status(value)
    if status == BATCH_DRAFT:
        return BATCH_PENDING
    if status == BATCH_CLOSED:
        return BATCH_SENT
    return status


def normalize_monthly_ars_name(value) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()


def monthly_ars_is_selectable(value) -> bool:
    return medication_ars_is_selectable(value)

