class DatabaseSchemaIncompatible(RuntimeError):
    """The central database is reachable but misses required application schema."""


def inspect_database_schema_compatibility(con) -> tuple[bool, list[str]]:
    """Read-only compatibility check used by normal client startup."""
    table_names = list(_BOOTSTRAP_REQUIRED_SCHEMA)
    rows = con.execute(
        """SELECT table_name,column_name
             FROM information_schema.columns
            WHERE table_schema='public' AND table_name=ANY(%s)""",
        (table_names,),
    ).fetchall()
    present: dict[str, set[str]] = {name: set() for name in table_names}
    for row in rows:
        present[str(row[0])].add(str(row[1]))
    missing: list[str] = []
    for table_name, required_columns in _BOOTSTRAP_REQUIRED_SCHEMA.items():
        if not present[table_name]:
            missing.append(f"table:{table_name}")
            continue
        for column_name in sorted(required_columns - present[table_name]):
            missing.append(f"column:{table_name}.{column_name}")
    return not missing, missing


def _read_database_schema_state(con) -> tuple[bool, bool, list[str]]:
    registry = con.execute(
        "SELECT to_regclass('public.schema_migrations')"
    ).fetchone()
    marker = None
    if registry and registry[0]:
        marker = con.execute(
            "SELECT migration_id FROM schema_migrations WHERE migration_id=%s",
            (BOOTSTRAP_SCHEMA_MIGRATION_ID,),
        ).fetchone()
    compatible, missing = inspect_database_schema_compatibility(con)
    return bool(marker), compatible, missing


def prepare_database_schema() -> str:
    """Skip historical DDL on compatible clients; migrate once under a global lock."""
    with db_connect() as con:
        ensure_sigeh_production_schema(con)
    with db_connect() as con:
        marker_present, compatible, _missing = _read_database_schema_state(con)
    if marker_present and compatible:
        return "ALREADY_COMPATIBLE"

    database_url = validate_database_url(DB_URL)
    lock_connection = psycopg2.connect(
        database_url,
        connect_timeout=8,
        options="-c statement_timeout=15000 -c lock_timeout=3000",
        application_name="hospital_schema_coordinator",
    )
    lock_connection.autocommit = True
    lock_cursor = lock_connection.cursor()
    try:
        lock_cursor.execute(
            "SELECT pg_advisory_lock(hashtext(%s))",
            ("hospital-main-schema-migration",),
        )
        with db_connect() as con:
            registry = con.execute(
                "SELECT to_regclass('public.schema_migrations')"
            ).fetchone()
            if not registry or not registry[0]:
                con.execute(
                    """CREATE TABLE schema_migrations(
                           migration_id TEXT PRIMARY KEY,
                           applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                           app_version TEXT NOT NULL
                       )"""
                )
            marker, compatible, missing = _read_database_schema_state(con)
        if compatible:
            if not marker:
                with db_connect() as con:
                    con.execute(
                        """INSERT INTO schema_migrations(migration_id,app_version)
                           VALUES(%s,%s) ON CONFLICT(migration_id) DO NOTHING""",
                        (BOOTSTRAP_SCHEMA_MIGRATION_ID, BOOTSTRAP_APP_VERSION),
                    )
            return "ALREADY_COMPATIBLE"

        write_main_app_log(
            "DATABASE_MIGRATION_REQUIRED",
            stage="DB_MIGRATION_CHECK",
            details=",".join(missing),
        )

        # Estas columnas del snapshot operacional se pueden añadir de manera
        # idempotente sin reejecutar las migraciones históricas completas.
        operational_snapshot_columns = {
            "column:admission_operational_sessions.operational_revision",
            "column:admission_operational_sessions.turn_code",
        }
        if missing and set(missing).issubset(operational_snapshot_columns):
            with db_connect() as con:
                if "column:admission_operational_sessions.operational_revision" in missing:
                    con.execute(
                        "ALTER TABLE admission_operational_sessions "
                        "ADD COLUMN IF NOT EXISTS operational_revision "
                        "BIGINT NOT NULL DEFAULT 1"
                    )
                if "column:admission_operational_sessions.turn_code" in missing:
                    con.execute(
                        "ALTER TABLE admission_operational_sessions "
                        "ADD COLUMN IF NOT EXISTS turn_code TEXT NOT NULL DEFAULT ''"
                    )
        else:
            db_init()

        with db_connect() as con:
            compatible, missing = inspect_database_schema_compatibility(con)
            if not compatible:
                raise DatabaseSchemaIncompatible(
                    "El esquema central continúa incompleto después de la migración: "
                    + ", ".join(missing)
                )
            con.execute(
                """INSERT INTO schema_migrations(migration_id,app_version)
                   VALUES(%s,%s) ON CONFLICT(migration_id) DO UPDATE SET
                   applied_at=NOW(),app_version=EXCLUDED.app_version""",
                (BOOTSTRAP_SCHEMA_MIGRATION_ID, BOOTSTRAP_APP_VERSION),
            )
        return "MIGRATED"
    finally:
        try:
            lock_cursor.execute(
                "SELECT pg_advisory_unlock(hashtext(%s))",
                ("hospital-main-schema-migration",),
            )
        finally:
            lock_cursor.close()
            lock_connection.close()


def get_admission_operational_snapshot() -> dict:
    """One small central query; it never reads V15, patients, reports, or Excel."""
    started = perf_counter()
    logger = logging.getLogger("hospital.admission.operational")
    logger.info("OP_STATE_FETCH_START")
    try:
        with db_connect() as con:
            row = con.execute(
                """SELECT operational_session_id,operational_source_id,
                          active_user_id,active_username,active_user_display_name,
                          active_user_id AS representative_user_id,
                          active_username AS representative_username,
                          active_user_display_name AS representative_display_name,
                          turn_id,turn_code,turn_started_at,turn_ends_at,generation,
                          operational_revision,primary_device_id,primary_login_session_id,
                          lease_generation,status,session.updated_at AS updated_at
                     FROM admission_operational_sessions session
                     JOIN sigeh_product_state product
                       ON product.singleton=1
                      AND product.production_epoch_id=session.production_epoch_id
                    WHERE session.status='ACTIVE'
                    ORDER BY session.updated_at DESC
                    LIMIT 1"""
            ).fetchone()
        snapshot = dict(row) if row else {}
        logger.info(
            "OP_STATE_FETCH_DONE elapsed_ms=%.1f revision=%s",
            (perf_counter() - started) * 1000.0,
            snapshot.get("operational_revision", 0),
        )
        return snapshot
    except Exception:
        logger.exception(
            "OP_STATE_FETCH_ERROR elapsed_ms=%.1f",
            (perf_counter() - started) * 1000.0,
        )
        raise

