def create_user(full_name: str, username: str, password: str, question: str, answer: str, role: str = ROLE_AUX):
    full_name = (full_name or "").strip()
    username = (username or "").strip()
    question = (question or "").strip()
    answer = (answer or "").strip()
    if not full_name or not username or not password or not question or not answer: raise ValueError("Todos los campos son obligatorios.")
    if len(password) < 4: raise ValueError("La contraseña debe tener al menos 4 caracteres.")
    pwd_hash, pwd_salt = hash_secret(password)
    ans_hash, ans_salt = hash_secret(answer.casefold())
    with db_connect() as con:
        con.execute("""INSERT INTO users(full_name, username, role, password_hash, password_salt, security_question, security_answer_hash, security_answer_salt, is_active, created_at) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", (full_name, username, role, pwd_hash, pwd_salt, question, ans_hash, ans_salt, 1, now_str()))

def authenticate_user(username: str, password: str):
    with db_connect() as con:
        cur = con.execute("SELECT * FROM users WHERE username=%s", ((username or "").strip(),))
        row = cur.fetchone()
        if not row: return None
        if int(row["is_active"]) != 1: return None
        if not verify_secret(password or "", row["password_hash"], row["password_salt"]): return None
        con.execute("UPDATE users SET last_login=%s WHERE id=%s", (now_str(), row["id"]))
        return dict(row)


def verify_user_credentials(username: str, password: str):
    """Revalida credenciales sin alterar last_login ni el estado de sesión."""
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM users WHERE username=%s",
            ((username or "").strip(),),
        ).fetchone()
    if not row or int(row["is_active"]) != 1:
        return None
    if not verify_secret(
        password or "",
        row["password_hash"],
        row["password_salt"],
    ):
        return None
    return dict(row)

def get_user(username: str):
    with db_connect() as con:
        cur = con.execute("SELECT * FROM users WHERE username=%s", ((username or "").strip(),))
        row = cur.fetchone()
        return dict(row) if row else None

def list_users():
    with db_connect() as con:
        cur = con.execute("SELECT id, full_name, username, role, is_active, created_at, last_login FROM users ORDER BY role DESC, username")
        return [dict(r) for r in cur.fetchall()]


def list_active_system_users() -> list[dict]:
    """Return the enabled user catalogue used by login and user management.

    Admission configuration deliberately reads the same ``users`` table as
    the main application.  It must not depend on operational sessions,
    PRIMARY leases, heartbeats, or the V15 local turn mirror.  The result is a
    display catalogue only; admission write permissions remain enforced by
    the operational service.
    """
    started = time.perf_counter()
    logger = logging.getLogger("hospital.admission.config")
    logger.info(
        "CONFIG_USERS_QUERY_START elapsed_ms=0.0 thread=%s",
        threading.current_thread().name,
    )
    try:
        with db_connect() as con:
            con.execute("SET LOCAL statement_timeout = '4000ms'")
            rows = con.execute(
                """SELECT id,username,full_name,role,is_active
                     FROM users
                    WHERE is_active=1
                    ORDER BY LOWER(COALESCE(full_name,'')),LOWER(username),id"""
            ).fetchall()
        users = []
        for row in rows:
            user = dict(row)
            username = str(user.get("username") or "").strip()
            if not username:
                continue
            user["user_id"] = str(user.get("id") or "")
            user["display_name"] = str(user.get("full_name") or username).strip()
            user["enabled"] = bool(user.get("is_active"))
            users.append(user)
        logger.info(
            "CONFIG_USERS_QUERY_DONE elapsed_ms=%.1f count=%s thread=%s",
            (time.perf_counter() - started) * 1000.0,
            len(users),
            threading.current_thread().name,
        )
        return users
    except Exception:
        logger.exception(
            "CONFIG_USERS_QUERY_ERROR elapsed_ms=%.1f thread=%s",
            (time.perf_counter() - started) * 1000.0,
            threading.current_thread().name,
        )
        raise


def list_assignable_admission_representatives() -> list[dict]:
    """Compatibility alias for integrations that still use the old name.

    The current configuration UI intentionally presents every enabled system
    user.  Authorization happens only when the administrator commits a
    representative change.
    """
    return list_active_system_users()

