_OFFLINE_AUTH_CACHE = OfflineAuthCache()


def list_login_usernames() -> list[str]:
    device_id, _device_name = _local_device_identity()
    if not CENTRAL_OFFLINE_BOOT:
        try:
            return list_usernames()
        except Exception as exc:
            if not is_temporary_connection_error(exc):
                raise
    return _OFFLINE_AUTH_CACHE.list_valid_usernames(device_id)


def authenticate_user_for_login(username: str, password: str):
    """Autentica online y renueva el verificador; offline solo usa ese device."""
    device_id, _device_name = _local_device_identity()
    if not CENTRAL_OFFLINE_BOOT:
        try:
            user = _run_with_fresh_pool_after_read_only(
                lambda: authenticate_user(username, password),
                stage="LOGIN_AUTHENTICATION",
            )
        except Exception as exc:
            if not is_temporary_connection_error(exc):
                raise
        else:
            if user:
                _OFFLINE_AUTH_CACHE.store_online_auth(
                    user, password, device_id
                )
            return user
    return _OFFLINE_AUTH_CACHE.authenticate(
        username, password, device_id
    )

