SESSION_TIMEOUT_SECONDS = IDLE_TIMEOUT_MINUTES * 60
SESSION_HEARTBEAT_TIMEOUT_SECONDS = 180
MAX_ACTIVE_SESSION_DEVICES = 2
_LOCAL_SESSION_MUTEX_HANDLES = {}


class ActiveUserSessionError(RuntimeError):
    def __init__(self, sessions):
        if isinstance(sessions, dict):
            sessions = [sessions]
        self.sessions = [dict(session or {}) for session in (sessions or [])]
        self.session = self.sessions[0] if self.sessions else {}
        super().__init__(
            "Este usuario ya tiene 2 sesiones activas en otras computadoras."
        )

    def user_message(self) -> str:
        lines = [
            "Este usuario ya tiene 2 sesiones activas en otras computadoras. "
            "Cierre una sesión antes de continuar."
        ]
        for index, session in enumerate(self.sessions[:2], 1):
            device = str(session.get("device_name") or "Equipo no identificado")
            login_at = str(session.get("login_at") or "No disponible")
            last_seen = str(session.get("last_seen") or "No disponible")
            lines.extend([
                "",
                f"Equipo {index}: {device}",
                f"Hora de inicio: {login_at}",
                f"Última actividad: {last_seen}",
            ])
        return "\n".join(lines)


class LocalActiveUserSessionError(RuntimeError):
    def __init__(self):
        super().__init__(
            "Este usuario ya tiene el sistema abierto en esta computadora."
        )


def _local_session_mutex_name(username: str, device_id: str) -> str:
    raw = f"{str(username or '').strip().casefold()}|{device_id}"
    digest = hashlib.sha256(raw.encode("utf-8")).hexdigest()
    return f"Local\\HospitalFacturacion-{digest}"


def acquire_local_session_mutex(
    username: str,
    device_id: str,
    session_id: str,
) -> bool:
    """Reserva la ejecución local; Windows libera el mutex tras un cierre abrupto."""
    if os.name != "nt":
        key = _local_session_mutex_name(username, device_id)
        if key in _LOCAL_SESSION_MUTEX_HANDLES:
            return False
        _LOCAL_SESSION_MUTEX_HANDLES[session_id] = key
        return True
    kernel32 = ctypes.windll.kernel32
    kernel32.CreateMutexW.restype = ctypes.c_void_p
    handle = kernel32.CreateMutexW(
        None, False, _local_session_mutex_name(username, device_id)
    )
    if not handle:
        raise OSError("No se pudo reservar la sesión local.")
    already_exists = int(kernel32.GetLastError()) == 183
    if already_exists:
        kernel32.CloseHandle(ctypes.c_void_p(handle))
        return False
    _LOCAL_SESSION_MUTEX_HANDLES[session_id] = handle
    return True


def release_local_session_mutex(session_id: str):
    handle = _LOCAL_SESSION_MUTEX_HANDLES.pop(str(session_id or ""), None)
    if handle is None:
        return
    if os.name == "nt":
        ctypes.windll.kernel32.CloseHandle(ctypes.c_void_p(handle))


def _local_device_identity() -> tuple[str, str]:
    """Obtiene un ID local estable; no conserva usuario ni sesión."""
    device_name = str(
        os.environ.get("COMPUTERNAME")
        or os.environ.get("HOSTNAME")
        or "Equipo Windows"
    ).strip()[:160]
    device_dir = (
        Path(os.environ.get("LOCALAPPDATA") or Path.home())
        / "HospitalProvincial"
        / "FacturacionMedica"
    )
    device_file = device_dir / "device_id"
    try:
        device_dir.mkdir(parents=True, exist_ok=True)
        device_id = (
            device_file.read_text(encoding="utf-8").strip()
            if device_file.exists()
            else ""
        )
        if not re.fullmatch(r"[A-Za-z0-9_-]{16,80}", device_id):
            device_id = uuid.uuid4().hex
            device_file.write_text(device_id, encoding="utf-8")
    except Exception:
        device_id = hashlib.sha256(
            f"{device_name}|{os.environ.get('USERNAME', '')}".encode("utf-8")
        ).hexdigest()[:32]
    return device_id, device_name


def _database_now_str(con) -> str:
    return str(
        con.execute(
            "SELECT TO_CHAR(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')"
        ).fetchone()[0]
    )


def _expire_stale_active_sessions(con, username: str = "") -> int:
    params = [_database_now_str(con)]
    user_condition = ""
    if username:
        user_condition = " AND LOWER(BTRIM(username))=LOWER(BTRIM(%s))"
        params.append(username)
    params.append(int(SESSION_HEARTBEAT_TIMEOUT_SECONDS))
    cursor = con.execute(
        f"""UPDATE active_sessions
            SET is_active=0,
                logout_at=%s,
                logout_reason='HEARTBEAT_EXPIRED'
            WHERE is_active=1
              {user_condition}
              AND (
                    last_seen IS NULL
                    OR last_seen !~ '^\\d{{4}}-\\d{{2}}-\\d{{2}} '
                    OR last_seen::timestamp
                       < LOCALTIMESTAMP - (%s * INTERVAL '1 second')
              )""",
        tuple(params),
    )
    return int(cursor.rowcount or 0)


def request_remote_logout(
    username: str,
    requested_by: str,
    reason: str = "Sesión cerrada",
    session_id: str = "",
    *,
    close_all: bool = False,
):
    username = (username or "").strip()
    requested_by = (requested_by or "Sistema").strip()
    session_id = (session_id or "").strip()
    if not username:
        raise ValueError("Usuario inválido para cerrar sesión.")
    with db_connect() as con:
        con.execute(
            "SELECT pg_advisory_xact_lock(hashtext(LOWER(BTRIM(%s))))",
            (username,),
        )
        _expire_stale_active_sessions(con, username)
        if close_all:
            active_rows = con.execute(
                """SELECT session_id,device_id
                   FROM active_sessions
                   WHERE LOWER(BTRIM(username))=LOWER(BTRIM(%s))
                     AND is_active=1
                   ORDER BY last_seen DESC
                   FOR UPDATE""",
                (username,),
            ).fetchall()
        elif session_id:
            active_rows = con.execute(
                """SELECT session_id,device_id
                   FROM active_sessions
                   WHERE session_id=%s
                     AND LOWER(BTRIM(username))=LOWER(BTRIM(%s))
                     AND is_active=1
                   FOR UPDATE""",
                (session_id, username),
            ).fetchall()
        else:
            active_rows = con.execute(
                """SELECT session_id,device_id
                   FROM active_sessions
                   WHERE LOWER(BTRIM(username))=LOWER(BTRIM(%s))
                     AND is_active=1
                   ORDER BY last_seen DESC
                   LIMIT 1
                   FOR UPDATE""",
                (username,),
            ).fetchall()
        if not active_rows:
            raise ValueError("Ese usuario no tiene una sesión activa.")
        target_session_ids = [str(row["session_id"]) for row in active_rows]
        target_devices = [
            (str(row["session_id"]), str(row["device_id"] or ""))
            for row in active_rows
        ]
        operational_service = OperationalSessionService(db_connect)
        for closed_session_id, closed_device_id in target_devices:
            if closed_device_id:
                operational_service.release_login_session(
                    device_id=closed_device_id,
                    login_session_id=closed_session_id,
                    reason="CIERRE_REMOTO",
                    connection=con,
                )
        con.execute(
            """UPDATE active_sessions
               SET is_active=0,logout_at=%s,logout_reason=%s
               WHERE session_id=ANY(%s) AND is_active=1""",
            (
                _database_now_str(con),
                str(reason or "CIERRE_REMOTO")[:200],
                target_session_ids,
            ),
        )
    return target_session_ids if close_all else target_session_ids[0]

