def make_session_id() -> str:
    return base64.urlsafe_b64encode(os.urandom(18)).decode("ascii").rstrip("=")

def register_active_session(
    username: str,
    session_id: str,
    *,
    device_id: str = "",
    device_name: str = "",
    return_details: bool = False,
):
    username = (username or "").strip()
    session_id = (session_id or "").strip()
    if not username or not session_id:
        raise ValueError("Usuario o sesión inválidos.")
    if not device_id or not device_name:
        local_device_id, local_device_name = _local_device_identity()
        device_id = device_id or local_device_id
        device_name = device_name or local_device_name
    with db_connect() as con:
        con.execute(
            "SELECT pg_advisory_xact_lock(hashtext(LOWER(BTRIM(%s))))",
            (username,),
        )
        prior_same_device = con.execute(
            """SELECT session_id
               FROM active_sessions
               WHERE LOWER(BTRIM(username))=LOWER(BTRIM(%s))
                 AND device_id=%s
                 AND is_active=1
               ORDER BY last_seen DESC
               LIMIT 1
               FOR UPDATE""",
            (username, device_id),
        ).fetchone()
        _expire_stale_active_sessions(con, username)
        same_device = con.execute(
            """SELECT session_id
               FROM active_sessions
               WHERE LOWER(BTRIM(username))=LOWER(BTRIM(%s))
                 AND device_id=%s
                 AND is_active=1
               ORDER BY last_seen DESC
               LIMIT 1
               FOR UPDATE""",
            (username, device_id),
        ).fetchone()
        stamp = _database_now_str(con)
        recovered_same_device = bool(
            prior_same_device
            and str(prior_same_device["session_id"]) != session_id
        )
        if same_device and str(same_device["session_id"]) != session_id:
            con.execute(
                """UPDATE active_sessions
                   SET is_active=0,logout_at=%s,
                       logout_reason='REPLACED_SAME_DEVICE'
                   WHERE session_id=%s AND is_active=1""",
                (stamp, str(same_device["session_id"])),
            )

        active_devices = [
            dict(row)
            for row in con.execute(
                """SELECT session_id,device_id,device_name,login_at,last_seen
                   FROM active_sessions
                   WHERE LOWER(BTRIM(username))=LOWER(BTRIM(%s))
                     AND is_active=1
                     AND device_id<>%s
                   ORDER BY last_seen DESC
                   FOR UPDATE""",
                (username, device_id),
            ).fetchall()
        ]
        if len(active_devices) >= MAX_ACTIVE_SESSION_DEVICES:
            raise ActiveUserSessionError(active_devices)
        con.execute(
            """
            INSERT INTO active_sessions(
                username,session_id,device_id,device_name,
                login_at,last_seen,is_active,logout_at,logout_reason
            )
            VALUES(%s,%s,%s,%s,%s,%s,1,NULL,NULL)
            ON CONFLICT(session_id) DO UPDATE SET
                username=EXCLUDED.username,
                device_id=EXCLUDED.device_id,
                device_name=EXCLUDED.device_name,
                login_at=EXCLUDED.login_at,
                last_seen=EXCLUDED.last_seen,
                is_active=1,
                logout_at=NULL,
                logout_reason=NULL
            """,
            (username, session_id, device_id, device_name, stamp, stamp)
        )
        con.execute(
            """UPDATE session_control
               SET force_logout_at=NULL,requested_by=NULL,reason=NULL
               WHERE LOWER(BTRIM(username))=LOWER(BTRIM(%s))""",
            (username,),
        )
    details = {
        "session_id": session_id,
        "device_id": device_id,
        "device_name": device_name,
        "recovered_same_device": recovered_same_device,
    }
    return details if return_details else session_id

def heartbeat_active_session(username: str, session_id: str):
    session_id = (session_id or "").strip()
