def check_session_health(username: str, session_id: str) -> dict:
    """Heartbeat, remote logout and shared pricing version in one connection."""
    session_id = str(session_id or "").strip()
    if not session_id:
        return {"alive": False, "logout_reason": "Sesión inválida"}
    with db_connect() as con:
        stamp = _database_now_str(con)
        row = con.execute(
            """WITH heartbeat AS (
                   UPDATE active_sessions SET last_seen=%s
                   WHERE session_id=%s AND is_active=1
                   RETURNING is_active
               ), session_state AS (
                   SELECT is_active,logout_reason FROM active_sessions
                   WHERE session_id=%s LIMIT 1
               ), operational AS (
                   SELECT operational_session_id,operational_source_id,turn_id,
                          generation,active_user_id,active_username,
                          active_user_display_name
                   FROM admission_operational_sessions
                   WHERE status='ACTIVE' ORDER BY updated_at DESC LIMIT 1
               ), pricing AS (
                   SELECT numeric_value,version FROM billing_pricing_settings
                   WHERE setting_key=%s
               ), honorarium_settings AS (
                   SELECT COALESCE(
                       JSONB_AGG(
                           JSONB_BUILD_OBJECT(
                               'ars_id',id,
                               'ars_name',nombre,
                               'suppress_honorarium_prompt',suppress_honorarium_prompt,
                               'updated_at',COALESCE(
                                   honorarium_prompt_updated_at,TO_TIMESTAMP(0)
                               )
                           ) ORDER BY nombre
                       ),
                       '[]'::JSONB
                   ) AS settings
                   FROM ars WHERE is_active=1
               )
               SELECT EXISTS(SELECT 1 FROM heartbeat) AS alive,
                      (SELECT logout_reason FROM session_state) AS logout_reason,
                      (SELECT row_to_json(operational) FROM operational) AS operational_context,
                      COALESCE((SELECT numeric_value FROM pricing),35.00) AS markup,
                      COALESCE((SELECT version FROM pricing),0) AS markup_version,
                      (SELECT settings FROM honorarium_settings) AS honorarium_settings""",
            (stamp, session_id, session_id, MEDICATION_MARKUP_SETTING_KEY),
        ).fetchone()
    data = dict(row or {})
    operational_data = dict(data.get("operational_context") or {})
    return {
        "alive": bool(data.get("alive")),
        "logout_reason": str(data.get("logout_reason") or ""),
        "active_user_display": str(
            operational_data.get("active_user_display_name")
            or operational_data.get("active_username") or ""
        ),
        "operational_context": operational_data,
        "medication_markup_percent": (
            float(data.get("markup") or DEFAULT_MEDICATION_MARKUP_PERCENT)
        ),
        "medication_markup_version": int(data.get("markup_version") or 0),
        "honorarium_settings": list(data.get("honorarium_settings") or []),
    }

