def get_active_sessions_map(
    max_age_seconds: int = SESSION_HEARTBEAT_TIMEOUT_SECONDS,
) -> dict:
    active = {}
    with db_connect() as con:
        if int(max_age_seconds) == int(SESSION_HEARTBEAT_TIMEOUT_SECONDS):
            _expire_stale_active_sessions(con)
        cur = con.execute(
            """SELECT username,session_id,device_id,device_name,login_at,last_seen
               FROM active_sessions
               WHERE is_active=1
               ORDER BY last_seen DESC"""
        )
        rows = [dict(r) for r in cur.fetchall()]

    for row in rows:
        username = row.get("username") or ""
        last_seen_raw = row.get("last_seen") or ""
        try:
            last_seen_dt = datetime.strptime(str(last_seen_raw), "%Y-%m-%d %H:%M:%S")
        except Exception:
            last_seen_dt = datetime.min

        if last_seen_dt < datetime.now() - timedelta(seconds=int(max_age_seconds)):
            continue
        key = str(username)
        candidate = {
            "session_id": row.get("session_id") or "",
            "device_id": row.get("device_id") or "",
            "device_name": row.get("device_name") or "",
            "login_at": row.get("login_at") or "",
            "last_seen": last_seen_raw,
        }
        current = active.get(key)
        if current is None or candidate["last_seen"] > current["last_seen"]:
            active[key] = candidate

    return active


