def ars_list():
    with db_connect() as con:
        cur = con.execute(
            "SELECT nombre FROM ars "
            "WHERE is_active=1 AND COALESCE(billing_enabled,TRUE)=TRUE "
            "ORDER BY nombre"
        )
        names = {
            str(r["nombre"] or "").strip()
            for r in cur.fetchall()
            if medication_ars_is_selectable(r["nombre"])
        }
    try:
        names.update(
            name
            for name in AdmissionReadOnlyRepository().list_canonical_ars()
            if medication_ars_is_selectable(name)
        )
    except AdmissionBridgeError as exc:
        write_runtime_log(f"Catálogo ARS de Admisión no disponible: {exc}")
    return sorted(
        (name for name in names if medication_ars_is_selectable(name)),
        key=str.casefold,
    )


class HonorariumPromptSettingsCache:
    """Thread-safe projection of global per-ARS suppression exceptions."""

    def __init__(self):
        self._lock = threading.RLock()
        self._by_id = {}
        self._by_name = {}
        self._version = ""

    def update(self, rows) -> None:
        by_id = {}
        by_name = {}
        versions = []
        for raw in rows or ():
            row = dict(raw or {})
            ars_id = int(row.get("ars_id") or row.get("id") or 0)
            name = str(row.get("ars_name") or row.get("nombre") or "").strip()
            suppressed = bool(row.get("suppress_honorarium_prompt"))
            value = {
                "ars_id": ars_id,
                "ars_name": name,
                "suppress_honorarium_prompt": suppressed,
            }
            if ars_id:
                by_id[ars_id] = value
            if name:
                by_name[remove_accents(name)] = value
            versions.append(str(row.get("updated_at") or ""))
        with self._lock:
            self._by_id = by_id
            self._by_name = by_name
            self._version = max(versions, default="")

    def value(self, *, ars_id=0, ars_name=""):
        with self._lock:
            row = self._by_id.get(int(ars_id or 0))
            if row is None:
                row = self._by_name.get(remove_accents(str(ars_name or "")))
            if row is None:
                return None
            return bool(row.get("suppress_honorarium_prompt"))

    def suppressed(self, *, ars_id=0, ars_name="") -> bool:
        return bool(self.value(ars_id=ars_id, ars_name=ars_name))

    def rows(self) -> list[dict]:
        with self._lock:
            return [dict(row) for row in self._by_id.values()]


HONORARIUM_PROMPT_SETTINGS = HonorariumPromptSettingsCache()


def should_show_honorarium_prompt(ars_id, receipt_context) -> bool:
    """Resolve the prompt entirely from the loaded receipt/catalog caches."""
    ars_name = str(getattr(receipt_context, "current_ars", "") or "").strip()
    if not ars_name:
        return False
    honorariums = dict(
        (getattr(receipt_context, "ars_cache", {}) or {}).get("Honorarios") or {}
    )
    if not honorariums:
        return False
    if receipt_context.cart_has_category("Honorarios"):
        return False
    prompt_key = int(ars_id or 0) or remove_accents(ars_name)
    if prompt_key in getattr(receipt_context, "_honorarium_prompted_ars", set()):
        return False
    suppressed = HONORARIUM_PROMPT_SETTINGS.value(
        ars_id=ars_id,
        ars_name=ars_name,
    )
    if suppressed is None:
        suppressed = bool(
            getattr(
                receipt_context,
                "_current_honorarium_prompt_suppressed",
                False,
            )
        )
    return not suppressed


def load_ars_honorarium_prompt_settings() -> list[dict]:
    with db_connect() as con:
        rows = con.execute(
            """SELECT id AS ars_id,nombre AS ars_name,
                      suppress_honorarium_prompt,
                      COALESCE(honorarium_prompt_updated_at,TO_TIMESTAMP(0)) AS updated_at
                 FROM ars
                WHERE is_active=1
                ORDER BY nombre"""
        ).fetchall()
    result = [dict(row) for row in rows]
    HONORARIUM_PROMPT_SETTINGS.update(result)
    return result


def save_ars_honorarium_prompt_settings(changes: dict, current_user: dict) -> list[dict]:
    if not user_is_admin(current_user):
        raise PermissionError(
            "Solo el Administrador puede modificar las excepciones de Honorarios por ARS."
        )
    normalized = {int(key): bool(value) for key, value in dict(changes or {}).items()}
    username = str(current_user.get("username") or "Sistema")
    with db_connect() as con:
        rows = con.execute(
            """SELECT id,nombre,suppress_honorarium_prompt
                 FROM ars
                WHERE id=ANY(%s) AND is_active=1
                ORDER BY id FOR UPDATE""",
            (list(normalized),),
        ).fetchall()
        for raw in rows:
            row = dict(raw)
            ars_id = int(row["id"])
            old_value = bool(row.get("suppress_honorarium_prompt"))
            new_value = normalized[ars_id]
            if old_value == new_value:
                continue
            con.execute(
                """UPDATE ars
                      SET suppress_honorarium_prompt=%s,
                          honorarium_prompt_enabled=NOT %s,
                          honorarium_prompt_updated_at=NOW(),
                          honorarium_prompt_updated_by=%s
                    WHERE id=%s""",
                (new_value, new_value, username, ars_id),
            )
            _insert_action_history(
                con,
                username,
                "ARS_HONORARIUM_PROMPT_SUPPRESSION_CHANGED",
                json.dumps(
                    {
                        "admin_user_id": current_user.get("user_id")
                        or current_user.get("id"),
                        "ars_id": ars_id,
                        "ars_name": str(row.get("nombre") or ""),
                        "old_suppressed": old_value,
                        "new_suppressed": new_value,
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                ),
                module="Facturación",
                entity_type="ars_billing_setting",
                entity_id=str(ars_id),
                role=str(current_user.get("role") or ""),
                ars_name=str(row.get("nombre") or ""),
            )
        refreshed = con.execute(
            """SELECT id AS ars_id,nombre AS ars_name,
                      suppress_honorarium_prompt,
                      COALESCE(honorarium_prompt_updated_at,TO_TIMESTAMP(0)) AS updated_at
                 FROM ars WHERE is_active=1 ORDER BY nombre"""
        ).fetchall()
    result = [dict(row) for row in refreshed]
    HONORARIUM_PROMPT_SETTINGS.update(result)
    return result


def list_monthly_ars_options():
    """Combina el catálogo vigente con las ARS realmente guardadas en recibos."""
    names = list(ars_list())
    with db_connect() as con:
        names.extend(
            str(row["ars"] or "").strip()
            for row in con.execute(
                """SELECT DISTINCT ars FROM recibos
                   WHERE is_deleted=0
                     AND NULLIF(TRIM(COALESCE(ars,'')),'') IS NOT NULL
                   ORDER BY ars"""
            ).fetchall()
        )
    unique = {}
    for name in names:
        normalized = normalize_monthly_ars_name(name)
        if normalized and monthly_ars_is_selectable(name):
            unique.setdefault(normalized, str(name).strip())
    return sorted(unique.values(), key=str.casefold)

