def load_universal_catalog_admin_data() -> dict:
    with db_connect() as con:
        items = con.execute(
            """SELECT categoria,nombre,precio,is_active
               FROM universal_items
               WHERE categoria IN ('Medicamentos','Materiales')
               ORDER BY categoria,nombre"""
        ).fetchall()
        setting = con.execute(
            """SELECT numeric_value,version FROM billing_pricing_settings
               WHERE setting_key=%s""",
            (MEDICATION_MARKUP_SETTING_KEY,),
        ).fetchone()
    if setting:
        update_medication_markup_cache(setting["numeric_value"], setting["version"])
    return {
        "markup": get_medication_markup_percent(),
        "items": [dict(row) for row in items],
    }


def mutate_universal_catalog(
    action: str,
    category: str,
    name: str,
    *,
    current_user: dict,
    new_name: str = "",
    base_price=0.0,
) -> None:
    if not user_is_admin(current_user):
        raise PermissionError("Solo el administrador puede gestionar el catálogo.")
    if category not in UNIVERSAL_CATEGORIES:
        raise ValueError("Categoría universal inválida.")
    action = str(action or "").upper()
    name = str(name or "").strip()
    new_name = str(new_name or name).strip()
    username = str(current_user.get("username") or "Sistema")
    device_id, device_name = _local_device_identity()
    with db_connect() as con:
        if action == "UPSERT":
            con.execute(
                """INSERT INTO universal_items(categoria,nombre,precio,is_active)
                   VALUES(%s,%s,%s,1)
                   ON CONFLICT(categoria,nombre) DO UPDATE SET
                       precio=EXCLUDED.precio,is_active=1""",
                (category, new_name, float(base_price)),
            )
        elif action == "EDIT":
            con.execute(
                """UPDATE universal_items SET nombre=%s,precio=%s
                   WHERE categoria=%s AND nombre=%s""",
                (new_name, float(base_price), category, name),
            )
        elif action in {"ACTIVATE", "DEACTIVATE", "DELETE"}:
            active = 1 if action == "ACTIVATE" else 0
            con.execute(
                """UPDATE universal_items SET is_active=%s
                   WHERE categoria=%s AND nombre=%s""",
                (active, category, name),
            )
        else:
            raise ValueError("Acción de catálogo inválida.")
        details = (
            f"{category}: {name or new_name}"
            + (f" → {new_name} · precio base RD$ {float(base_price):,.2f}" if action in {"UPSERT", "EDIT"} else "")
            + f" · Dispositivo {device_name} ({device_id})"
        )
        _insert_action_history(
            con, username, f"CATALOG_{action}", details,
            module="Facturación", entity_type="catálogo_universal",
            entity_id=f"{category}|{new_name or name}",
            role=current_user.get("role", ""), ars_name="CATÁLOGO UNIVERSAL",
        )

def _ensure_ars(nombre_ars: str):
    nombre_ars = require_medication_ars(nombre_ars)
    with db_connect() as con: con.execute("INSERT INTO ars(nombre, sala_emergencia, consulta_price, is_active, billing_enabled) VALUES(%s, COALESCE((SELECT sala_emergencia FROM ars WHERE nombre=%s), 0), COALESCE((SELECT consulta_price FROM ars WHERE nombre=%s), 0), 1, TRUE) ON CONFLICT(nombre) DO UPDATE SET is_active=1, billing_enabled=TRUE", (nombre_ars, nombre_ars, nombre_ars))

def get_ars_items(categoria: str, nombre_ars: str) -> dict:
    if not medication_ars_is_selectable(nombre_ars):
        return {}
    with db_connect() as con:
        cur = con.execute("""SELECT ai.nombre, ai.precio FROM ars_items ai JOIN ars a ON a.id = ai.ars_id WHERE ai.categoria=%s AND a.nombre=%s AND ai.is_active=1 ORDER BY ai.nombre""", (categoria, nombre_ars))
        return {r["nombre"]: float(r["precio"]) for r in cur.fetchall()}


class ARSRuntimeCache:
    """Thread-safe, per-ARS runtime data. Reads never perform database I/O."""

    def __init__(self):
        self._lock = threading.RLock()
        self._entries = {}

    def get(self, ars_name: str):
        key = str(ars_name or "").strip()
        with self._lock:
            value = self._entries.get(key)
            return copy.deepcopy(value) if value is not None else None

    def put(self, ars_name: str, value: dict):
        key = str(ars_name or "").strip()
        if not key:
            return
        with self._lock:
            self._entries[key] = copy.deepcopy(dict(value or {}))

    def invalidate(self, ars_name: str = ""):
        key = str(ars_name or "").strip()
        with self._lock:
            if key:
                self._entries.pop(key, None)
            else:
                self._entries.clear()


ARS_RUNTIME_CACHE = ARSRuntimeCache()


def load_ars_runtime_data(ars_name: str) -> dict:
    """Load prices and all four ARS catalogs in one PostgreSQL round-trip."""
    ars_name = require_medication_ars(ars_name)
    categories = {category: {} for category in ARS_CATEGORIES}
    with db_connect() as con:
        rows = con.execute(
            """SELECT a.id AS ars_id,a.sala_emergencia,a.consulta_price,
                      a.suppress_honorarium_prompt,
                      ai.categoria,ai.nombre AS item_name,ai.precio AS item_price
               FROM ars a
               LEFT JOIN ars_items ai ON ai.ars_id=a.id AND ai.is_active=1
               WHERE a.nombre=%s AND a.is_active=1
               ORDER BY ai.categoria,ai.nombre""",
            (ars_name,),
        ).fetchall()
    if not rows:
        return {
            "ars_id": 0, "sala_emergencia": 0.0, "consulta_price": 0.0,
            "suppress_honorarium_prompt": False,
            "catalogs": categories, "loaded_at": time.time(),
        }
    for row in rows:
        category = str(row.get("categoria") or "")
        item_name = str(row.get("item_name") or "")
        if category in categories and item_name:
            categories[category][item_name] = float(row.get("item_price") or 0.0)
    first = rows[0]
    return {
        "ars_id": int(first.get("ars_id") or 0),
        "sala_emergencia": float(first.get("sala_emergencia") or 0.0),
        "consulta_price": float(first.get("consulta_price") or 0.0),
        "suppress_honorarium_prompt": bool(
            first.get("suppress_honorarium_prompt")
        ),
        "catalogs": categories,
        "loaded_at": time.time(),
    }

