_SHIFT_REPORT_EXCLUDED_ARS = {
    normalize_key("SENASA SUBSIDIADO"),
    normalize_key("BANCO CENTRAL"),
    normalize_key("YUNEN"),
}
_SHIFT_INVALID_AUTHORIZATIONS = {
    "", "NA", "NOAPLICA", "PENDIENTE", "NINGUNO", "NINGUNA", "SINNUMERO",
    "NOAUTORIZADO", "PORASIGNAR", "0", "0000",
}


def _valid_shift_authorization(value) -> bool:
    return normalize_key(value) not in _SHIFT_INVALID_AUTHORIZATIONS


def _insert_shift_closure_header(con, event: AdmissionShiftClosure) -> None:
    con.execute(
        """INSERT INTO billing_shift_closures(
               source_instance_id,turn_id,event_uuid,operational_day_id,
               operational_date,started_at,scheduled_end_at,closed_at,
               representative,shift_type,actor,actor_role,admission_session_id,
               received_at,closed_by
           ) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
           ON CONFLICT(source_instance_id,turn_id) DO NOTHING""",
        (
            event.source_instance_id, event.turn_id, event.event_uuid,
            event.operational_day_id, event.operational_date, event.started_at,
            event.scheduled_end_at, event.closed_at, event.representative,
            event.shift_type, event.actor, event.actor_role, event.session_id,
            now_str(), event.actor or event.representative,
        ),
    )


