def get_ars_billing_profile(ars: str) -> dict:
    ars = require_medication_ars(ars)
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM billing_ars_profiles WHERE ars=%s",
            (ars,),
        ).fetchone()
    if row:
        return dict(row)
    defaults = {
        "ars": ars,
        "display_name": ars,
        "ars_rnc": "",
        "ars_address": "",
        "ars_phone": "",
        "ars_email": "",
        "administrative_notes": "",
        **DEFAULT_PROVIDER_PROFILE,
    }
    defaults.update(PRIVATE_ARS_PROFILE_DEFAULTS.get(ars.upper(), {}))
    return defaults


def save_ars_billing_profile(ars: str, values: dict, user: dict) -> None:
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede editar perfiles de ARS.")
    ars = require_medication_ars(ars)
    username = str((user or {}).get("username") or "Sistema")
    stamp = now_str()
    profile = get_ars_billing_profile(ars)
    for key in (
        "display_name", "ars_rnc", "ars_address", "ars_phone", "ars_email",
        "administrative_notes", "provider_code",
        "provider_name", "provider_rnc", "director_name", "director_title",
        "service_description", "specialty_default",
    ):
        if key in values:
            profile[key] = str(values.get(key) or "").strip()
    if not profile["display_name"]:
        profile["display_name"] = ars
    email = str(profile.get("ars_email") or "").strip()
    if email and not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
        raise ValueError("El correo de la ARS no tiene un formato válido.")
    with db_connect() as con:
        con.execute(
            """INSERT INTO billing_ars_profiles(
                   ars, display_name, ars_rnc, ars_address, ars_phone, ars_email,
                   administrative_notes, provider_code,
                   provider_name, provider_rnc, director_name, director_title,
                   service_description, specialty_default, updated_at, updated_by
               ) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
               ON CONFLICT(ars) DO UPDATE SET
                   display_name=EXCLUDED.display_name,
                   ars_rnc=EXCLUDED.ars_rnc,
                   ars_address=EXCLUDED.ars_address,
                   ars_phone=EXCLUDED.ars_phone,
                   ars_email=EXCLUDED.ars_email,
                   administrative_notes=EXCLUDED.administrative_notes,
                   provider_code=EXCLUDED.provider_code,
                   provider_name=EXCLUDED.provider_name,
                   provider_rnc=EXCLUDED.provider_rnc,
                   director_name=EXCLUDED.director_name,
                   director_title=EXCLUDED.director_title,
                   service_description=EXCLUDED.service_description,
                   specialty_default=EXCLUDED.specialty_default,
                   updated_at=EXCLUDED.updated_at,
                   updated_by=EXCLUDED.updated_by""",
            (
                ars, profile["display_name"], profile["ars_rnc"],
                profile["ars_address"], profile["ars_phone"],
                profile["ars_email"], profile["administrative_notes"],
                profile["provider_code"],
                profile["provider_name"], profile["provider_rnc"],
                profile["director_name"], profile["director_title"],
                profile["service_description"], profile["specialty_default"],
                stamp, username,
            ),
        )


def create_monthly_billing_batch(
    year: int,
    month: int,
    ars: str,
    user: dict,
    notes: str = "",
):
    """Crea una fotografía editable de lo facturado hasta este instante."""
    username = str((user or {}).get("username") or "Sistema")
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede generar listados mensuales.")
    ars = str(ars or "").strip()
    if not ars:
        raise ValueError("Selecciona la ARS o el renglón SIN SEGURO.")
    if not monthly_ars_is_selectable(ars):
        raise ValueError("Esta carga inicial no incluye SENASA SUBSIDIADO.")
    profile = get_ars_billing_profile(ars)
    cutoff = now_str()
    invoice_date = datetime.now().strftime("%Y-%m-%d")
    with db_connect() as con:
        version = int(
            con.execute(
                """SELECT COALESCE(MAX(version),0)+1 AS version
                   FROM billing_batches
                   WHERE period_year=%s AND period_month=%s AND ars=%s""",
                (int(year), int(month), ars),
            ).fetchone()["version"]
        )
        batch = con.execute(
            """INSERT INTO billing_batches(
                   period_year, period_month, ars, version, status, cutoff_at,
                   created_at, created_by, notes, ars_display_name, invoice_date,
                   provider_code, provider_name, provider_rnc, ars_rnc,
                   ars_address, ars_phone, ars_email, administrative_notes,
                   director_name, director_title,
                   service_description, specialty_default
               ) VALUES(
                   %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s
               )
               RETURNING id""",
            (
                int(year), int(month), ars, version, BATCH_PENDING, cutoff,
                cutoff, username, str(notes or "").strip(),
                profile.get("display_name") or ars, invoice_date,
                profile.get("provider_code") or "",
                profile.get("provider_name") or "",
                profile.get("provider_rnc") or "",
                profile.get("ars_rnc") or "",
                profile.get("ars_address") or "",
                profile.get("ars_phone") or "",
                profile.get("ars_email") or "",
                profile.get("administrative_notes") or "",
                profile.get("director_name") or "",
                profile.get("director_title") or "DIRECTORA",
                profile.get("service_description") or "EMERGENCIA",
                profile.get("specialty_default") or "EMERGENCIOLOGÍA",
            ),
        ).fetchone()
        batch_id = int(batch["id"])
        con.execute(
            """INSERT INTO billing_batch_events(
                   batch_id, event_type, performed_at, performed_by, details
               ) VALUES(%s,'CREADO',%s,%s,%s)""",
            (
                batch_id,
                cutoff,
                username,
                json.dumps(
                    {
                        "cutoff_at": cutoff,
                        "receipts": 0,
                        "total": 0.0,
                    },
                    ensure_ascii=False,
                ),
            ),
        )
        _insert_action_history(
            con, username, "Crear listado ARS",
            f"Listado {batch_id} · {ars} · {int(month):02d}-{int(year)}",
            module="Listados ARS", entity_type="listado_ars",
            entity_id=str(batch_id), role=str((user or {}).get("role") or ""),
            created_at=cutoff,
        )
        return batch_id


def list_monthly_billing_batches(limit: int = 200):
    with db_connect() as con:
        rows = con.execute(
            """SELECT b.*,
                      CASE WHEN b.status='ENVIADO'
                           THEN COALESCE(b.sent_receipt_count,0)
                           ELSE COUNT(*) FILTER (WHERE br.included=1) END AS receipts,
                      COUNT(*) FILTER (
                          WHERE br.included=1
                            AND NULLIF(TRIM(COALESCE(br.comprobante_snapshot,'')),'')
                                IS NOT NULL
                      ) AS comprobantes,
                      CASE WHEN b.status='ENVIADO'
                           THEN COALESCE(b.sent_total,0)
                           ELSE COALESCE(SUM(br.total_snapshot) FILTER (WHERE br.included=1),0)
                      END AS total
               FROM billing_batches b
               LEFT JOIN billing_batch_receipts br ON br.batch_id=b.id
               GROUP BY b.id
               ORDER BY b.period_year DESC, b.period_month DESC, b.id DESC
               LIMIT %s""",
            (int(limit),),
        ).fetchall()
        return [dict(row) for row in rows]


def list_sent_billing_batches_report(
    *, year=None, month=None, ars="", batch_ids=None,
):
    clauses = ["status=%s"]
    params = [BATCH_SENT]
    if year is not None:
        clauses.append("sent_period_year=%s")
        params.append(int(year))
    if month is not None:
        clauses.append("sent_period_month=%s")
        params.append(int(month))
    normalized_ars = normalize_monthly_ars_name(ars)
    if normalized_ars:
        clauses.append(
            "REGEXP_REPLACE(LOWER(TRIM(sent_ars)), '\\s+', ' ', 'g')=%s"
        )
        params.append(normalized_ars)
    if batch_ids is not None:
        ids = sorted({int(value) for value in batch_ids})
        if not ids:
            return []
        clauses.append("id=ANY(%s)")
        params.append(ids)
    with db_connect() as con:
        rows = con.execute(
            f"""SELECT id,version,sent_period_year AS period_year,
                       sent_period_month AS period_month,sent_ars AS ars,
                       sent_invoice_number AS invoice_number,sent_ncf AS ncf,
                       sent_at,sent_by,sent_receipt_count AS receipt_count,
                       sent_total
                FROM billing_batches
                WHERE {' AND '.join(clauses)}
                ORDER BY sent_period_year DESC,sent_period_month DESC,
                         sent_ars,id""",
            tuple(params),
        ).fetchall()
    return [dict(row) for row in rows]


def get_monthly_billing_batch(batch_id: int):
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM billing_batches WHERE id=%s", (int(batch_id),)
        ).fetchone()
        return dict(row) if row else None


def _query_monthly_batch_receipts(con, batch_id: int, included: bool = True):
    rows = con.execute(
        """SELECT br.*, COALESCE(r.numero::text,'') AS numero,
                   COALESCE(r.nombre,br.patient_snapshot) AS nombre,
                   COALESCE(r.fecha,br.service_date_snapshot) AS fecha,
                   r.tipo_cobertura,
                   r.estado_facturacion, r.estado_facturacion_at,
                   COALESCE(r.admission_atencion_id,br.admission_attention_id)
                       AS admission_atencion_id
           FROM billing_batch_receipts br
           LEFT JOIN recibos r ON r.id=br.recibo_id
           WHERE br.batch_id=%s AND br.included=%s
           ORDER BY br.billing_date_snapshot, r.numero NULLS LAST,
                    br.admission_attention_id""",
        (int(batch_id), 1 if included else 0),
    ).fetchall()
    return [dict(row) for row in rows]


def list_monthly_batch_receipts(batch_id: int, included: bool = True):
    with db_connect() as con:
        return _query_monthly_batch_receipts(con, batch_id, included)


def _monthly_batch_export_signature(batch: dict, receipts: list[dict]) -> str:
    fiscal_keys = (
        "id", "period_year", "period_month", "ars", "version",
        "invoice_number", "ncf", "invoice_date", "ncf_expiration_date",
        "provider_code", "provider_name", "provider_rnc", "ars_rnc",
        "ars_address", "director_name", "director_title", "discount", "itbis",
    )
    receipt_keys = (
        "recibo_id", "admission_source_instance_id", "admission_attention_id",
        "patient_snapshot", "document_type_snapshot", "document_number_snapshot",
        "authorization_snapshot", "service_date_snapshot", "specialty_snapshot",
        "ars_snapshot", "comprobante_snapshot", "total_snapshot",
    )
    payload = {
        "batch": {key: batch.get(key) for key in fiscal_keys},
        "receipts": [
            {key: row.get(key) for key in receipt_keys}
            for row in sorted(
                receipts,
                key=lambda row: (
                    int(row.get("recibo_id") or 0),
                    str(row.get("admission_source_instance_id") or ""),
                    int(row.get("admission_attention_id") or 0),
                ),
            )
        ],
    }
    encoded = json.dumps(
        payload, ensure_ascii=False, sort_keys=True, default=str,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _file_sha256(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _query_available_receipts_for_batch(
    con,
    batch_id: int,
    batch: dict,
    limit: int = 500,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
):
    """Fuente transitoria: recibos guardados; no consulta Admisión."""
    if not monthly_ars_is_selectable(batch.get("ars")):
        return []
    ars_expr = _batch_ars_expression("r")
    normalized_ars = normalize_monthly_ars_name(batch.get("ars"))
    rows = con.execute(
            f"""SELECT r.id AS recibo_id, r.numero, r.nombre,
                       r.admission_nss_snapshot AS nss_snapshot,
                       r.admission_cedula_snapshot AS cedula_snapshot,
                       CASE
                           WHEN NULLIF(TRIM(COALESCE(r.admission_nss_snapshot,'')),'')
                               IS NOT NULL THEN 'NSS'
                           WHEN NULLIF(TRIM(COALESCE(r.admission_cedula_snapshot,'')),'')
                               IS NOT NULL THEN 'CÉDULA'
                           ELSE NULL
                       END AS document_type_snapshot,
                       COALESCE(
                           NULLIF(TRIM(COALESCE(r.admission_nss_snapshot,'')),''),
                           NULLIF(TRIM(COALESCE(r.admission_cedula_snapshot,'')),'')
                       ) AS document_number_snapshot,
                       NULLIF(TRIM(COALESCE(r.numero_autorizacion,'')),'') AS authorization_snapshot,
                        r.fecha AS service_date_snapshot,
                        NULLIF(TRIM(COALESCE(r.specialty_snapshot,'')),'') AS specialty_snapshot,
                        COALESCE(r.admission_source_instance_id,'LEGACY')
                            AS admission_source_instance_id,
                        r.admission_atencion_id,
                        {ars_expr} AS ars_snapshot,
                       NULL::text AS comprobante_snapshot,
                        COALESCE(r.fecha,'') AS billing_date_snapshot,
                        COALESCE(r.total,0) AS total_snapshot
                 FROM recibos r
                 WHERE r.is_deleted=0
                   AND r.estado_facturacion IN ('PENDIENTE','SIN_CLASIFICAR')
                   AND NULLIF(TRIM(COALESCE(r.ars,'')),'') IS NOT NULL
                   AND REGEXP_REPLACE(LOWER(TRIM({ars_expr})), '\\s+', ' ', 'g')=%s
                   AND (
                       %s IS NULL OR (
                           LEFT(COALESCE(r.fecha,''),10) ~ '^\\d{{4}}-\\d{{2}}-\\d{{2}}$'
                           AND LEFT(r.fecha,10)::date >= %s::date
                       )
                   )
                   AND (
                       %s IS NULL OR (
                           LEFT(COALESCE(r.fecha,''),10) ~ '^\\d{{4}}-\\d{{2}}-\\d{{2}}$'
                           AND LEFT(r.fecha,10)::date <= %s::date
                       )
                   )
                  AND NOT EXISTS(
                      SELECT 1
                      FROM billing_batch_receipts linked
                      WHERE linked.included=1 AND (
                          linked.recibo_id=r.id OR (
                              r.admission_atencion_id IS NOT NULL
                              AND linked.admission_attention_id=r.admission_atencion_id
                              AND linked.admission_source_instance_id=
                                  COALESCE(r.admission_source_instance_id,'LEGACY')
                          )
                      )
                  )
                ORDER BY
                    CASE WHEN LEFT(COALESCE(r.fecha,''),10)
                                   ~ '^\\d{{4}}-\\d{{2}}-\\d{{2}}$'
                         THEN LEFT(r.fecha,10)::date END DESC NULLS LAST,
                    r.id DESC
                LIMIT %s""",
            (
                normalized_ars,
                date_from, date_from, date_to, date_to,
                int(limit),
            ),
    ).fetchall()
    result = []
    for raw in rows:
        row = dict(raw)
        if normalize_monthly_ars_name(row.get("ars_snapshot")) != normalized_ars:
            continue
        row["candidate_key"] = f"R:{int(row['recibo_id'])}"
        row["candidate_kind"] = "RECEIPT"
        row["candidate_status"] = "POR REVISAR"
        result.append(row)
    return result


def obtener_candidatos_listado_ars(
    batch_id: int,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
    batch: dict | None = None,
    limit: int = 5000,
):
    """Fuente temporal aislada: todos los recibos históricos guardados."""
    return list_available_receipts_for_batch(
        batch_id,
        limit=limit,
        date_from=date_from,
        date_to=date_to,
        batch=batch,
    )


def list_available_receipts_for_batch(
    batch_id: int,
    limit: int = 500,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
    batch: dict | None = None,
):
    with db_connect() as con:
        if batch is None:
            row = con.execute(
                "SELECT * FROM billing_batches WHERE id=%s", (int(batch_id),)
            ).fetchone()
            batch = dict(row) if row else None
        if not batch:
            return []
        return _query_available_receipts_for_batch(
            con,
            batch_id,
            batch,
            limit,
            date_from=date_from,
            date_to=date_to,
        )


def list_available_monthly_batch_candidates(
    batch_id: int,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
    batch: dict | None = None,
    repository=None,
    limit: int = 5000,
):
    """Compatibilidad: delega en la fuente temporal de recibos históricos."""
    return obtener_candidatos_listado_ars(
        batch_id,
        date_from=date_from,
        date_to=date_to,
        batch=batch,
        limit=limit,
    )


def load_monthly_batch_workspace(
    batch_id: int,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
):
    """Carga el expediente completo con una sola conexión y consultas agrupadas."""
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM billing_batches WHERE id=%s", (int(batch_id),)
        ).fetchone()
        if not row:
            return None
        batch = dict(row)
        receipts = _query_monthly_batch_receipts(con, batch_id)
        return {
            "batch": batch,
            "receipts": receipts,
            "available": [],
            "date_from": date_from,
            "date_to": date_to,
        }


def add_receipts_to_monthly_batch(
    batch_id: int,
    receipt_ids,
    user: dict,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
    skip_ineligible: bool = False,
    return_summary: bool = False,
):
    username = str((user or {}).get("username") or "Sistema")
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede editar listados mensuales.")
    requested_ids = sorted({int(value) for value in receipt_ids})
    if not requested_ids:
        return 0
    stamp = now_str()
    with db_connect() as con:
        locked_batch = con.execute(
            "SELECT * FROM billing_batches WHERE id=%s FOR UPDATE",
            (int(batch_id),),
        ).fetchone()
        if not locked_batch or not batch_is_editable(locked_batch["status"]):
            raise ValueError("El expediente ya no está disponible para edición.")
        if not monthly_ars_is_selectable(locked_batch["ars"]):
            raise ValueError("Esta carga inicial no incluye SENASA SUBSIDIADO.")
        con.execute(
            "SELECT id FROM recibos WHERE id=ANY(%s) ORDER BY id FOR UPDATE",
            (requested_ids,),
        ).fetchall()
        linked_rows = con.execute(
            """SELECT target.id AS recibo_id,b.id,b.ars,b.period_year,
                      b.period_month,b.status
               FROM recibos target
               JOIN billing_batch_receipts br ON br.included=1 AND (
                    br.recibo_id=target.id OR (
                        target.admission_atencion_id IS NOT NULL
                        AND br.admission_attention_id=target.admission_atencion_id
                        AND br.admission_source_instance_id=
                            COALESCE(target.admission_source_instance_id,'LEGACY')
                    )
               )
               JOIN billing_batches b ON b.id=br.batch_id
               WHERE target.id=ANY(%s)
               ORDER BY target.id,b.id""",
            (requested_ids,),
        ).fetchall()
        if linked_rows and not skip_ineligible:
            linked = linked_rows[0]
            raise ValueError(
                "El recibo ya pertenece al listado "
                f"#{linked['id']} ({linked['ars']} "
                f"{linked['period_month']:02d}-{linked['period_year']}, "
                f"{batch_status_label(linked['status'])})."
            )
        candidates = {
            int(row["recibo_id"]): row
            for row in _query_available_receipts_for_batch(
                con,
                batch_id,
                dict(locked_batch),
                limit=max(5000, len(requested_ids)),
                date_from=date_from,
                date_to=date_to,
            )
            if int(row["recibo_id"]) in requested_ids
        }
        omitted_count = len(set(requested_ids) - set(candidates))
        if omitted_count and not skip_ineligible:
            raise ValueError(
                "Uno o más recibos dejaron de cumplir la ARS o el rango seleccionado."
            )
        if skip_ineligible:
            requested_ids = sorted(candidates)
        if not requested_ids:
            return {"added": 0, "omitted": omitted_count} if return_summary else 0
        values = []
        for receipt_id in requested_ids:
            receipt = candidates[receipt_id]
            values.append((
                int(batch_id), receipt_id,
                receipt.get("admission_source_instance_id"),
                receipt.get("admission_atencion_id"),
                receipt.get("nombre") or "",
                receipt.get("nss_snapshot"), receipt.get("cedula_snapshot"),
                receipt.get("document_type_snapshot"),
                receipt.get("document_number_snapshot"),
                receipt.get("authorization_snapshot"),
                receipt.get("service_date_snapshot"),
                receipt.get("specialty_snapshot"),
                receipt.get("ars_snapshot"), receipt.get("comprobante_snapshot"),
                receipt.get("billing_date_snapshot"),
                float(receipt.get("total_snapshot") or 0), stamp, username,
            ))
        with con.con.cursor() as cursor:
            upgrade_values = [
                (value[0], value[1], value[2], value[3])
                for value in values if value[3] is not None
            ]
            if upgrade_values:
                psycopg2.extras.execute_values(
                    cursor,
                    """WITH linked(batch_id,recibo_id,source_id,attention_id) AS (
                           VALUES %s
                       )
                       UPDATE billing_batch_receipts br
                       SET recibo_id=linked.recibo_id
                       FROM linked
                       WHERE br.batch_id=linked.batch_id
                         AND br.recibo_id IS NULL
                         AND br.admission_source_instance_id=linked.source_id
                         AND br.admission_attention_id=linked.attention_id""",
                    upgrade_values,
                    template="(%s,%s,%s,%s)",
                )
            psycopg2.extras.execute_values(
                cursor,
                """INSERT INTO billing_batch_receipts(
                   batch_id, recibo_id, admission_source_instance_id,
                   admission_attention_id, included, patient_snapshot,
                   nss_snapshot, cedula_snapshot, document_type_snapshot,
                   document_number_snapshot, authorization_snapshot,
                   service_date_snapshot, specialty_snapshot, ars_snapshot,
                   comprobante_snapshot, billing_date_snapshot, total_snapshot,
                   added_at, added_by, removed_at, removed_by, removal_reason
               ) VALUES %s
               ON CONFLICT(batch_id, recibo_id) WHERE recibo_id IS NOT NULL
               DO UPDATE SET
                   included=1,
                   admission_source_instance_id=EXCLUDED.admission_source_instance_id,
                   admission_attention_id=EXCLUDED.admission_attention_id,
                   patient_snapshot=EXCLUDED.patient_snapshot,
                   nss_snapshot=EXCLUDED.nss_snapshot,
                   cedula_snapshot=EXCLUDED.cedula_snapshot,
                   document_type_snapshot=EXCLUDED.document_type_snapshot,
                   document_number_snapshot=EXCLUDED.document_number_snapshot,
                   authorization_snapshot=EXCLUDED.authorization_snapshot,
                   service_date_snapshot=EXCLUDED.service_date_snapshot,
                   specialty_snapshot=EXCLUDED.specialty_snapshot,
                   ars_snapshot=EXCLUDED.ars_snapshot,
                   comprobante_snapshot=EXCLUDED.comprobante_snapshot,
                   billing_date_snapshot=EXCLUDED.billing_date_snapshot,
                   total_snapshot=EXCLUDED.total_snapshot,
                   added_at=EXCLUDED.added_at,
                   added_by=EXCLUDED.added_by,
                   removed_at=NULL, removed_by=NULL, removal_reason=NULL""",
                values,
                template="(%s,%s,%s,%s,1,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,NULL,NULL,NULL)",
            )
            event_values = [
                (int(batch_id), receipt_id, stamp, username, "")
                for receipt_id in requested_ids
            ]
            psycopg2.extras.execute_values(
                cursor,
                """INSERT INTO billing_batch_events(
                       batch_id, recibo_id, event_type, performed_at,
                       performed_by, details
                   ) VALUES %s""",
                event_values,
                template="(%s,%s,'RECIBO_AGREGADO',%s,%s,%s)",
            )
            if skip_ineligible:
                cursor.execute(
                    """INSERT INTO billing_batch_events(
                           batch_id,recibo_id,event_type,performed_at,
                           performed_by,details
                       ) VALUES(%s,NULL,'BULK_ADD_TO_BILLING_CONFIRMATION',%s,%s,%s)""",
                    (
                        int(batch_id), stamp, username,
                        json.dumps(
                            {
                                "added": len(requested_ids),
                                "omitted": omitted_count,
                                "date_from": date_from,
                                "date_to": date_to,
                                "role": normalize_role((user or {}).get("role")),
                                "device": str(os.environ.get("COMPUTERNAME") or "ESTACION"),
                                "result": "COMPLETED",
                            },
                            ensure_ascii=False,
                            sort_keys=True,
                        ),
                    ),
                )
        con.execute(
            """UPDATE billing_batches SET updated_at=%s, updated_by=%s WHERE id=%s""",
            (stamp, username, int(batch_id)),
        )
    if return_summary:
        return {"added": len(requested_ids), "omitted": omitted_count}
    return len(requested_ids)


def add_all_receipts_to_monthly_batch(
    batch_id: int,
    receipt_ids,
    user: dict,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
):
    """Agrega en lote y omite candidatos que dejaron de ser elegibles."""
    return add_receipts_to_monthly_batch(
        batch_id,
        receipt_ids,
        user,
        date_from=date_from,
        date_to=date_to,
        skip_ineligible=True,
        return_summary=True,
    )


def add_receipt_to_monthly_batch(batch_id: int, receipt_id: int, user: dict):
    return add_receipts_to_monthly_batch(batch_id, [receipt_id], user)


def add_admission_candidates_to_monthly_batch(
    batch_id: int,
    candidate_keys,
    user: dict,
    *,
    date_from: str | None = None,
    date_to: str | None = None,
    repository=None,
    skip_ineligible: bool = False,
    return_summary: bool = False,
) -> int | dict:
    """Persiste únicamente candidatos temporales de la transición de Admisión."""
    requested = {str(value) for value in candidate_keys if str(value).startswith("A:")}
    if not requested:
        return 0
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede editar listados mensuales.")
    batch = get_monthly_billing_batch(batch_id)
    if not batch or not batch_is_editable(batch):
        raise ValueError("El expediente ya no está disponible para edición.")
    fresh = list_available_monthly_batch_candidates(
        batch_id, date_from=date_from, date_to=date_to, batch=batch,
        repository=repository,
    )
    candidates = {
        str(row.get("candidate_key")): row
        for row in fresh
        if row.get("candidate_kind") == "ADMISSION"
        and str(row.get("candidate_key")) in requested
    }
    omitted_count = len(requested - set(candidates))
    if omitted_count and not skip_ineligible:
        raise ValueError(
            "Una o más atenciones ya fueron añadidas, enviadas o facturadas."
        )
    if skip_ineligible:
        requested = set(candidates)
    if not requested:
        return {"added": 0, "omitted": omitted_count} if return_summary else 0
    stamp = now_str()
    username = str((user or {}).get("username") or "Sistema")
    values = []
    events = []
    for key in sorted(requested):
        row = candidates[key]
        source = str(row["source_instance_id"])
        attention_id = int(row["attention_id"])
        values.append((
            int(batch_id), source, attention_id, row.get("nombre") or "",
            row.get("nss_snapshot"), row.get("cedula_snapshot"), "ADMISIÓN",
            row.get("document_number_snapshot"),
            row.get("authorization_snapshot"), row.get("service_date_snapshot"),
            row.get("specialty_snapshot"), row.get("ars_snapshot"),
            row.get("billing_date_snapshot"), stamp, username,
        ))
        events.append((
            int(batch_id), stamp, username,
            json.dumps(
                {"source_instance_id": source, "attention_id": attention_id},
                ensure_ascii=False,
            ),
        ))
    with db_connect() as con:
        locked = con.execute(
            "SELECT status FROM billing_batches WHERE id=%s FOR UPDATE",
            (int(batch_id),),
        ).fetchone()
        if not locked or not batch_is_editable(locked["status"]):
            raise ValueError("El expediente ya no está disponible para edición.")
        with con.con.cursor() as cursor:
            psycopg2.extras.execute_values(
                cursor,
                """INSERT INTO billing_batch_receipts(
                       batch_id,recibo_id,admission_source_instance_id,
                       admission_attention_id,included,patient_snapshot,
                       nss_snapshot,cedula_snapshot,document_type_snapshot,
                       document_number_snapshot,authorization_snapshot,
                       service_date_snapshot,specialty_snapshot,ars_snapshot,
                       comprobante_snapshot,billing_date_snapshot,total_snapshot,
                       added_at,added_by,removed_at,removed_by,removal_reason
                   ) VALUES %s
                   ON CONFLICT(batch_id,admission_source_instance_id,admission_attention_id)
                       WHERE admission_attention_id IS NOT NULL
                   DO UPDATE SET included=1,
                       patient_snapshot=EXCLUDED.patient_snapshot,
                       nss_snapshot=EXCLUDED.nss_snapshot,
                       cedula_snapshot=EXCLUDED.cedula_snapshot,
                       document_type_snapshot='ADMISIÓN',
                       document_number_snapshot=EXCLUDED.document_number_snapshot,
                       authorization_snapshot=EXCLUDED.authorization_snapshot,
                       service_date_snapshot=EXCLUDED.service_date_snapshot,
                       specialty_snapshot=EXCLUDED.specialty_snapshot,
                       ars_snapshot=EXCLUDED.ars_snapshot,total_snapshot=0,
                       added_at=EXCLUDED.added_at,added_by=EXCLUDED.added_by,
                       removed_at=NULL,removed_by=NULL,removal_reason=NULL""",
                values,
                template=(
                    "(%s,NULL,%s,%s,1,%s,%s,%s,%s,%s,%s,%s,%s,%s,NULL,%s,0,%s,%s,NULL,NULL,NULL)"
                ),
            )
            psycopg2.extras.execute_values(
                cursor,
                """INSERT INTO billing_batch_events(
                       batch_id,recibo_id,event_type,performed_at,performed_by,details
                   ) VALUES %s""",
                events,
                template="(%s,NULL,'ADMISION_AGREGADA',%s,%s,%s)",
            )
        con.execute(
            "UPDATE billing_batches SET updated_at=%s,updated_by=%s WHERE id=%s",
            (stamp, username, int(batch_id)),
        )
    if return_summary:
        return {"added": len(requested), "omitted": omitted_count}
    return len(requested)


def remove_receipt_from_monthly_batch(
    batch_id: int,
    receipt_id: int,
    user: dict,
    reason: str,
):
    username = str((user or {}).get("username") or "Sistema")
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede editar listados mensuales.")
    reason = str(reason or "").strip()
    if not reason:
        raise ValueError("Indica por qué se retira el recibo del listado.")
    stamp = now_str()
    with db_connect() as con:
        locked_batch = con.execute(
            "SELECT status FROM billing_batches WHERE id=%s FOR UPDATE",
            (int(batch_id),),
        ).fetchone()
        if not locked_batch or not batch_is_editable(locked_batch["status"]):
            raise ValueError("El listado no está disponible para edición.")
        updated = con.execute(
            """UPDATE billing_batch_receipts
               SET included=0, removed_at=%s, removed_by=%s, removal_reason=%s
               WHERE batch_id=%s AND recibo_id=%s AND included=1""",
            (stamp, username, reason, int(batch_id), int(receipt_id)),
        )
        if updated.rowcount != 1:
            raise ValueError("El recibo ya no está incluido en este listado.")
        con.execute(
            """UPDATE billing_batches SET updated_at=%s, updated_by=%s WHERE id=%s""",
            (stamp, username, int(batch_id)),
        )
        con.execute(
            """INSERT INTO billing_batch_events(
                   batch_id, recibo_id, event_type, performed_at, performed_by, details
               ) VALUES(%s,%s,'RECIBO_RETIRADO',%s,%s,%s)""",
            (int(batch_id), int(receipt_id), stamp, username, reason),
        )


