def delete_monthly_billing_batch(batch_id: int, user: dict) -> dict:
    """Elimina solo un expediente pendiente y sus relaciones, en transacción."""
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede eliminar expedientes mensuales.")
    with db_connect() as con:
        batch_row = con.execute(
            "SELECT * FROM billing_batches WHERE id=%s FOR UPDATE",
            (int(batch_id),),
        ).fetchone()
        if not batch_row:
            raise ValueError("El expediente ya no existe.")
        batch = dict(batch_row)
        if not batch_is_editable(batch):
            raise ValueError("Un expediente enviado no puede eliminarse.")
        count = int(
            con.execute(
                """SELECT COUNT(*) AS total
                   FROM billing_batch_receipts
                   WHERE batch_id=%s AND included=1""",
                (int(batch_id),),
            ).fetchone()["total"]
        )
        con.execute(
            "DELETE FROM billing_batch_receipts WHERE batch_id=%s",
            (int(batch_id),),
        )
        deleted = con.execute(
            """DELETE FROM billing_batches
               WHERE id=%s AND status IN (%s,%s)""",
            (int(batch_id), BATCH_PENDING, BATCH_DRAFT),
        )
        if deleted.rowcount != 1:
            raise ValueError("El expediente dejó de estar pendiente.")
        _insert_action_history(
            con, str((user or {}).get("username") or "Sistema"),
            "Eliminar listado ARS",
            f"Listado {int(batch_id)} · {batch.get('ars') or ''} · {count} paciente(s)",
            module="Listados ARS", entity_type="listado_ars",
            entity_id=str(batch_id), role=str((user or {}).get("role") or ""),
        )
        return {"batch": batch, "receipts": count}


def update_monthly_batch_configuration(
    batch_id: int,
    values: dict,
    user: dict,
    *,
    save_as_profile: bool = False,
) -> None:
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede editar listados mensuales.")
    username = str((user or {}).get("username") or "Sistema")
    batch = get_monthly_billing_batch(batch_id)
    if not batch or not batch_is_editable(batch):
        raise ValueError("Solo se pueden editar expedientes pendientes.")

    normalized = {}
    for key in (
        "ars_display_name", "invoice_number", "ncf", "invoice_date",
        "ncf_expiration_date", "provider_code", "provider_name",
        "provider_rnc", "ars_rnc", "ars_address", "ars_phone", "ars_email",
        "administrative_notes", "director_name",
        "director_title", "service_description", "specialty_default",
    ):
        normalized[key] = str(values.get(key) or "").strip()
    for date_key, label in (
        ("invoice_date", "fecha de factura"),
        ("ncf_expiration_date", "fecha de vencimiento del NCF"),
    ):
        date_value = normalized[date_key]
        if date_value:
            try:
                parsed = None
                for fmt in ("%d-%m-%Y", "%d/%m/%Y", "%Y-%m-%d"):
                    try:
                        parsed = datetime.strptime(date_value, fmt)
                        break
                    except ValueError:
                        continue
                if parsed is None:
                    raise ValueError
                normalized[date_key] = parsed.strftime("%Y-%m-%d")
            except ValueError as exc:
                raise ValueError(
                    f"La {label} debe tener formato DD-MM-AAAA."
                ) from exc
    try:
        discount = float(values.get("discount") or 0)
        itbis = float(values.get("itbis") or 0)
    except (TypeError, ValueError) as exc:
        raise ValueError("Descuento e ITBIS deben ser valores numéricos.") from exc
    if discount < 0 or itbis < 0:
        raise ValueError("Descuento e ITBIS no pueden ser negativos.")

    stamp = now_str()
    with db_connect() as con:
        con.execute(
            """UPDATE billing_batches SET
                   ars_display_name=%s, invoice_number=%s, ncf=%s,
                   invoice_date=%s, ncf_expiration_date=%s,
                   provider_code=%s, provider_name=%s, provider_rnc=%s,
                   ars_rnc=%s, ars_address=%s, ars_phone=%s, ars_email=%s,
                   administrative_notes=%s, director_name=%s,
                   director_title=%s, service_description=%s,
                   specialty_default=%s, discount=%s, itbis=%s,
                   updated_at=%s, updated_by=%s
               WHERE id=%s""",
            (
                normalized["ars_display_name"] or batch["ars"],
                normalized["invoice_number"], normalized["ncf"],
                normalized["invoice_date"], normalized["ncf_expiration_date"],
                normalized["provider_code"], normalized["provider_name"],
                normalized["provider_rnc"], normalized["ars_rnc"],
                normalized["ars_address"], normalized["ars_phone"],
                normalized["ars_email"], normalized["administrative_notes"],
                normalized["director_name"],
                normalized["director_title"] or "DIRECTORA",
                normalized["service_description"] or "EMERGENCIA",
                normalized["specialty_default"] or "EMERGENCIOLOGÍA",
                discount, itbis, stamp, username, int(batch_id),
            ),
        )
        con.execute(
            """INSERT INTO billing_batch_events(
                   batch_id, event_type, performed_at, performed_by, details
               ) VALUES(%s,'DATOS_ENVIO_ACTUALIZADOS',%s,%s,%s)""",
            (
                int(batch_id), stamp, username,
                json.dumps(
                    {
                        "invoice_number": normalized["invoice_number"],
                        "ncf": normalized["ncf"],
                        "invoice_date": normalized["invoice_date"],
                        "save_as_profile": bool(save_as_profile),
                    },
                    ensure_ascii=False,
                ),
            ),
        )
        _insert_action_history(
            con, username, "Editar listado ARS",
            f"Listado {int(batch_id)} · datos del envío actualizados",
            module="Listados ARS", entity_type="listado_ars",
            entity_id=str(batch_id), role=str((user or {}).get("role") or ""),
            created_at=stamp,
        )
    if save_as_profile:
        save_ars_billing_profile(
            batch["ars"],
            {
                "display_name": normalized["ars_display_name"] or batch["ars"],
                "ars_rnc": normalized["ars_rnc"],
                "ars_address": normalized["ars_address"],
                "ars_phone": normalized["ars_phone"],
                "ars_email": normalized["ars_email"],
                "administrative_notes": normalized["administrative_notes"],
                "provider_code": normalized["provider_code"],
                "provider_name": normalized["provider_name"],
                "provider_rnc": normalized["provider_rnc"],
                "director_name": normalized["director_name"],
                "director_title": normalized["director_title"] or "DIRECTORA",
                "service_description": normalized["service_description"] or "EMERGENCIA",
                "specialty_default": normalized["specialty_default"] or "EMERGENCIOLOGÍA",
            },
            user,
        )


def update_monthly_batch_receipt_export_data(
    batch_id: int,
    receipt_id: int,
    *,
    document_type: str,
    document_number: str,
    authorization: str,
    specialty: str,
    user: dict,
) -> None:
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede corregir listados mensuales.")
    document_type = str(document_type or "").strip().upper()
    if document_type not in {"NSS", "CÉDULA", "CEDULA"}:
        raise ValueError("Selecciona NSS o CÉDULA.")
    document_type = "CÉDULA" if document_type in {"CÉDULA", "CEDULA"} else "NSS"
    document_number = str(document_number or "").strip()
    authorization = str(authorization or "").strip()
    specialty = str(specialty or "").strip() or "EMERGENCIOLOGÍA"
    if not document_number:
        raise ValueError("Escribe el NSS o la cédula.")
    if len(document_number) > 24:
        raise ValueError("El NSS o la cédula no puede exceder 24 caracteres.")
    if not authorization:
        raise ValueError("Escribe el número de autorización.")
    if len(authorization) > 40:
        raise ValueError("La autorización no puede exceder 40 caracteres.")

    username = str((user or {}).get("username") or "Sistema")
    stamp = now_str()
    with db_connect() as con:
        row = con.execute(
            """SELECT b.status, br.included
               FROM billing_batches b
               JOIN billing_batch_receipts br ON br.batch_id=b.id
               WHERE b.id=%s AND br.recibo_id=%s
               FOR UPDATE""",
            (int(batch_id), int(receipt_id)),
        ).fetchone()
        if not row or not int(row["included"] or 0):
            raise ValueError("El recibo no está incluido en el expediente.")
        if not batch_is_editable(row["status"]):
            raise ValueError("Solo se pueden corregir expedientes pendientes.")
        con.execute(
            """UPDATE billing_batch_receipts SET
                   document_type_snapshot=%s,
                   document_number_snapshot=%s,
                   authorization_snapshot=%s,
                   specialty_snapshot=%s,
                   nss_snapshot=CASE WHEN %s='NSS' THEN %s ELSE nss_snapshot END,
                   cedula_snapshot=CASE WHEN %s='CÉDULA' THEN %s ELSE cedula_snapshot END,
                   last_edited_at=%s, last_edited_by=%s
               WHERE batch_id=%s AND recibo_id=%s""",
            (
                document_type, document_number, authorization, specialty,
                document_type, document_number,
                document_type, document_number,
                stamp, username, int(batch_id), int(receipt_id),
            ),
        )
        con.execute(
            """UPDATE billing_batches SET updated_at=%s, updated_by=%s WHERE id=%s""",
            (stamp, username, int(batch_id)),
        )
        con.execute(
            """INSERT INTO billing_batch_events(
                   batch_id, recibo_id, event_type, performed_at,
                   performed_by, details
               ) VALUES(%s,%s,'IDENTIFICACION_ENVIO_CORREGIDA',%s,%s,%s)""",
            (
                int(batch_id), int(receipt_id), stamp, username,
                json.dumps(
                    {
                        "document_type": document_type,
                        "document_number": document_number,
                        "authorization": authorization,
                        "specialty": specialty,
                    },
                    ensure_ascii=False,
                ),
            ),
        )


def monthly_batch_export_problems(batch_id: int) -> list[str]:
    batch = get_monthly_billing_batch(batch_id)
    if not batch:
        return ["No se encontró el expediente."]
    rows = list_monthly_batch_receipts(batch_id)
    return validate_export_payload(batch, rows)


def record_monthly_batch_export(batch_id: int, output_path: str, user: dict) -> None:
    username = str((user or {}).get("username") or "Sistema")
    stamp = now_str()
    output_path = os.path.abspath(str(output_path or "").strip())
    if not output_path or not os.path.isfile(output_path):
        raise ValueError("No se encontró el Excel generado para registrar la exportación.")
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM billing_batches WHERE id=%s FOR UPDATE",
            (int(batch_id),),
        ).fetchone()
        if not row or normalize_batch_status(row["status"]) != BATCH_PENDING:
            raise ValueError("El expediente dejó de estar disponible para exportación.")
        batch = dict(row)
        receipts = _query_monthly_batch_receipts(con, batch_id)
        signature = (
            _monthly_batch_export_signature(batch, receipts)
            + ":" + _file_sha256(output_path)
        )
        updated = con.execute(
            """UPDATE billing_batches
               SET last_export_path=%s, last_exported_at=%s,
                   last_export_signature=%s, updated_at=%s, updated_by=%s
               WHERE id=%s AND status=%s""",
            (
                output_path, stamp, signature, stamp, username,
                int(batch_id), BATCH_PENDING,
            ),
        )
        if updated.rowcount != 1:
            raise ValueError("El expediente dejó de estar disponible para exportación.")
        con.execute(
            """INSERT INTO billing_batch_events(
                   batch_id, event_type, performed_at, performed_by, details
               ) VALUES(%s,'EXCEL_GENERADO',%s,%s,%s)""",
            (
                int(batch_id), stamp, username,
                json.dumps({"path": output_path}, ensure_ascii=False),
            ),
        )


def confirm_monthly_batch_sent(batch_id: int, user: dict) -> dict:
    """Confirma el envío una sola vez, después de una exportación válida."""
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede confirmar listados enviados.")
    username = str((user or {}).get("username") or "Sistema")
    stamp = now_str()
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM billing_batches WHERE id=%s FOR UPDATE",
            (int(batch_id),),
        ).fetchone()
        if not row:
            raise ValueError("El expediente ya no existe.")
        batch = dict(row)
        if normalize_batch_status(batch.get("status")) != BATCH_PENDING:
            raise ValueError("Solo un expediente PENDIENTE puede confirmarse como enviado.")
        receipts = _query_monthly_batch_receipts(con, batch_id)
        if not receipts:
            raise ValueError("Añade al menos un recibo antes de confirmar el envío.")
        problems = validate_export_payload(batch, receipts)
        if problems:
            raise ValueError("Corrige los datos obligatorios antes de confirmar el envío.")
        export_path = str(batch.get("last_export_path") or "").strip()
        if not export_path or not os.path.isfile(export_path):
            raise ValueError("Genera correctamente el Excel final antes de confirmar el envío.")
        expected_signature = (
            _monthly_batch_export_signature(batch, receipts)
            + ":" + _file_sha256(export_path)
        )
        if not hmac.compare_digest(
            str(batch.get("last_export_signature") or ""), expected_signature
        ):
            raise ValueError(
                "El expediente cambió después de exportarse. Genera nuevamente el Excel final."
            )
        duplicate = con.execute(
            """SELECT br.recibo_id,br.admission_attention_id,other.batch_id
               FROM billing_batch_receipts br
               JOIN billing_batch_receipts other
                 ON other.included=1
                AND other.batch_id<>br.batch_id
                AND (
                    (br.recibo_id IS NOT NULL AND other.recibo_id=br.recibo_id)
                    OR (
                        br.admission_attention_id IS NOT NULL
                        AND other.admission_attention_id=br.admission_attention_id
                        AND other.admission_source_instance_id=
                            br.admission_source_instance_id
                    )
                )
               WHERE br.batch_id=%s AND br.included=1
               LIMIT 1""",
            (int(batch_id),),
        ).fetchone()
        if duplicate:
            raise ValueError(
                f"El recibo o atención {duplicate['recibo_id'] or duplicate['admission_attention_id']} "
                "también pertenece al listado "
                f"#{duplicate['batch_id']}."
            )
        sent_count = len(receipts)
        sent_total = round(
            sum(float(item.get("total_snapshot") or 0) for item in receipts), 2
        )
        updated = con.execute(
            """UPDATE billing_batches
               SET status=%s,sent_at=%s,sent_by=%s,
                   sent_receipt_count=%s,sent_total=%s,
                   sent_invoice_number=%s,sent_ncf=%s,sent_ars=%s,
                   sent_period_year=%s,sent_period_month=%s,
                   updated_at=%s,updated_by=%s
               WHERE id=%s AND status=%s""",
            (
                BATCH_SENT, stamp, username, sent_count, sent_total,
                str(batch.get("invoice_number") or ""),
                str(batch.get("ncf") or ""), str(batch.get("ars") or ""),
                int(batch.get("period_year")), int(batch.get("period_month")),
                stamp, username, int(batch_id), BATCH_PENDING,
            ),
        )
        if updated.rowcount != 1:
            raise ValueError("El expediente dejó de estar pendiente.")
        con.execute(
            """INSERT INTO billing_batch_events(
                   batch_id,event_type,performed_at,performed_by,details
               ) VALUES(%s,'CONFIRMADO_ENVIADO',%s,%s,%s)""",
            (
                int(batch_id), stamp, username,
                json.dumps(
                    {
                        "path": export_path, "receipts": sent_count,
                        "total": sent_total,
                        "invoice_number": str(batch.get("invoice_number") or ""),
                        "ncf": str(batch.get("ncf") or ""),
                    },
                    ensure_ascii=False,
                ),
            ),
        )
        _insert_action_history(
            con, username, "Confirmar listado enviado",
            f"Listado {int(batch_id)} · {sent_count} paciente(s) · RD$ {sent_total:,.2f}",
            module="Listados ARS", entity_type="listado_ars",
            entity_id=str(batch_id), role=str((user or {}).get("role") or ""),
            created_at=stamp,
        )
        return {
            "batch_id": int(batch_id),
            "sent_at": stamp,
            "sent_by": username,
            "receipts": sent_count,
            "total": sent_total,
        }


def update_monthly_batch_receipt_comprobante(
    batch_id: int,
    receipt_id: int,
    comprobante: str,
    user: dict,
):
    """Actualiza el comprobante de un facturado sin reabrir sus montos."""
    username = str((user or {}).get("username") or "Sistema")
    if not user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        raise PermissionError("Tu rol no puede editar comprobantes del listado.")
    value = str(comprobante or "").strip()
    if not value:
        raise ValueError("Escribe el número de comprobante o NCF.")
    stamp = now_str()
    with db_connect() as con:
        row = con.execute(
            """SELECT b.status, br.included, r.estado_facturacion
               FROM billing_batches b
               JOIN billing_batch_receipts br ON br.batch_id=b.id
               JOIN recibos r ON r.id=br.recibo_id
               WHERE b.id=%s AND br.recibo_id=%s
               FOR UPDATE""",
            (int(batch_id), int(receipt_id)),
        ).fetchone()
        if not row or not int(row["included"] or 0):
            raise ValueError("El recibo no está incluido en este listado.")
        if not batch_is_editable(row["status"]):
            raise ValueError("Solo se pueden editar listados pendientes.")
        if row["estado_facturacion"] != BILLING_INVOICED:
            raise ValueError("El recibo dejó de estar confirmado como facturado.")
        con.execute(
            """UPDATE billing_batch_receipts
               SET comprobante_snapshot=%s
               WHERE batch_id=%s AND recibo_id=%s""",
            (value, int(batch_id), int(receipt_id)),
        )
        con.execute(
            """UPDATE billing_batches
               SET updated_at=%s, updated_by=%s
               WHERE id=%s""",
            (stamp, username, int(batch_id)),
        )
        con.execute(
            """INSERT INTO billing_batch_events(
                   batch_id, recibo_id, event_type, performed_at,
                   performed_by, details
               ) VALUES(%s,%s,'COMPROBANTE_ACTUALIZADO',%s,%s,%s)""",
            (
                int(batch_id),
                int(receipt_id),
                stamp,
                username,
                json.dumps({"comprobante": value}, ensure_ascii=False),
            ),
        )
        con.execute(
            """INSERT INTO action_history(username, action, details, created_at)
               VALUES(%s,%s,%s,%s)""",
            (
                username,
                "Actualizar comprobante de listado",
                f"Listado {int(batch_id)} · Recibo ID {int(receipt_id)}",
                stamp,
            ),
        )


class DuplicateReceiptError(ValueError):
    def __init__(self, receipt):
        self.receipt = dict(receipt or {})
        date_text = str(self.receipt.get("fecha") or "")
        try:
            date_text = datetime.strptime(date_text, "%Y-%m-%d").strftime("%d-%m-%Y")
        except ValueError:
            pass
        super().__init__(
            f"Ya existe el recibo Nº {self.receipt.get('numero', '')} "
            f"para este paciente en la fecha {date_text}."
        )


class AdmissionAttentionUnavailableError(ValueError):
    def __init__(self):
        super().__init__(
            "Esta atención ya fue facturada o está siendo procesada por otra estación."
        )


def _lock_and_validate_admission_processing(
    con,
    admission_attention,
    *,
    session_id: str,
    receipt_id=None,
):
    """Revalida y bloquea brevemente la atención antes de guardar el recibo."""
    if not admission_attention:
        return None
    data = (
        admission_attention.snapshot()
        if isinstance(admission_attention, AdmissionAttention)
        else dict(admission_attention)
    )
    attention_id = int(
        data.get("attention_id") or data.get("admission_atencion_id") or 0
    )
    source_instance_id = str(
        data.get("source_instance_id")
        or data.get("admission_source_instance_id")
        or "LEGACY"
    )
    if not attention_id:
        raise AdmissionAttentionUnavailableError()

    shift = BillingAdmissionQueryService().current_shift()

    con.execute(
        "SELECT pg_advisory_xact_lock(hashtext(%s))",
        (f"admission-billing:{source_instance_id}:{attention_id}",),
    )
    existing = con.execute(
        """SELECT id,turno_origen_id,turno_procesamiento_id,herencia_estado
           FROM recibos
           WHERE admission_atencion_id=%s
             AND COALESCE(admission_source_instance_id,'LEGACY')=%s
             AND is_deleted=0
           ORDER BY id LIMIT 1""",
        (attention_id, source_instance_id),
    ).fetchone()
    if existing:
        if receipt_id is not None and int(existing["id"]) == int(receipt_id):
            return {
                "turno_origen_id": existing["turno_origen_id"],
                "turno_procesamiento_id": existing["turno_procesamiento_id"],
                "herencia_estado": existing["herencia_estado"],
                "already_linked": True,
            }
        raise AdmissionAttentionUnavailableError()

    eligible = con.execute(
        """WITH current_shift AS (
               SELECT %s::TEXT AS source_instance_id,
                      %s::BIGINT AS turn_id
           )
           SELECT p.turn_id AS turno_origen_id,
                  cs.turn_id AS turno_procesamiento_id,
                  (p.turn_id<>cs.turn_id) AS is_inherited
           FROM admission_attention_projection p
           JOIN current_shift cs
             ON cs.source_instance_id=p.source_instance_id
           LEFT JOIN admission_shift_inheritances inheritance
             ON inheritance.source_instance_id=p.source_instance_id
            AND inheritance.attention_id=p.attention_id
            AND inheritance.turno_origen_id=p.turn_id
            AND inheritance.estado='PENDIENTE'
           WHERE p.attention_id=%s AND p.source_instance_id=%s
             AND p.readiness=%s
             AND (
                   p.turn_id=cs.turn_id
                   OR inheritance.attention_id IS NOT NULL
             )
             AND UPPER(TRIM(COALESCE(p.service_type,'')))='EMERGENCIA'
             AND UPPER(TRIM(COALESCE(p.source_status,'ACTIVA')))
                 IN ('ACTIVA','PENDIENTE')
           LIMIT 1""",
        (
            str(shift["source_instance_id"]), int(shift["turn_id"]),
            attention_id, source_instance_id, READINESS_READY,
        ),
    ).fetchone()
    if not eligible:
        raise AdmissionAttentionUnavailableError()

    claim = con.execute(
        """SELECT session_id,expires_at
           FROM admission_billing_claims
           WHERE source_instance_id=%s AND attention_id=%s
             AND session_id=%s AND expires_at>NOW()
           FOR UPDATE""",
        (source_instance_id, attention_id, str(session_id or "")),
    ).fetchone()
    if not claim:
        raise AdmissionAttentionUnavailableError()

    return {
        "turno_origen_id": int(eligible["turno_origen_id"]),
        "turno_procesamiento_id": int(eligible["turno_procesamiento_id"]),
        "herencia_estado": (
            "HEREDADA_PROCESADA"
            if bool(eligible["is_inherited"])
            else "TURNO_ACTUAL_PROCESADA"
        ),
        "already_linked": False,
    }


def normalize_receipt_identity(value) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip()).upper()


def build_receipt_dedup_key(
    nombre="", attention_id=None, nss="", cedula="", source_instance_id=""
) -> str:
    if attention_id not in (None, ""):
        source = normalize_receipt_identity(source_instance_id)
        return f"A:{source + ':' if source else ''}{int(attention_id)}"
    nss_value = normalize_receipt_identity(nss)
    if nss_value:
        return f"N:{nss_value}"
    cedula_value = normalize_receipt_identity(cedula)
    if cedula_value:
        return f"C:{cedula_value}"
    name_value = normalize_receipt_identity(nombre)
    return f"M:{name_value}" if name_value else ""


def _log_duplicate_attempt(username, duplicate, fecha, dedup_key):
    try:
        log_action(
            username or "Sistema",
            "Intento bloqueado por duplicidad",
            f"Recibo existente {duplicate.get('numero')} · fecha {fecha} · clave {dedup_key}",
        )
    except Exception as exc:
        write_runtime_log(f"No se pudo registrar intento duplicado: {exc}")


def _guard_active_receipt_duplicate(
    con, *, nombre, fecha, username="Sistema", attention_id=None, nss="",
    cedula="", source_instance_id="", exclude_id=None
) -> str:
    dedup_key = build_receipt_dedup_key(
        nombre, attention_id, nss, cedula, source_instance_id
    )
    service_date = str(fecha or "").strip()
    if not service_date or not dedup_key:
        return dedup_key
    lock_key = f"receipt:{service_date}:{dedup_key}"
    con.execute("SELECT pg_advisory_xact_lock(hashtext(%s))", (lock_key,))
    params = [service_date, dedup_key]
    exclusion = ""
    if exclude_id is not None:
        exclusion = " AND id<>%s"
        params.append(int(exclude_id))
    duplicate = con.execute(
        """SELECT id, numero, nombre, fecha, total, estado_facturacion
           FROM recibos
           WHERE is_deleted=0 AND fecha=%s AND dedup_key=%s"""
        + exclusion
        + " ORDER BY id LIMIT 1",
        tuple(params),
    ).fetchone()
    if duplicate:
        duplicate = dict(duplicate)
        _log_duplicate_attempt(username, duplicate, service_date, dedup_key)
        raise DuplicateReceiptError(duplicate)
    return dedup_key


def add_recibo(numero: int, nombre: str, fecha: str, dx: str, ars: str, sala: float, total: float, pdf_filename: str, username: str, is_backdated: int = 0, created_at: str = None):
    # fecha = fecha seleccionada del servicio/recibo.
    # created_at = fecha real en que se generó el recibo.
    # Los reportes se calculan por created_at, para que un recibo atrasado hecho hoy caiga en el reporte de hoy.
    if str(ars or "").strip() and not medication_ars_is_selectable(ars):
        raise ValueError("SENASA SUBSIDIADO no se factura en este módulo.")
    created_at = created_at or now_str()
    with db_connect() as con:
        dedup_key = _guard_active_receipt_duplicate(
            con, nombre=nombre, fecha=fecha, username=username
        )
        cur = con.execute("""INSERT INTO recibos(numero, nombre, fecha, dx, ars, sala, total, pdf_filename, username, created_at, is_backdated, estado_facturacion, estado_facturacion_at, dedup_key, document_storage_mode) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id""", (int(numero), nombre or "", fecha or "", dx or "", ars or "", float(sala), float(total), pdf_filename or "", username or "", created_at, is_backdated, BILLING_PENDING, created_at, dedup_key or None, STORAGE_LEGACY))
        return int(cur.fetchone()[0])

def add_recibo_item(recibo_id: int, categoria: str, nombre: str, precio_unit: float, cantidad: int, total: float, ars: str = ""):
    with db_connect() as con: con.execute("INSERT INTO recibo_items(recibo_id, categoria, nombre, precio_unit, cantidad, total, ars) VALUES(%s,%s,%s,%s,%s,%s,%s)", (recibo_id, categoria, nombre, float(precio_unit), int(cantidad), float(total), ars or ""))

def update_recibo_db(recibo_id: int, nombre: str, fecha: str, dx: str, ars: str, sala: float, total: float, pdf_filename: str, username: str, is_backdated: int = 0):
    if str(ars or "").strip() and not medication_ars_is_selectable(ars):
        raise ValueError("SENASA SUBSIDIADO no se factura en este módulo.")
    with db_connect() as con:
        current = con.execute(
            """SELECT admission_atencion_id, admission_nss_snapshot,
                      admission_cedula_snapshot, admission_source_instance_id
               FROM recibos WHERE id=%s FOR UPDATE""",
            (int(recibo_id),),
        ).fetchone()
        if not current:
            raise ValueError("El recibo no existe.")
        dedup_key = _guard_active_receipt_duplicate(
            con, nombre=nombre, fecha=fecha, username=username,
            attention_id=current["admission_atencion_id"],
            nss=current["admission_nss_snapshot"],
            cedula=current["admission_cedula_snapshot"],
            source_instance_id=current["admission_source_instance_id"],
            exclude_id=recibo_id,
        )
        cur = con.execute(
            """UPDATE recibos SET nombre=%s, fecha=%s, dx=%s, ars=%s, sala=%s, total=%s,
                      pdf_filename=%s, is_backdated=%s, dedup_key=%s,
                      revision_version=revision_version+1
               WHERE id=%s AND estado_facturacion IN ('PENDIENTE','SIN_CLASIFICAR')""",
            (nombre or "", fecha or "", dx or "", ars or "", float(sala), float(total), pdf_filename or "", is_backdated, dedup_key or None, recibo_id),
        )
        if cur.rowcount != 1:
            raise ValueError("Este recibo no puede editarse en su estado de facturación actual.")
        con.execute("DELETE FROM recibo_items WHERE recibo_id=%s", (recibo_id,))


def save_receipt_with_items(
    recibo_id,
    numero,
    nombre,
    fecha,
    dx,
    ars,
    sala,
    total,
    pdf_filename,
    username,
    is_backdated,
    created_at,
    grouped,
    coverage="ASEGURADO",
    authorization_number="",
    admission_attention=None,
    admission_session_id="",
    document_context=None,
    verification_bypass=None,
):
    """Guarda cabecera, ítems, historial y snapshot con un solo commit."""
    if str(ars or "").strip() and not medication_ars_is_selectable(ars):
        raise ValueError("SENASA SUBSIDIADO no se factura en este módulo.")
    bypass_data = dict(verification_bypass or {})
    actor_user = {
        "username": str(username or ""),
        "role": str(bypass_data.get("role") or ""),
    }
    if bypass_data and not admission_attention:
        actor_user = get_user(str(username or "")) or actor_user
        bypass_reason = str(bypass_data.get("reason") or "").strip()
        if not can_bypass_patient_verification(actor_user):
            raise PermissionError(
                "Tu rol no puede crear recibos sin verificar una atención."
            )
        if len(bypass_reason) < 8:
            raise ValueError("El motivo para omitir la verificación es obligatorio.")
        bypass_data["reason"] = bypass_reason
        bypass_data["role"] = normalize_role(actor_user.get("role"))
        bypass_data["username"] = str(username or "Sistema")
        bypass_data["device"] = str(
            bypass_data.get("device")
            or os.environ.get("COMPUTERNAME")
            or "ESTACION"
        )
    elif not admission_attention and recibo_id is None:
        raise ValueError("Debes verificar una atención antes de crear el recibo.")
    if admission_attention:
        attention_data = (
            admission_attention.snapshot()
            if isinstance(admission_attention, AdmissionAttention)
            else dict(admission_attention)
        )
        attention_ars = str(
            attention_data.get("canonical_ars")
            or attention_data.get("ars")
            or ""
        )
        if not admission_ars_is_visible(attention_ars):
            raise ValueError(
                "La ARS de esta atención está excluida del flujo de validación."
            )
        if (
            bool(attention_data.get("uninsured"))
            or str(attention_data.get("coverage_status") or "")
            == COVERAGE_UNINSURED_DECLARED
        ):
            actor_user = get_user(str(username or "")) or actor_user
            if not can_view_uninsured_patients(actor_user):
                raise PermissionError(
                    "Tu rol no puede facturar pacientes sin seguro."
                )
        readiness = str(attention_data.get("billing_readiness") or "")
        if readiness and readiness != READINESS_READY:
            reasons = list(attention_data.get("readiness_reasons") or ())
            raise ValueError(
                "La atención todavía no está completa para Facturación."
                + ("\n- " + "\n- ".join(reasons) if reasons else "")
            )
    item_rows = []
    for categoria, items in grouped:
        item_ars = ars if categoria in ARS_CATEGORIES else ""
        for item_name, precio, cantidad, item_total, _ in items:
            item_rows.append(
                (
                    categoria,
                    item_name,
                    float(precio),
                    int(cantidad),
                    float(item_total),
                    item_ars,
                )
            )

    editing = recibo_id is not None
    authorization_number = str(authorization_number or "").strip()
    document_state = (
        DOCUMENT_READY
        if billing_is_ready_for_audit(
            patient_validated=bool(admission_attention),
            authorization=authorization_number,
        )
        else DOCUMENT_PRELIMINARY
    )
    authorization_changed_at = now_str() if authorization_number else None
    authorization_actor = (username or "Sistema") if authorization_number else None
    admission_values = list(_admission_values(admission_attention))
    service_type = str(
        (admission_attention or {}).get("attention_type", "")
        if isinstance(admission_attention, dict)
        else getattr(admission_attention, "attention_type", "")
    ).upper() or "EMERGENCIA"
    if service_type not in ("EMERGENCIA", "CONSULTA"):
        service_type = "EMERGENCIA"
    if admission_attention:
        admission_values[6] = str(username or "Sistema")
    with db_connect() as con:
        admission_processing = _lock_and_validate_admission_processing(
            con,
            admission_attention,
            session_id=str(admission_session_id or ""),
            receipt_id=recibo_id,
        )
        if editing:
            current = con.execute(
                """SELECT estado_facturacion, revision_version, total, sala, ars,
                          tipo_cobertura, numero_autorizacion, estado_documento,
                          admission_atencion_id, admission_nss_snapshot,
                          admission_cedula_snapshot, admission_source_instance_id,
                          verification_bypassed, receipt_origin,
                          EXISTS(
                              SELECT 1 FROM recibo_facturacion_history h
                              WHERE h.recibo_id=recibos.id AND h.estado_nuevo='FACTURADO'
                          ) AS was_invoiced
                   FROM recibos WHERE id=%s FOR UPDATE""",
                (int(recibo_id),),
            ).fetchone()
            if not current:
                raise ValueError("El recibo que intentas editar ya no existe.")
            current_status = str(current["estado_facturacion"] or BILLING_UNCLASSIFIED)
            if current_status not in (BILLING_PENDING, BILLING_UNCLASSIFIED):
                raise ValueError(
                    f"El recibo está {BILLING_STATUS_LABELS.get(current_status, current_status).lower()} y no puede editarse. "
                    "Debe reabrirse como pendiente antes de modificarlo."
                )
            has_new_attention = admission_values[0] is not None
            effective_attention_id = (
                current["admission_atencion_id"] or admission_values[0]
            )
            effective_nss = (
                admission_values[2] if has_new_attention
                else current["admission_nss_snapshot"]
            )
            effective_cedula = (
                admission_values[3] if has_new_attention
                else current["admission_cedula_snapshot"]
            )
            effective_source = (
                admission_values[8]
                if str(admission_values[8] or "").strip()
                else current["admission_source_instance_id"]
            )
            _guard_active_receipt_duplicate(
                con, nombre=nombre, fecha=fecha, username=username,
                attention_id=effective_attention_id, nss=effective_nss,
                cedula=effective_cedula, source_instance_id=effective_source,
                exclude_id=recibo_id,
            )
            updated = con.execute(
                """UPDATE recibos
                   SET nombre=%s, fecha=%s, dx=%s, ars=%s, tipo_cobertura=%s, sala=%s, total=%s,
                       is_backdated=%s, revision_version=revision_version+1,
                       numero_autorizacion=%s,
                       autorizacion_at=CASE
                           WHEN COALESCE(numero_autorizacion,'')<>%s THEN %s
                           ELSE autorizacion_at END,
                       autorizacion_por=CASE
                           WHEN COALESCE(numero_autorizacion,'')<>%s THEN %s
                           ELSE autorizacion_por END,
                       estado_documento=%s,
                       auditoria_asignada_a=NULL, auditoria_asignada_at=NULL,
                       auditoria_checklist_json=NULL, auditoria_preflight_json=NULL,
                       auditoria_riesgo=0,
                       admission_atencion_id=COALESCE(admission_atencion_id,%s),
                       admission_paciente_id=COALESCE(admission_paciente_id,%s),
                       admission_nss_snapshot=CASE WHEN %s IS NULL
                           THEN admission_nss_snapshot ELSE %s END,
                       admission_cedula_snapshot=CASE WHEN %s IS NULL
                           THEN admission_cedula_snapshot ELSE %s END,
                       admission_ars_snapshot=CASE WHEN %s IS NULL
                           THEN admission_ars_snapshot ELSE %s END,
                       admission_linked_at=COALESCE(admission_linked_at,%s),
                       admission_linked_by=COALESCE(admission_linked_by,%s),
                       admission_source_updated_at=CASE WHEN %s IS NULL
                           THEN admission_source_updated_at ELSE %s END,
                       admission_source_instance_id=COALESCE(
                           NULLIF(%s,''), admission_source_instance_id),
                       admission_snapshot_hash=COALESCE(
                           NULLIF(%s,''), admission_snapshot_hash),
                       admission_coverage_status=COALESCE(
                           NULLIF(%s,''), admission_coverage_status),
                       admission_readiness=COALESCE(
                           NULLIF(%s,''), admission_readiness),
                       turno_origen_id=COALESCE(turno_origen_id,%s),
                       turno_procesamiento_id=COALESCE(turno_procesamiento_id,%s),
                       herencia_estado=COALESCE(herencia_estado,%s),
                       herencia_procesada_at=COALESCE(herencia_procesada_at,%s),
                       herencia_procesada_por=COALESCE(herencia_procesada_por,%s),
                       service_type=COALESCE(NULLIF(%s,''), service_type),
                       specialty_snapshot=COALESCE(NULLIF(%s,''), specialty_snapshot),
                       admission_username_snapshot=COALESCE(NULLIF(%s,''), admission_username_snapshot)
                   WHERE id=%s AND estado_facturacion IN ('PENDIENTE','SIN_CLASIFICAR')""",
                (
                    nombre or "", fecha or "", dx or "", ars or "", coverage,
                    float(sala), float(total), int(is_backdated), authorization_number,
                    authorization_number, authorization_changed_at,
                    authorization_number, authorization_actor,
                    document_state,
                    admission_values[0], admission_values[1],
                    admission_values[0], admission_values[2],
                    admission_values[0], admission_values[3],
                    admission_values[0], admission_values[4],
                    admission_values[5], admission_values[6],
                    admission_values[0], admission_values[7],
                    admission_values[8], admission_values[9],
                    admission_values[10], admission_values[11],
                    (
                        admission_processing.get("turno_origen_id")
                        if admission_processing else None
                    ),
                    (
                        admission_processing.get("turno_procesamiento_id")
                        if admission_processing else None
                    ),
                    (
                        admission_processing.get("herencia_estado")
                        if admission_processing else None
                    ),
                    now_str() if admission_processing else None,
                    str(username or "Sistema") if admission_processing else None,
                    service_type, admission_values[13], admission_values[14],
                    int(recibo_id),
                ),
            )
            if updated.rowcount != 1:
                raise ValueError("El estado del recibo cambió mientras se editaba. Actualiza el historial.")
            con.execute("DELETE FROM recibo_items WHERE recibo_id=%s", (int(recibo_id),))
            saved_id = int(recibo_id)
            action = "Editar recibo pendiente"
            previous_total = float(current["total"] or 0)
            next_revision = int(current["revision_version"] or 0) + 1
            was_invoiced = bool(current["was_invoiced"])
            details = (
                f"Recibo {numero} - Total RD$ {previous_total:,.2f} -> "
                f"RD$ {float(total):,.2f} - Versión {next_revision}"
            )
        else:
            _guard_active_receipt_duplicate(
                con, nombre=nombre, fecha=fecha, username=username,
                attention_id=admission_values[0], nss=admission_values[2],
                cedula=admission_values[3],
                source_instance_id=admission_values[8],
            )
            cur = con.execute(
                """INSERT INTO recibos(
                       numero, nombre, fecha, dx, ars, tipo_cobertura, sala, total, pdf_filename,
                       username, created_at, is_backdated, pdf_synced,
                       estado_facturacion, estado_facturacion_at, numero_autorizacion,
                       autorizacion_at, autorizacion_por, estado_documento
                       ,document_storage_mode
                       ,admission_atencion_id, admission_paciente_id,
                       admission_nss_snapshot, admission_cedula_snapshot,
                       admission_ars_snapshot, admission_linked_at,
                       admission_linked_by, admission_source_updated_at,
                       admission_source_instance_id, admission_snapshot_hash,
                       admission_coverage_status, admission_readiness,
                       turno_origen_id, turno_procesamiento_id,
                       herencia_estado, herencia_procesada_at,
                       herencia_procesada_por,
                       service_type, specialty_snapshot, admission_username_snapshot
                   ) VALUES(
                       %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,0,%s,%s,%s,%s,%s,%s,
                       %s,
                       %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                       %s,%s,%s,%s,%s,%s,%s,%s
                   )
                   RETURNING id""",
                (
                    int(numero), nombre or "", fecha or "", dx or "", ars or "", coverage,
                    float(sala), float(total), "", username or "",
                    created_at or now_str(), int(is_backdated),
                    BILLING_PENDING, created_at or now_str(),
                    authorization_number, authorization_changed_at,
                    authorization_actor,
                    document_state,
                    new_receipt_storage_mode(),
                    *admission_values[:12],
                    (
                        admission_processing.get("turno_origen_id")
                        if admission_processing else None
                    ),
                    (
                        admission_processing.get("turno_procesamiento_id")
                        if admission_processing else None
                    ),
                    (
                        admission_processing.get("herencia_estado")
                        if admission_processing else None
                    ),
                    now_str() if admission_processing else None,
                    str(username or "Sistema") if admission_processing else None,
                    service_type, admission_values[13], admission_values[14],
                ),
            )
            saved_id = int(cur.fetchone()[0])
            if bypass_data:
                con.execute(
                    """UPDATE recibos
                       SET verification_bypassed=TRUE,
                           verification_bypass_reason=%s,
                           verification_bypass_by=%s,
                           verification_bypass_role=%s,
                           verification_bypass_device=%s,
                           verification_bypass_at=NOW(),
                           receipt_origin='MANUAL_PRIVILEGED'
                       WHERE id=%s""",
                    (
                        bypass_data["reason"], str(username or "Sistema"),
                        bypass_data["role"], bypass_data["device"], saved_id,
                    ),
                )
            else:
                con.execute(
                    "UPDATE recibos SET receipt_origin='ADMISSION_LINKED' WHERE id=%s",
                    (saved_id,),
                )
            con.execute(
                """INSERT INTO recibo_facturacion_history(
                       recibo_id, estado_anterior, estado_nuevo, realizado_por, realizado_at,
                       motivo, observacion, referencia, total_al_momento, ars_al_momento, recibo_version
                   ) VALUES(%s,NULL,%s,%s,%s,%s,%s,%s,%s,%s,0)""",
                (
                    saved_id, BILLING_PENDING, str(username or "Sistema"), now_str(),
                    "Creación del recibo",
                    "Listo para auditoría" if document_state == DOCUMENT_READY
                    else "Documento preliminar pendiente de autorización",
                    "",
                    float(total), ars or "",
                ),
            )
            action = "Generar recibo pendiente"
            details = (
                f"Recibo {numero} - Total ${float(total):,.2f} "
                f"(Pasado: {bool(is_backdated)})"
            )

        if bypass_data and not editing:
            event_at = now_str()
            con.execute(
                """INSERT INTO recibo_facturacion_history(
                       recibo_id,estado_anterior,estado_nuevo,realizado_por,
                       realizado_at,motivo,observacion,evento_tipo,
                       total_al_momento,ars_al_momento,recibo_version
                   ) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,0)""",
                (
                    saved_id, BILLING_PENDING, BILLING_PENDING,
                    str(username or "Sistema"), event_at,
                    bypass_data["reason"],
                    "Recibo creado sin vínculo a una atención por rol autorizado",
                    "PATIENT_VERIFICATION_BYPASSED",
                    float(total), str(ars or ""),
                ),
            )
            _insert_action_history(
                con,
                str(username or "Sistema"),
                "UNLINKED_RECEIPT_CREATED",
                (
                    f"Recibo {numero}; motivo={bypass_data['reason']}; "
                    f"dispositivo={bypass_data['device']}"
                ),
                module="Facturación",
                entity_type="recibo",
                entity_id=str(saved_id),
                role=bypass_data["role"],
                created_at=event_at,
            )

        if (
            editing
            and admission_values[0] is not None
            and bool(current.get("verification_bypassed"))
            and current.get("admission_atencion_id") is None
        ):
            _insert_action_history(
                con,
                str(username or "Sistema"),
                "ADMISSION_ATTENTION_LINKED_LATER",
                (
                    f"Recibo {numero}; atención={int(admission_values[0])}; "
                    f"dispositivo={os.environ.get('COMPUTERNAME') or 'ESTACION'}; "
                    "resultado=VINCULADO"
                ),
                module="Facturación",
                entity_type="recibo",
                entity_id=str(saved_id),
                role=normalize_role(actor_user.get("role")),
            )

        if (
            admission_processing
            and not admission_processing.get("already_linked")
            and admission_values[0] is not None
        ):
            con.execute(
                """UPDATE admission_billing_claims
                   SET turno_origen_id=%s,turno_procesamiento_id=%s,
                       estado_herencia=%s,processed_at=NOW(),receipt_id=%s,
                       expires_at=NOW()
                   WHERE source_instance_id=%s AND attention_id=%s
                     AND session_id=%s""",
                (
                    admission_processing["turno_origen_id"],
                    admission_processing["turno_procesamiento_id"],
                    admission_processing["herencia_estado"],
                    saved_id,
                    str(admission_values[8] or "LEGACY"),
                    int(admission_values[0]),
                    str(admission_session_id or ""),
                ),
            )
            _upsert_admission_inheritance(
                con,
                source_instance_id=str(admission_values[8] or "LEGACY"),
                attention_id=int(admission_values[0]),
                turno_origen_id=admission_processing["turno_origen_id"],
                estado="COMPLETADA",
                turno_procesamiento_id=admission_processing[
                    "turno_procesamiento_id"
                ],
                processed_by=str(username or "Sistema"),
                receipt_id=saved_id,
            )

        if item_rows:
            cursor = con.con.cursor()
            psycopg2.extras.execute_values(
                cursor,
                """INSERT INTO recibo_items(
                       recibo_id, categoria, nombre, precio_unit, cantidad, total, ars
                   ) VALUES %s""",
                [(saved_id, *row) for row in item_rows],
                page_size=500,
            )

        if editing:
            revision_snapshot = {
                "previous": {
                    "total": previous_total,
                    "room": float(current["sala"] or 0),
                    "ars": str(current["ars"] or ""),
                    "coverage": str(current["tipo_cobertura"] or ""),
                    "authorization": str(current["numero_autorizacion"] or ""),
                    "document_state": str(current["estado_documento"] or DOCUMENT_PRELIMINARY),
                },
                "new": {
                    "total": float(total),
                    "room": float(sala),
                    "ars": str(ars or ""),
                    "coverage": str(coverage or ""),
                    "authorization": authorization_number,
                    "document_state": document_state,
                    "item_count": len(item_rows),
                },
                "difference": float(total) - previous_total,
                "previously_invoiced": was_invoiced,
            }
            con.execute(
                """INSERT INTO recibo_facturacion_history(
                       recibo_id, estado_anterior, estado_nuevo, realizado_por, realizado_at,
                       motivo, observacion, referencia, evento_tipo, preflight_json, riesgo,
                       total_al_momento, ars_al_momento, recibo_version
                   ) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,0,%s,%s,%s)""",
                (
                    saved_id, current_status, current_status, str(username or "Sistema"),
                    now_str(),
                    "Edición posterior a reapertura" if was_invoiced else "Edición de recibo pendiente",
                    (
                        f"Monto anterior RD$ {previous_total:,.2f}; "
                        f"monto nuevo RD$ {float(total):,.2f}; "
                        f"diferencia RD$ {float(total) - previous_total:+,.2f}"
                    ),
                    authorization_number or None,
                    "EDICION_POST_REAPERTURA" if was_invoiced else "EDICION_DOCUMENTO",
                    json.dumps(revision_snapshot, ensure_ascii=False),
                    float(total), str(ars or ""), next_revision,
                ),
            )

        document_version = save_receipt_document_snapshot(
            con,
            saved_id,
            str(username or "Sistema"),
            document_context=dict(document_context or {}),
            target_storage_mode=(
                new_receipt_storage_mode() if not editing else None
            ),
        )
        saved_storage_mode = (
            document_version.get("storage_mode")
            or (new_receipt_storage_mode() if not editing else "SNAPSHOT")
        )
        con.execute(
            "INSERT INTO action_history(username, action, details, created_at) VALUES(%s,%s,%s,%s)",
            (
                str(username or "Sistema"),
                action,
                (
                    f"{details} - Documento v{document_version['version']} "
                    f"{saved_storage_mode}"
                ),
                now_str(),
            ),
        )

    return saved_id

def _receipt_actor(actor):
    if isinstance(actor, dict):
        return dict(actor)
    username = str(actor or "").strip()
    return get_user(username) if username else None


def _require_receipt_permission(actor, permission, message):
    user = _receipt_actor(actor)
    if not user_has_permission(user, permission):
        raise PermissionError(message)
    return user, str(user.get("username") or "Sistema")


def _assert_receipts_not_in_active_batches(con, receipt_ids):
    if not receipt_ids:
        return
    rows = con.execute(
        """SELECT DISTINCT br.recibo_id, b.status
           FROM billing_batch_receipts br
           JOIN billing_batches b ON b.id=br.batch_id
           WHERE br.recibo_id = ANY(%s) AND br.included=1""",
        ([int(value) for value in receipt_ids],),
    ).fetchall()
    statuses = {str(row["status"] or "").upper() for row in rows}
    if statuses.intersection({"ENVIADO", "CERRADO"}):
        raise ValueError(
            "Este recibo pertenece a un listado enviado y no puede eliminarse."
        )
    if statuses.intersection({"PENDIENTE", "BORRADOR"}):
        raise ValueError(
            "Este recibo pertenece a un listado pendiente. Retíralo del listado antes de eliminarlo."
        )
    if rows:
        raise ValueError(
            "Este recibo pertenece a un listado. Retíralo del listado antes de eliminarlo."
        )


def move_receipts_to_trash(receipt_ids, actor, reason=""):
    user, username = _require_receipt_permission(
        actor, PERMISSION_DELETE_PENDING,
        "Tu rol no puede mover recibos a la papelera.",
    )
    ids = sorted({int(value) for value in receipt_ids})
    if not ids:
        return []
    stamp = now_str()
    with db_connect() as con:
        rows = con.execute(
            """SELECT id, numero, nombre, fecha, total
               FROM recibos
               WHERE id = ANY(%s) AND is_deleted=0
               ORDER BY id FOR UPDATE""",
            (ids,),
        ).fetchall()
        if len(rows) != len(ids):
            raise ValueError("Uno de los recibos ya no existe o ya está en la papelera.")
        _assert_receipts_not_in_active_batches(con, ids)
        con.execute(
            """UPDATE recibos
               SET is_deleted=1, deleted_at=%s, deleted_by=%s, deleted_reason=%s
               WHERE id = ANY(%s)""",
            (stamp, username, reason or "", ids),
        )
        audit_rows = [
            (
                username, "Mover recibo a papelera",
                f"Recibo Nº {row['numero']} · ID {row['id']}. {reason}".strip(),
                stamp,
            )
            for row in rows
        ]
        with con.con.cursor() as cursor:
            psycopg2.extras.execute_values(
                cursor,
                """INSERT INTO action_history(username,action,details,created_at)
                   VALUES %s""",
                audit_rows,
            )
        return [dict(row) for row in rows]


def delete_recibo(recibo_id: int, deleted_by=None, reason: str = ""):
    return move_receipts_to_trash([recibo_id], deleted_by, reason)[0]


class ReceiptProtectedError(ValueError):
    """El recibo conserva evidencia que impide su purga definitiva."""


def inspect_receipt_purgeability(con, receipt_id: int, *, for_update=False):
    """Clasifica una purga sin alterar datos y usando las FK como contrato.

    Las versiones documentales son inmutables por diseño. La migración
    documental conserva hashes, copias y estados de verificación, por lo que
    tampoco se descarta implícitamente. Los items y el historial no definitivo
    usan ON DELETE CASCADE y los eventos de listados conservan su auditoría con
    ON DELETE SET NULL.
    """
    lock_clause = " FOR UPDATE" if for_update else ""
    row = con.execute(
        """SELECT id, numero, estado_facturacion, is_deleted, pdf_filename
           FROM recibos WHERE id=%s""" + lock_clause,
        (int(receipt_id),),
    ).fetchone()
    if not row or not bool(row["is_deleted"]):
        raise ValueError("El recibo no existe en la papelera.")

    dependencies = con.execute(
        """SELECT
               EXISTS(
                   SELECT 1 FROM recibo_facturacion_history h
                   WHERE h.recibo_id=%s AND h.estado_nuevo='FACTURADO'
               ) AS was_invoiced,
               EXISTS(
                   SELECT 1 FROM billing_batch_receipts br
                   WHERE br.recibo_id=%s
               ) AS has_billing_batch,
               EXISTS(
                   SELECT 1 FROM recibo_document_versions v
                   WHERE v.recibo_id=%s
               ) AS has_document_versions,
               EXISTS(
                   SELECT 1 FROM recibo_document_migration m
                   WHERE m.recibo_id=%s
               ) AS has_document_migration""",
        (int(receipt_id),) * 4,
    ).fetchone()

    reasons = []
    if str(row["estado_facturacion"] or "").upper() != BILLING_PENDING:
        reasons.append("estado financiero protegido")
    if bool(dependencies["was_invoiced"]):
        reasons.append("historial de facturación definitivo")
    if bool(dependencies["has_billing_batch"]):
        reasons.append("vínculo con un listado de ARS")
    if bool(dependencies["has_document_versions"]):
        reasons.append("versiones documentales inmutables")
    if bool(dependencies["has_document_migration"]):
        reasons.append("evidencia de migración documental")

    result = dict(row)
    result.update({
        "purgable": not reasons,
        "protected_reasons": tuple(reasons),
        "was_invoiced": bool(dependencies["was_invoiced"]),
        "has_billing_batch": bool(dependencies["has_billing_batch"]),
        "has_document_versions": bool(dependencies["has_document_versions"]),
        "has_document_migration": bool(dependencies["has_document_migration"]),
    })
    return result


def purge_receipt_permanently(receipt_id: int, user_context=None):
    """Purga un recibo elegible en una transacción completa."""
    _user, username = _require_receipt_permission(
        user_context, PERMISSION_MANAGE_TRASH,
        "Solo un administrador puede eliminar recibos permanentemente.",
    )
    with db_connect() as con:
        decision = inspect_receipt_purgeability(
            con, int(receipt_id), for_update=True,
        )
        if not decision["purgable"]:
            raise ReceiptProtectedError(
                "Este recibo contiene historial de facturación o documentación "
                "protegida y no puede eliminarse definitivamente."
            )

        # Las FK eliminan items/historial descartable y conservan eventos de
        # listado con receipt_id NULL. No se fuerzan ni deshabilitan constraints.
        deleted = con.execute(
            "DELETE FROM recibos WHERE id=%s AND is_deleted=1",
            (int(receipt_id),),
        )
        if getattr(deleted, "rowcount", 1) != 1:
            raise RuntimeError(
                "El recibo cambió durante la operación; no se realizaron cambios."
            )
        con.execute(
            """INSERT INTO action_history(username, action, details, created_at)
               VALUES(%s,%s,%s,%s)""",
            (
                username,
                "Eliminar recibo definitivamente",
                f"Recibo Nº {decision['numero']} · ID {decision['id']}",
                now_str(),
            ),
        )
        return decision


def permanently_delete_recibo(recibo_id: int, actor=None):
    """Compatibilidad con llamadas existentes."""
    return purge_receipt_permanently(recibo_id, actor)


def _trash_receipt_ids(*, receipt_ids=None, days=None):
    params = []
    filters = ["is_deleted=1"]
    if receipt_ids is not None:
        normalized = sorted({int(value) for value in receipt_ids})
        if not normalized:
            return []
        filters.append("id = ANY(%s)")
        params.append(normalized)
    if days is not None:
        cutoff = datetime.now() - timedelta(days=max(0, int(days)))
        filters.extend(["deleted_at IS NOT NULL", "deleted_at < %s"])
        params.append(cutoff.strftime("%Y-%m-%d %H:%M:%S"))
    with db_connect() as con:
        rows = con.execute(
            "SELECT id FROM recibos WHERE " + " AND ".join(filters)
            + " ORDER BY deleted_at, id",
            tuple(params),
        ).fetchall()
    return [int(row["id"]) for row in rows]


def preview_receipt_trash_cleanup(*, receipt_ids=None, days=None, actor=None):
    """Cuenta elegibles y protegidos sin bloquear ni modificar recibos."""
    _require_receipt_permission(
        actor, PERMISSION_MANAGE_TRASH,
        "Solo un administrador puede eliminar recibos permanentemente.",
    )
    ids = _trash_receipt_ids(receipt_ids=receipt_ids, days=days)
    eligible_ids = []
    protected_ids = []
    errors = []
    with db_connect() as con:
        for receipt_id in ids:
            try:
                decision = inspect_receipt_purgeability(con, receipt_id)
                target = eligible_ids if decision["purgable"] else protected_ids
                target.append(receipt_id)
            except Exception as exc:
                errors.append((receipt_id, type(exc).__name__))
    return {
        "total": len(ids),
        "eligible": len(eligible_ids),
        "protected": len(protected_ids),
        "errors": len(errors),
        "target_ids": tuple(ids),
        "eligible_ids": tuple(eligible_ids),
        "protected_ids": tuple(protected_ids),
    }


def purge_receipts_safely(*, receipt_ids=None, days=None, actor=None):
    """Procesa cada recibo con el servicio canónico; un protegido no aborta."""
    preview = preview_receipt_trash_cleanup(
        receipt_ids=receipt_ids, days=days, actor=actor,
    )
    deleted_rows = []
    protected = 0
    errors = 0
    for receipt_id in preview["target_ids"]:
        try:
            deleted_rows.append(purge_receipt_permanently(receipt_id, actor))
        except ReceiptProtectedError:
            protected += 1
        except Exception as exc:
            errors += 1
            write_runtime_log(
                "Purga de recibo ID " + str(receipt_id)
                + " falló: " + type(exc).__name__ + ": " + str(exc)
            )
    return {
        "total": preview["total"],
        "eligible": preview["eligible"],
        "deleted": len(deleted_rows),
        "protected": protected,
        "errors": errors + preview["errors"],
        "deleted_receipts": deleted_rows,
    }


def purge_old_deleted_receipts(days: int = 30, actor=None):
    """Compatibilidad: devuelve la lista eliminada por la limpieza segura."""
    return purge_receipts_safely(days=days, actor=actor)["deleted_receipts"]

def restore_recibo(recibo_id: int, restored_by=None):
    user, username = _require_receipt_permission(
        restored_by, PERMISSION_MANAGE_TRASH,
        "Tu rol no puede restaurar recibos de la papelera.",
    )
    with db_connect() as con:
        row = con.execute(
            """SELECT id, numero, nombre, fecha, estado_facturacion,
                      admission_atencion_id, admission_nss_snapshot,
                      admission_cedula_snapshot, admission_source_instance_id
               FROM recibos WHERE id=%s AND is_deleted=1 FOR UPDATE""",
            (int(recibo_id),),
        ).fetchone()
        if not row:
            raise ValueError("El recibo no existe en la papelera.")
        _guard_active_receipt_duplicate(
            con, nombre=row["nombre"], fecha=row["fecha"], username=username,
            attention_id=row["admission_atencion_id"],
            nss=row["admission_nss_snapshot"],
            cedula=row["admission_cedula_snapshot"],
            source_instance_id=row["admission_source_instance_id"],
            exclude_id=recibo_id,
        )
        previous_status = str(row["estado_facturacion"] or BILLING_UNCLASSIFIED)
        restored_status = BILLING_PENDING if previous_status == BILLING_INVOICED else previous_status
        restored_at = now_str()
        con.execute(
            """UPDATE recibos SET is_deleted=0, deleted_at=NULL, deleted_by=NULL, deleted_reason=NULL,
                      estado_facturacion=%s,
                      estado_facturacion_at=CASE WHEN %s='PENDIENTE' THEN %s ELSE estado_facturacion_at END,
                      estado_facturacion_por=CASE WHEN %s='PENDIENTE' THEN %s ELSE estado_facturacion_por END
               WHERE id=%s""",
            (restored_status, restored_status, restored_at, restored_status, username, int(recibo_id)),
        )
        if restored_status != previous_status:
            con.execute(
                """INSERT INTO recibo_facturacion_history(
                       recibo_id, estado_anterior, estado_nuevo, realizado_por, realizado_at,
                       motivo, total_al_momento, ars_al_momento, recibo_version
                   )
                   SELECT id, %s, %s, %s, %s, %s, total, ars, revision_version
                   FROM recibos WHERE id=%s""",
                (previous_status, restored_status, username, restored_at,
                 "Restaurado desde la papelera; requiere nueva validación", int(recibo_id)),
            )
        con.execute(
            "INSERT INTO action_history(username, action, details, created_at) VALUES(%s,%s,%s,%s)",
            (username, "Restaurar recibo", f"Recibo Nº {row['numero']} · ID {recibo_id}", restored_at),
        )
        return dict(row)

