def get_audit_workqueue_summary() -> dict:
    with db_connect() as con:
        row = con.execute(
            """SELECT COUNT(*), COALESCE(SUM(total),0),
                      COALESCE(MAX(GREATEST(0, CURRENT_DATE-NULLIF(created_at,'')::timestamp::date)),0),
                      COUNT(*) FILTER (
                          WHERE GREATEST(0, CURRENT_DATE-NULLIF(created_at,'')::timestamp::date)>=3
                      ),
                      COUNT(*) FILTER (WHERE auditoria_asignada_a IS NULL),
                      COUNT(*) FILTER (WHERE estado_documento='PRELIMINAR'),
                      COUNT(*) FILTER (WHERE estado_documento='LISTO_AUDITORIA')
               FROM recibos
               WHERE is_deleted=0 AND estado_facturacion='PENDIENTE'
                 AND """ + medication_ars_sql_exclusion("ars")
        ).fetchone()
        top = con.execute(
            """SELECT CASE
                         WHEN COALESCE(tipo_cobertura,'ASEGURADO')='NO_ASEGURADO'
                           THEN 'SIN SEGURO'
                         ELSE COALESCE(NULLIF(ars,''),'Sin ARS')
                       END, COUNT(*), COALESCE(SUM(total),0)
               FROM recibos
               WHERE is_deleted=0 AND estado_facturacion='PENDIENTE'
                 AND """ + medication_ars_sql_exclusion("ars") + """
               GROUP BY CASE
                          WHEN COALESCE(tipo_cobertura,'ASEGURADO')='NO_ASEGURADO'
                            THEN 'SIN SEGURO'
                          ELSE COALESCE(NULLIF(ars,''),'Sin ARS')
                        END
               ORDER BY COUNT(*) DESC, SUM(total) DESC LIMIT 1"""
        ).fetchone()
    return {
        "receipts": int(row[0] or 0),
        "total": float(row[1] or 0),
        "oldest_days": int(row[2] or 0),
        "overdue": int(row[3] or 0),
        "unassigned": int(row[4] or 0),
        "preliminary": int(row[5] or 0),
        "ready": int(row[6] or 0),
        "top_ars": str(top[0]) if top else "Sin pendientes",
        "top_ars_count": int(top[1] or 0) if top else 0,
    }


def get_receipt_history_metrics(*, _connection=None):
    """Resumen de estados y cola de auditoría en una sola consulta agrupada."""
    query = """
        WITH active AS (
            SELECT estado_facturacion,total,created_at,auditoria_asignada_a,
                   estado_documento,tipo_cobertura,ars
            FROM recibos WHERE is_deleted=0
              AND """ + medication_ars_sql_exclusion("ars") + """
        ), status_summary AS (
            SELECT COALESCE(estado_facturacion,%s) AS status,
                   COUNT(*) AS receipts,COALESCE(SUM(total),0) AS total
            FROM active GROUP BY COALESCE(estado_facturacion,%s)
        ), pending AS (
            SELECT COUNT(*) AS receipts,COALESCE(SUM(total),0) AS total,
                   COUNT(*) FILTER (
                       WHERE GREATEST(0,CURRENT_DATE-NULLIF(created_at,'')::timestamp::date)>=3
                   ) AS overdue,
                   COUNT(*) FILTER (
                       WHERE NULLIF(BTRIM(COALESCE(auditoria_asignada_a,'')),'') IS NULL
                   ) AS unassigned,
                   COUNT(*) FILTER (WHERE estado_documento='PRELIMINAR') AS preliminary,
                   COUNT(*) FILTER (WHERE estado_documento='LISTO_AUDITORIA') AS ready
            FROM active WHERE estado_facturacion='PENDIENTE'
        )
        SELECT s.status AS status,
               s.receipts AS status_receipts,
               s.total AS status_total,
               p.receipts AS pending_receipts,
               p.total AS pending_total,
               p.overdue AS pending_overdue,
               p.unassigned AS pending_unassigned,
               p.preliminary AS pending_preliminary,
               p.ready AS pending_ready
        FROM pending p LEFT JOIN status_summary s ON TRUE
        ORDER BY s.status NULLS LAST
    """
    params = (BILLING_UNCLASSIFIED, BILLING_UNCLASSIFIED)
    if _connection is not None:
        rows = _connection.execute(query, params).fetchall()
    else:
        with db_connect() as con:
            rows = con.execute(query, params).fetchall()
    summary = {status: {"receipts": 0, "total": 0.0} for status in BILLING_STATUSES}
    queue = {
        "receipts": 0, "total": 0.0, "overdue": 0,
        "unassigned": 0, "preliminary": 0, "ready": 0,
    }
    for raw_row in rows:
        row = dict(raw_row)
        status = str(row.get("status") or "")
        if status in summary:
            summary[status] = {
                "receipts": int(row.get("status_receipts") or 0),
                "total": float(row.get("status_total") or 0),
            }
        queue = {
            "receipts": int(row.get("pending_receipts") or 0),
            "total": float(row.get("pending_total") or 0),
            "overdue": int(row.get("pending_overdue") or 0),
            "unassigned": int(row.get("pending_unassigned") or 0),
            "preliminary": int(row.get("pending_preliminary") or 0),
            "ready": int(row.get("pending_ready") or 0),
        }
    return {"summary": summary, "queue": queue}


