def list_receipts_for_report(
    start_date: str, end_date: str, is_backdated: int = 0,
    ars_filter="Todas las ARS", user_filter="Todos los Usuarios",
    analysis_type: str = ANALYSIS_CONFIRMED,
):
    """Devuelve los recibos incluidos en un reporte usando la fecha real de generación (created_at).

    Mantiene ambas fechas:
    - fecha: fecha seleccionada/servicio.
    - created_at: fecha y hora en que el recibo fue generado.
    Solo se incluyen recibos con created_at definido.
    """
    scope_clauses, params, report_date_expr, _analysis = receipt_scope(
        "r", start_date, end_date, analysis_type
    )
    include_all_histories = is_backdated is None or str(is_backdated) == "-1"
    query = (
        "SELECT r.numero, r.nombre, r.fecha, r.created_at AS created_at, "
        "r.ars, r.total, r.username, r.estado_facturacion, r.estado_facturacion_at, "
        "r.estado_facturacion_por, r.referencia_facturacion, r.estado_documento, "
        "r.numero_autorizacion "
        "FROM recibos r "
        f"WHERE {' AND '.join(scope_clauses)} "
    )

    if not include_all_histories:
        query += " AND r.is_backdated = %s"
        params.append(int(is_backdated))

    ars_selection = _normalize_report_filter(ars_filter, "Todas las ARS")
    user_selection = _normalize_report_filter(user_filter, "Todos los Usuarios")
    for column, selection in (("r.ars", ars_selection), ("r.username", user_selection)):
        clause, value = _report_filter_clause(column, selection)
        if clause:
            query += clause
            params.append(value)

    query += f" ORDER BY {report_date_expr}, r.numero"

    with db_connect() as con:
        cur = con.execute(query, tuple(params))
        return [dict(r) for r in cur.fetchall()]

def report_exists(report_date: str) -> bool:
    with db_connect() as con:
        cur = con.execute("SELECT 1 FROM daily_reports WHERE report_date=%s", (report_date,))
        return cur.fetchone() is not None

def _report_snapshot_parts(payload):
    data = copy.deepcopy(payload or {})
    if not isinstance(data, dict):
        data = {"value": data}
    filters = data.get("filters") or data.get("_filters") or {}
    financial_basis = data.get("query") or data.get("_analysis") or {}
    summary = data.get("summary") or {
        key: value
        for key, value in data.items()
        if not str(key).startswith("_") and not isinstance(value, (dict, list))
    }
    charts = {
        key: data.get(key)
        for key in (
            "trend", "monthly", "categories", "category_distribution",
            "comparison", "coverage", "category_comparison",
        )
        if key in data
    }
    guided = data.get("guided_reading") or data.get("guide") or {}
    return data, filters, financial_basis, summary, charts, guided


def _standard_report_snapshot_payload(
    totals: dict, *, ars_filter, user_filter, coverage: str,
    is_backdated, analysis_type: str, period_type: str,
) -> dict:
    """Capture every selected filter without changing the report's visual totals."""
    analysis = analysis_definition(analysis_type)
    payload = copy.deepcopy(totals or {})
    payload["filters"] = {
        "ars": _normalize_report_filter(ars_filter, "Todas las ARS"),
        "user": _normalize_report_filter(user_filter, "Todos los Usuarios"),
        "coverage": str(coverage or "Todas"),
        "history_scope": "all" if is_backdated is None else int(is_backdated),
        "period_type": str(period_type or ""),
    }
    payload["query"] = {
        "analysis_type": analysis["key"],
        "analysis_label": analysis["label"],
        "statuses": list(analysis["statuses"]),
        "date_basis": analysis["date_basis"],
        "date_basis_label": DATE_BASIS_LABELS[analysis["date_basis"]],
    }
    return payload


def _save_report_snapshot_for_source(
    con, *, source_table, source_key, report_id, report_type,
    start_date, end_date, generated_at, generated_by, payload, context,
    generated_by_user_id=None, created_from_module="", report_generation_uuid="",
):
    data, filters, financial, summary, charts, guided = _report_snapshot_parts(
        payload
    )
    return save_report_document_snapshot(
        con,
        source_table=source_table,
        source_key_value=str(source_key),
        report_id=report_id,
        report_type=str(report_type or "Reporte"),
        report_title=str((context or {}).get("title") or report_type or "Reporte"),
        period_start=start_date or None,
        period_end=end_date or None,
        generated_at=generated_at,
        generated_by=generated_by,
        filters=filters,
        financial_basis=financial,
        dataset=data,
        summary=summary,
        charts=charts,
        guided_reading=guided,
        render_context=context or {},
        storage_mode=new_report_storage_mode(),
        generated_by_user_id=generated_by_user_id,
        created_from_module=created_from_module,
        report_generation_uuid=report_generation_uuid,
    )


def save_daily_report_record(
    report_date: str, filepath: str, totals: dict, generated_by: str,
    document_context: dict | None = None, generated_by_user_id=None,
    created_from_module: str = "reportes_diarios", snapshot_payload: dict | None = None,
):
    generated_at = now_str()
    stored_name = os.path.basename(str(filepath or ""))
    context = copy.deepcopy(
        document_context
        or _build_standard_report_context(
            "REPORTE DIARIO",
            f"Período: {report_date}",
            totals,
            generated_by,
            generated_at=generated_at,
        )
    )
    with db_connect() as con:
        row = con.execute(
            """INSERT INTO daily_reports(
                 report_date,generated_at,generated_by,filepath,totals_json,
                 document_storage_mode,is_deleted
               ) VALUES(%s,%s,%s,%s,%s,%s,FALSE)
               ON CONFLICT(report_date) DO UPDATE SET
                 generated_at=EXCLUDED.generated_at,
                 generated_by=EXCLUDED.generated_by,
                 filepath=EXCLUDED.filepath,
                 totals_json=EXCLUDED.totals_json,
                 document_storage_mode=EXCLUDED.document_storage_mode,
                 is_deleted=FALSE
               RETURNING id""",
            (
                report_date,
                generated_at,
                generated_by,
                stored_name,
                json.dumps(totals, ensure_ascii=False),
                new_report_storage_mode(),
            ),
        ).fetchone()
        record_id = int(row["id"])
        _save_report_snapshot_for_source(
            con,
            source_table="daily_reports",
            source_key=str(record_id),
            report_id=None,
            report_type="Diario",
            start_date=report_date,
            end_date=report_date,
            generated_at=generated_at,
            generated_by=generated_by,
            payload=snapshot_payload if snapshot_payload is not None else totals,
            context=context,
            generated_by_user_id=generated_by_user_id,
            created_from_module=created_from_module,
        )
    return record_id


