def list_daily_reports(limit: int = 200):
    with db_connect() as con:
        cur = con.execute(
            "SELECT id AS record_id, id::text AS source_key, "
            "'daily_reports' AS source_table, 'Diario' AS report_type, "
            "report_date AS start_date, report_date AS end_date, generated_at, "
            "generated_by, filepath, totals_json, document_storage_mode "
            "FROM daily_reports WHERE is_deleted=FALSE "
            "ORDER BY report_date DESC LIMIT %s",
            (int(limit),)
        )
        return [dict(r) for r in cur.fetchall()]

def list_report_history(limit: int = 300):
    with db_connect() as con:
        cur = con.execute(
            "SELECT id AS record_id, id::text AS source_key, "
            "'report_history' AS source_table, report_type, start_date, end_date, "
            "generated_at, generated_by, filepath, totals_json,document_storage_mode "
            "FROM report_history WHERE is_deleted=FALSE ORDER BY id DESC LIMIT %s",
            (int(limit),)
        )
        rows = [dict(r) for r in cur.fetchall()]
        closure_rows = con.execute(
            """SELECT turn_id AS record_id,
                      source_instance_id || '|' || turn_id::text AS source_key,
                      'billing_shift_closures' AS source_table,
                      'Cierre automático del turno de ' ||
                      COALESCE(NULLIF(representative,''),NULLIF(closed_by,''),
                               NULLIF(claimed_by,''),'Usuario no identificado') AS report_type,
                      operational_date AS start_date,operational_date AS end_date,
                      generated_at,COALESCE(NULLIF(representative,''),claimed_by) AS generated_by,
                       report_filename AS filepath,COALESCE(totals_json,'{}') AS totals_json,
                       document_storage_mode
               FROM billing_shift_closures
               WHERE report_filename IS NOT NULL
               ORDER BY generated_at DESC LIMIT %s""",
            (int(limit),),
        ).fetchall()
        rows.extend(dict(r) for r in closure_rows)
    rows.extend(list_daily_reports(limit))
    rows.sort(key=lambda r: (r.get("generated_at") or ""), reverse=True)
    return rows[:limit]

def delete_report_record(source_table: str, record_id: int, filepath: str = ""):
    allowed_tables = {"daily_reports", "report_history"}
    if source_table not in allowed_tables:
        raise ValueError("Tipo de reporte inválido.")

    stored_filepath = filepath or ""
    with db_connect() as con:
        cur = con.execute(f"SELECT filepath FROM {source_table} WHERE id=%s", (int(record_id),))
        row = cur.fetchone()
        if row and row["filepath"]:
            stored_filepath = row["filepath"]

        con.execute(
            f"UPDATE {source_table} SET is_deleted=TRUE WHERE id=%s",
            (int(record_id),),
        )

    filename = os.path.basename(stored_filepath or filepath or "")
    for candidate in {
        stored_filepath,
        stable_storage_path(REPORTS_DIR, filename),
    }:
        if candidate and os.path.exists(candidate):
            try:
                os.remove(candidate)
            except Exception:
                pass

def get_user_preferences(username: str) -> dict:
    with db_connect() as con:
        cur = con.execute("SELECT auto_add_guantes, auto_print, auto_add_bajante_cateter FROM user_preferences WHERE username=%s", (username,))
        row = cur.fetchone()
        if row:
            return {
                "auto_add_guantes": bool(row["auto_add_guantes"]),
                "auto_print": bool(row["auto_print"]),
                "auto_add_bajante_cateter": bool(row["auto_add_bajante_cateter"]),
            }
        return {"auto_add_guantes": True, "auto_print": False, "auto_add_bajante_cateter": True}

def upsert_user_preferences(username: str, auto_add_guantes: bool = None, auto_print: bool = None, auto_add_bajante_cateter: bool = None):
    with db_connect() as con:
        cur = con.execute("SELECT username FROM user_preferences WHERE username=%s", (username,))
        exists = cur.fetchone() is not None
        if not exists:
            con.execute(
                "INSERT INTO user_preferences(username, auto_add_guantes, auto_print, auto_add_bajante_cateter) VALUES(%s,%s,%s,%s)",
                (username, 1 if auto_add_guantes is None else (1 if auto_add_guantes else 0), 0 if auto_print is None else (1 if auto_print else 0), 1 if auto_add_bajante_cateter is None else (1 if auto_add_bajante_cateter else 0)),
            )
        else:
            sets = []
            params = []
            if auto_add_guantes is not None:
                sets.append("auto_add_guantes=%s")
                params.append(1 if auto_add_guantes else 0)
            if auto_print is not None:
                sets.append("auto_print=%s")
                params.append(1 if auto_print else 0)
            if auto_add_bajante_cateter is not None:
                sets.append("auto_add_bajante_cateter=%s")
                params.append(1 if auto_add_bajante_cateter else 0)
            if sets:
                params.append(username)
                con.execute(f"UPDATE user_preferences SET {', '.join(sets)} WHERE username=%s", tuple(params))

def list_user_catalog_favorites(username: str) -> set:
    """Favoritos personales; no cambian el catálogo ni sus precios."""
    if not username:
        return set()
    with db_connect() as con:
        cur = con.execute(
            """SELECT categoria, item_nombre
               FROM user_catalog_favorites
               WHERE username=%s""",
            (username,),
        )
        return {
            (str(row["categoria"]), str(row["item_nombre"]))
            for row in cur.fetchall()
        }

def set_user_catalog_favorite(
    username: str,
    categoria: str,
    item_nombre: str,
    enabled: bool,
) -> None:
    if not username or not categoria or not item_nombre:
        return
    with db_connect() as con:
        if enabled:
            con.execute(
                """INSERT INTO user_catalog_favorites(
                       username, categoria, item_nombre, created_at
                   ) VALUES(%s,%s,%s,%s)
                   ON CONFLICT(username, categoria, item_nombre) DO NOTHING""",
                (username, categoria, item_nombre, now_str()),
            )
        else:
            con.execute(
                """DELETE FROM user_catalog_favorites
                   WHERE username=%s AND categoria=%s AND item_nombre=%s""",
                (username, categoria, item_nombre),
            )

def rename_catalog_favorites(
    old_category: str,
    old_name: str,
    new_category: str,
    new_name: str,
) -> None:
    """Mantiene los favoritos personales al renombrar o mover un ítem."""
    with db_connect() as con:
        con.execute(
            """INSERT INTO user_catalog_favorites(
                   username, categoria, item_nombre, created_at
               )
               SELECT username, %s, %s, created_at
               FROM user_catalog_favorites
               WHERE categoria=%s AND item_nombre=%s
               ON CONFLICT(username, categoria, item_nombre) DO NOTHING""",
            (new_category, new_name, old_category, old_name),
        )
        con.execute(
            """DELETE FROM user_catalog_favorites
               WHERE categoria=%s AND item_nombre=%s
                 AND NOT (categoria=%s AND item_nombre=%s)""",
            (old_category, old_name, new_category, new_name),
        )

def delete_catalog_favorites(category: str, item_name: str) -> None:
    with db_connect() as con:
        con.execute(
            """DELETE FROM user_catalog_favorites
               WHERE categoria=%s AND item_nombre=%s""",
            (category, item_name),
        )

def get_user_receipt_counts() -> dict:
    with db_connect() as con:
        cur = con.execute("SELECT username, COUNT(id) AS c FROM recibos GROUP BY username")
        return {row["username"]: int(row["c"]) for row in cur.fetchall()}

def get_recibo_data(recibo_id: int):
    with db_connect() as con:
        cur = con.execute("SELECT * FROM recibos WHERE id=%s", (recibo_id,))
        recibo = dict(cur.fetchone())
        cur = con.execute("SELECT * FROM recibo_items WHERE recibo_id=%s", (recibo_id,))
        recibo["items"] = [dict(r) for r in cur.fetchall()]
        return recibo


def billing_status_label(status: str) -> str:
    normalized = str(status or BILLING_UNCLASSIFIED).upper()
    return BILLING_STATUS_LABELS.get(normalized, normalized.replace("_", " ").title())


def audit_assignment_matches(assignee: str, assignment_filter: str, username: str) -> bool:
    assigned_to = str(assignee or "").strip()
    current_user = str(username or "").strip()
    if assignment_filter == AUDIT_ASSIGNMENT_UNASSIGNED:
        return not assigned_to
    if assignment_filter == AUDIT_ASSIGNMENT_MINE:
        return bool(assigned_to and assigned_to == current_user)
    if assignment_filter == AUDIT_ASSIGNMENT_OTHERS:
        return bool(assigned_to and assigned_to != current_user)
    return True


def document_state_label(state: str) -> str:
    normalized = str(state or DOCUMENT_PRELIMINARY).upper()
    return DOCUMENT_STATE_LABELS.get(normalized, normalized.replace("_", " ").title())


def receipt_history_palette(status: str, document_state: str, is_dark: bool = False):
    status = str(status or BILLING_UNCLASSIFIED).upper()
    document_state = str(document_state or DOCUMENT_PRELIMINARY).upper()
    if status == BILLING_INVOICED:
        return ("#b8f3df", "#12382f") if is_dark else ("#075c42", "#e1f5ee")
    if status == BILLING_NOT_INVOICED:
        return ("#ffd6da", "#451e24") if is_dark else ("#8f1f2b", "#fde8eb")
    if status == BILLING_UNCLASSIFIED:
        return ("#e1e7ef", "#2d3540") if is_dark else ("#435466", "#e9eef4")
    if document_state == DOCUMENT_READY:
        return ("#d8ecff", "#17364b") if is_dark else ("#124f7c", "#e5f3ff")
    return ("#ffe3a3", "#493714") if is_dark else ("#7a4b00", "#fff3d6")


def audit_risk_label(score: int) -> str:
    value = int(score or 0)
    if value >= 60:
        return "Alta"
    if value >= 30:
        return "Media"
    return "Baja"


def _audit_preflight_from_connection(
    con,
    recibo_id: int,
    *,
    allow_unlinked: bool = False,
) -> dict:
    row = con.execute(
        """SELECT id, numero, nombre, fecha, dx, ars, tipo_cobertura, sala, total,
                  created_at, is_backdated, pdf_synced, estado_facturacion,
                  numero_autorizacion, estado_documento, admission_atencion_id,
                  admission_nss_snapshot, admission_cedula_snapshot,
                  admission_source_instance_id, document_storage_mode,
                  verification_bypassed, receipt_origin,
                  EXISTS(
                      SELECT 1 FROM recibo_document_versions v
                      WHERE v.recibo_id=recibos.id AND v.is_current=TRUE
                  ) AS snapshot_available
           FROM recibos WHERE id=%s""",
        (int(recibo_id),),
    ).fetchone()
    if not row:
        raise ValueError("El recibo no existe.")
    item_row = con.execute(
        """SELECT COUNT(*), COALESCE(SUM(total), 0)
           FROM recibo_items WHERE recibo_id=%s""",
        (int(recibo_id),),
    ).fetchone()
    item_count = int(item_row[0] or 0)
    items_total = float(item_row[1] or 0)
    room = float(row["sala"] or 0)
    receipt_total = float(row["total"] or 0)
    calculated_total = items_total + room
    duplicate_rows = con.execute(
        """SELECT numero FROM recibos
           WHERE id<>%s AND is_deleted=0
             AND LOWER(TRIM(COALESCE(nombre,'')))=LOWER(TRIM(%s))
             AND COALESCE(fecha,'')=COALESCE(%s,'')
             AND COALESCE(ars,'')=COALESCE(%s,'')
             AND ABS(COALESCE(total,0)-%s)<0.01
           ORDER BY id DESC LIMIT 5""",
        (
            int(recibo_id), str(row["nombre"] or ""), str(row["fecha"] or ""),
            str(row["ars"] or ""), receipt_total,
        ),
    ).fetchall()
    duplicates = [int(candidate[0]) for candidate in duplicate_rows]
    coverage = str(row["tipo_cobertura"] or "ASEGURADO").upper()
    authorization_number = str(row["numero_autorizacion"] or "").strip()
    storage_mode = str(row["document_storage_mode"] or STORAGE_LEGACY)
    document_available = (
        bool(row["snapshot_available"])
        if storage_mode in (STORAGE_SNAPSHOT, STORAGE_HYBRID)
        else bool(int(row["pdf_synced"] or 0))
    )
    checks = {
        "patient_identity": bool(str(row["nombre"] or "").strip()),
        "admission_link": bool(row["admission_atencion_id"])
        or bool(row["verification_bypassed"])
        or bool(allow_unlinked),
        "coverage_eligibility": coverage == "NO_ASEGURADO" or bool(str(row["ars"] or "").strip()),
        "authorization_validity": coverage == "NO_ASEGURADO" or bool(authorization_number),
        "clinical_documentation": bool(str(row["dx"] or "").strip()),
        "charge_accuracy": (
            item_count > 0
            and receipt_total > 0
            and abs(calculated_total - receipt_total) <= max(0.01, receipt_total * 0.001)
        ),
        "duplicate_review": not duplicates,
        "document_available": document_available,
        "pdf_synced": bool(int(row["pdf_synced"] or 0)),
    }
    blockers = []
    if not checks["patient_identity"]:
        blockers.append("Falta el nombre o identificación del paciente.")
    if not checks["admission_link"]:
        blockers.append(
            "El recibo no está vinculado con una atención validada de Admisión."
        )
    if not checks["coverage_eligibility"]:
        blockers.append("El recibo asegurado no tiene una ARS definida.")
    if not checks["authorization_validity"]:
        blockers.append(
            "Falta el número de autorización. El documento continúa como preliminar."
        )
    if not checks["clinical_documentation"]:
        blockers.append("Falta el diagnóstico o soporte clínico.")
    if item_count <= 0:
        blockers.append("El recibo no contiene servicios o artículos facturables.")
    if receipt_total <= 0:
        blockers.append("El total del recibo debe ser mayor que cero.")
    elif abs(calculated_total - receipt_total) > max(0.01, receipt_total * 0.001):
        blockers.append(
            f"El total no coincide: detalle y sala RD$ {calculated_total:,.2f}; "
            f"recibo RD$ {receipt_total:,.2f}."
        )
    if not checks["document_available"]:
        blockers.append(
            "El recibo no tiene una versión documental disponible."
            if storage_mode != STORAGE_LEGACY
            else "El PDF histórico todavía no está sincronizado."
        )
    warnings = []
    if not row["admission_atencion_id"] and checks["admission_link"]:
        warnings.append("Sin vínculo a atención; requiere motivo reforzado al confirmar.")
    if duplicates:
        warnings.append(
            "Posible duplicado con recibo(s): " + ", ".join(str(value) for value in duplicates)
        )
    if int(row["is_backdated"] or 0):
        warnings.append("El recibo fue generado con fecha de servicio atrasada.")
    try:
        generated = datetime.fromisoformat(str(row["created_at"] or "")[:19])
        age_days = max(0, (datetime.now() - generated).days)
    except (TypeError, ValueError):
        age_days = 0
    risk = min(
        100,
        len(blockers) * 20
        + (35 if duplicates else 0)
        + (15 if int(row["is_backdated"] or 0) else 0)
        + (15 if receipt_total >= 10000 else 10 if receipt_total >= 5000 else 0)
        + (15 if age_days >= 7 else 8 if age_days >= 3 else 0),
    )
    result = {
        "receipt_id": int(row["id"]),
        "receipt_number": int(row["numero"]),
        "checks": checks,
        "blockers": blockers,
        "warnings": warnings,
        "duplicates": duplicates,
        "item_count": item_count,
        "items_total": items_total,
        "room": room,
        "receipt_total": receipt_total,
        "authorization_number": authorization_number,
        "admission_attention_id": (
            int(row["admission_atencion_id"])
            if row["admission_atencion_id"] is not None else None
        ),
        "admission_source_instance_id": str(
            row["admission_source_instance_id"] or "LEGACY"
        ),
        "verification_bypassed": bool(row["verification_bypassed"]),
        "receipt_origin": str(row["receipt_origin"] or "LEGACY_UNLINKED"),
        "document_state": str(row["estado_documento"] or DOCUMENT_PRELIMINARY),
        "calculated_total": calculated_total,
        "age_days": age_days,
        "risk_score": risk,
        "risk_label": audit_risk_label(risk),
        "ready": not blockers,
    }
    con.execute(
        "UPDATE recibos SET auditoria_preflight_json=%s, auditoria_riesgo=%s WHERE id=%s",
        (json.dumps(result, ensure_ascii=False), risk, int(recibo_id)),
    )
    return result


def get_receipt_audit_preflight(recibo_id: int, actor=None) -> dict:
    with db_connect() as con:
        return _audit_preflight_from_connection(
            con,
            int(recibo_id),
            allow_unlinked=can_confirm_unlinked_receipt(_receipt_actor(actor)),
        )


def assign_receipt_for_audit(recibo_id: int, actor, release: bool = False):
    username, user = _actor_context(actor)
    if not user_has_permission(user, PERMISSION_VIEW_BILLING_AUDIT):
        raise PermissionError("Tu rol no puede gestionar la cola de auditoría.")
    with db_connect() as con:
        row = con.execute(
            """SELECT id, numero, ars, total, estado_facturacion, revision_version,
                      auditoria_asignada_a, estado_documento
               FROM recibos WHERE id=%s FOR UPDATE""",
            (int(recibo_id),),
        ).fetchone()
        if not row:
            raise ValueError("El recibo no existe.")
        status = str(row["estado_facturacion"] or BILLING_UNCLASSIFIED)
        if status not in (BILLING_PENDING, BILLING_UNCLASSIFIED):
            raise ValueError("Solo los recibos pendientes pueden asignarse para auditoría.")
        if (
            not release
            and str(row["estado_documento"] or DOCUMENT_PRELIMINARY) != DOCUMENT_READY
        ):
            raise ValueError(
                "El recibo aún es preliminar. Incorpora el número de autorización "
                "antes de enviarlo a auditoría."
            )
        current_assignee = str(row["auditoria_asignada_a"] or "")
        if not release and current_assignee and current_assignee != username:
            raise PermissionError(
                f"Este recibo ya está asignado a {current_assignee}."
            )
        if release and current_assignee and current_assignee != username and not is_administrator(user):
            raise PermissionError("Solo quien tiene asignado el recibo o un administrador puede liberarlo.")
        assigned_to = None if release else username
        assigned_at = None if release else now_str()
        con.execute(
            "UPDATE recibos SET auditoria_asignada_a=%s, auditoria_asignada_at=%s WHERE id=%s",
            (assigned_to, assigned_at, int(recibo_id)),
        )
        event_at = now_str()
        con.execute(
            """INSERT INTO recibo_facturacion_history(
                   recibo_id, estado_anterior, estado_nuevo, realizado_por, realizado_at,
                   motivo, evento_tipo, total_al_momento, ars_al_momento, recibo_version
               ) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
            (
                int(recibo_id), status, status, username, event_at,
                "Recibo liberado de la cola" if release else "Recibo tomado para revisión",
                "LIBERACION" if release else "ASIGNACION",
                float(row["total"] or 0), str(row["ars"] or ""),
                int(row["revision_version"] or 0),
            ),
        )
        con.execute(
            "INSERT INTO action_history(username, action, details, created_at) VALUES(%s,%s,%s,%s)",
            (
                username, "Liberar auditoría" if release else "Asignar auditoría",
                f"Recibo {row['numero']}", event_at,
            ),
        )
    return get_recibo_data(int(recibo_id))


def _actor_context(actor):
    if isinstance(actor, dict):
        return str(actor.get("username") or "Sistema"), actor
    username = str(actor or "Sistema")
    try:
        stored = get_user(username)
        return username, dict(stored) if stored else {"username": username, "role": ""}
    except Exception:
        return username, {"username": username, "role": ""}


def change_receipt_billing_status(
    recibo_id: int,
    new_status: str,
    actor,
    reason: str = "",
    observation: str = "",
    reference: str = "",
    reason_code: str = "",
    checklist: dict = None,
):
    """Cambia el estado financiero y registra una fotografía inmutable del evento."""
    target = str(new_status or "").upper().strip()
    if target not in BILLING_STATUSES:
        raise ValueError("Estado de facturación no válido.")
    username, user = _actor_context(actor)
    permission_by_target = {
        BILLING_INVOICED: PERMISSION_VALIDATE_RECEIPT,
        BILLING_NOT_INVOICED: PERMISSION_MARK_NOT_INVOICED,
        BILLING_PENDING: PERMISSION_REOPEN_RECEIPT,
    }
    required_permission = permission_by_target.get(target, PERMISSION_VIEW_BILLING_AUDIT)
    if not user_has_permission(user, required_permission):
        raise PermissionError("Tu rol no tiene permiso para realizar este cambio de facturación.")

    reason = str(reason or "").strip()
    observation = str(observation or "").strip()
    reference = str(reference or "").strip()
    reason_code = str(reason_code or "").strip().upper()
    checklist = dict(checklist or {})
    with db_connect() as con:
        row = con.execute(
            """SELECT id, numero, ars, total, estado_facturacion, revision_version,
                      pdf_synced, is_deleted, is_backdated, auditoria_asignada_a,
                      numero_autorizacion, estado_documento, tipo_cobertura
               FROM recibos WHERE id=%s FOR UPDATE""",
            (int(recibo_id),),
        ).fetchone()
        if not row:
            raise ValueError("El recibo no existe.")
        if int(row["is_deleted"] or 0):
            raise ValueError("Restaura el recibo antes de cambiar su estado de facturación.")
        current = str(row["estado_facturacion"] or BILLING_UNCLASSIFIED).upper()
        assigned_to = str(row.get("auditoria_asignada_a") or "")
        if (
            target in (BILLING_INVOICED, BILLING_NOT_INVOICED)
            and assigned_to and assigned_to != username and not is_administrator(user)
        ):
            raise PermissionError(
                f"Este recibo está asignado a {assigned_to}. Debe liberarse antes de validarlo."
            )
        if current == target:
            raise ValueError(f"El recibo ya está en estado {billing_status_label(target)}.")
        allowed = {
            BILLING_PENDING: {BILLING_INVOICED, BILLING_NOT_INVOICED},
            BILLING_INVOICED: {BILLING_PENDING},
            BILLING_NOT_INVOICED: {BILLING_PENDING},
            BILLING_UNCLASSIFIED: {BILLING_PENDING, BILLING_INVOICED, BILLING_NOT_INVOICED},
        }
        if target not in allowed.get(current, set()):
            raise ValueError(
                f"No se permite cambiar directamente de {billing_status_label(current)} "
                f"a {billing_status_label(target)}."
            )
        if target == BILLING_INVOICED:
            preflight = _audit_preflight_from_connection(
                con,
                int(recibo_id),
                allow_unlinked=can_confirm_unlinked_receipt(user),
            )
            if preflight["blockers"]:
                raise ValueError(
                    "El recibo no está listo para facturarse:\n\n- "
                    + "\n- ".join(preflight["blockers"])
                )
            admission_attention_id = preflight.get("admission_attention_id")
            if not admission_attention_id:
                if not can_confirm_unlinked_receipt(user):
                    raise PermissionError(
                        "Tu rol no puede confirmar recibos sin una atención vinculada."
                    )
                if len(reason) < 8:
                    raise ValueError(
                        "Debes indicar un motivo adicional para confirmar sin atención."
                    )
            if admission_attention_id:
                try:
                    live_attention = get_projected_billable_attention(
                        int(admission_attention_id),
                        str(
                            preflight.get("admission_source_instance_id")
                            or "LEGACY"
                        ),
                        current_user=user,
                    )
                except Exception as exc:
                    raise ValueError(
                        "No se pudo verificar la atención central antes de "
                        f"confirmar:\n{exc}"
                    ) from exc
                if not live_attention:
                    raise ValueError(
                        "La atención vinculada fue anulada, pasó a Urgencia o "
                        "requiere revisión de identidad. No puede confirmarse."
                    )
            missing_checks = [
                label for key, label in AUDIT_CHECKLIST_ITEMS.items()
                if not bool(checklist.get(key))
            ]
            if missing_checks:
                raise ValueError(
                    "Debes completar toda la lista de verificación antes de confirmar:\n\n- "
                    + "\n- ".join(missing_checks)
                )
        else:
            preflight = _audit_preflight_from_connection(con, int(recibo_id))
        preflight = dict(preflight)
        preflight["actor_context"] = {
            "role": normalize_role(user.get("role")),
            "device": str(os.environ.get("COMPUTERNAME") or "ESTACION"),
            "result": "COMPLETED",
        }
        if target in (BILLING_NOT_INVOICED, BILLING_PENDING) and not reason:
            raise ValueError("Debes indicar el motivo del cambio de estado.")
        if target == BILLING_NOT_INVOICED and reason_code not in AUDIT_REASON_CODES:
            reason_code = "OTHER"

        revision = int(row["revision_version"] or 0)
        if target == BILLING_PENDING and current in (BILLING_INVOICED, BILLING_NOT_INVOICED):
            revision += 1
            preflight = dict(preflight)
            preflight["reopening_effect"] = {
                "removed_from_confirmed_reports": current == BILLING_INVOICED,
                "amount_removed": float(row["total"] or 0) if current == BILLING_INVOICED else 0.0,
                "requires_pdf_regeneration": True,
                "requires_new_audit": True,
            }
        event_type = (
            "UNLINKED_RECEIPT_CONFIRMED_BILLED"
            if target == BILLING_INVOICED and not preflight.get("admission_attention_id")
            else "REAPERTURA_FINANCIERA"
            if target == BILLING_PENDING and current == BILLING_INVOICED
            else "REAPERTURA_CORRECCION"
            if target == BILLING_PENDING
            else "CAMBIO_ESTADO"
        )
        changed_at = now_str()
        affected_draft_batches = []
        if target == BILLING_PENDING and current == BILLING_INVOICED:
            closed_cursor = con.execute(
                """SELECT b.id, b.period_year, b.period_month, b.ars
                   FROM billing_batch_receipts br
                   JOIN billing_batches b ON b.id=br.batch_id
                   WHERE br.recibo_id=%s AND br.included=1
                     AND b.status='CERRADO'""",
                (int(recibo_id),),
            )
            closed = closed_cursor.fetchall() if hasattr(closed_cursor, "fetchall") else []
            if closed:
                raise ValueError(
                    "El recibo pertenece a un listado mensual cerrado. "
                    "Reabre o corrige primero ese listado para conservar la trazabilidad."
                )
            draft_cursor = con.execute(
                """SELECT b.id
                   FROM billing_batch_receipts br
                   JOIN billing_batches b ON b.id=br.batch_id
                   WHERE br.recibo_id=%s AND br.included=1
                     AND b.status='BORRADOR'
                   FOR UPDATE""",
                (int(recibo_id),),
            )
            draft_rows = draft_cursor.fetchall() if hasattr(draft_cursor, "fetchall") else []
            affected_draft_batches = [
                int(item["id"])
                for item in draft_rows
            ]
            for batch_id in affected_draft_batches:
                con.execute(
                    """UPDATE billing_batch_receipts
                       SET included=0, removed_at=%s, removed_by=%s,
                           removal_reason=%s
                       WHERE batch_id=%s AND recibo_id=%s AND included=1""",
                    (
                        changed_at,
                        username,
                        "Retirado automáticamente al reabrir el recibo",
                        batch_id,
                        int(recibo_id),
                    ),
                )
                con.execute(
                    """INSERT INTO billing_batch_events(
                           batch_id, recibo_id, event_type, performed_at,
                           performed_by, details
                       ) VALUES(%s,%s,'RETIRO_POR_REAPERTURA',%s,%s,%s)""",
                    (
                        batch_id, int(recibo_id), changed_at, username, reason,
                    ),
                )
                con.execute(
                    """UPDATE billing_batches
                       SET updated_at=%s, updated_by=%s WHERE id=%s""",
                    (changed_at, username, batch_id),
                )
            if affected_draft_batches:
                preflight = dict(preflight)
                preflight["reopening_effect"]["draft_batches_removed"] = (
                    affected_draft_batches
                )
        con.execute(
            """UPDATE recibos
               SET estado_facturacion=%s, estado_facturacion_at=%s, estado_facturacion_por=%s,
                   motivo_no_facturado=%s, observacion_facturacion=%s,
                   referencia_facturacion=%s, revision_version=%s,
                   motivo_no_facturado_codigo=%s, auditoria_asignada_a=%s,
                   auditoria_asignada_at=CASE WHEN %s='PENDIENTE' THEN NULL
                                              ELSE COALESCE(auditoria_asignada_at,%s) END,
                   auditoria_checklist_json=%s, auditoria_preflight_json=%s,
                   auditoria_riesgo=%s,
                   pdf_synced=CASE
                       WHEN %s='PENDIENTE' AND document_storage_mode='LEGACY_PDF'
                       THEN 0 ELSE pdf_synced END,
                   pdf_sync_error=CASE WHEN %s='PENDIENTE'
                                            AND document_storage_mode='LEGACY_PDF'
                                       THEN 'Reabierto: requiere regenerar el PDF histórico'
                                       ELSE pdf_sync_error END,
                   estado_documento=CASE
                       WHEN %s='FACTURADO' THEN 'FINAL'
                       WHEN %s='PENDIENTE'
                            AND (COALESCE(tipo_cobertura,'ASEGURADO')='NO_ASEGURADO'
                                 OR NULLIF(TRIM(COALESCE(numero_autorizacion,'')),'') IS NOT NULL)
                           THEN 'LISTO_AUDITORIA'
                       WHEN %s='PENDIENTE' THEN 'PRELIMINAR'
                       ELSE estado_documento END
               WHERE id=%s""",
            (
                target,
                changed_at,
                username,
                reason if target == BILLING_NOT_INVOICED else None,
                observation or None,
                reference if target == BILLING_INVOICED else None,
                revision,
                reason_code if target == BILLING_NOT_INVOICED else None,
                username if target in (BILLING_INVOICED, BILLING_NOT_INVOICED) else None,
                target,
                changed_at,
                json.dumps(checklist, ensure_ascii=False) if target == BILLING_INVOICED else None,
                None if target == BILLING_PENDING else json.dumps(preflight, ensure_ascii=False),
                0 if target == BILLING_PENDING else int(preflight["risk_score"]),
                target, target,
                target, target, target,
                int(recibo_id),
            ),
        )
        con.execute(
            """INSERT INTO recibo_facturacion_history(
                   recibo_id, estado_anterior, estado_nuevo, realizado_por, realizado_at,
                   motivo, observacion, referencia, evento_tipo, motivo_codigo,
                   checklist_json, preflight_json, riesgo,
                   total_al_momento, ars_al_momento, recibo_version
               ) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
            (
                int(recibo_id), current, target, username, changed_at, reason or None,
                observation or None, reference or None, event_type,
                reason_code or None,
                json.dumps(checklist, ensure_ascii=False) if checklist else None,
                json.dumps(preflight, ensure_ascii=False), int(preflight["risk_score"]),
                float(row["total"] or 0), str(row["ars"] or ""), revision,
            ),
        )
        document_version = save_receipt_document_snapshot(
            con,
            int(recibo_id),
            username,
        )
        con.execute(
            "INSERT INTO action_history(username, action, details, created_at) VALUES(%s,%s,%s,%s)",
            (
                username,
                (
                    "UNLINKED_RECEIPT_CONFIRMED_BILLED"
                    if event_type == "UNLINKED_RECEIPT_CONFIRMED_BILLED"
                    else "Cambiar estado de facturación"
                ),
                (
                    f"Recibo {row['numero']}: {current} -> {target}. {reason} "
                    f"Documento v{document_version['version']}."
                ).strip(),
                changed_at,
            ),
        )
    return get_recibo_data(int(recibo_id))


def validate_receipts_as_invoiced_bulk(
    receipt_ids,
    current_user,
    progress_callback=None,
):
    """Procesa N recibos con la misma validación transaccional del flujo individual."""
    user = dict(current_user or {})
    if not is_administrator(user):
        raise PermissionError(
            "Solo el Administrador puede validar recibos masivamente."
        )
    unique_ids = list(dict.fromkeys(
        int(receipt_id) for receipt_id in receipt_ids if int(receipt_id) > 0
    ))
    checklist = {key: True for key in AUDIT_CHECKLIST_ITEMS}
    completed = []
    already_invoiced = []
    failed = []
    total = len(unique_ids)
    for index, receipt_id in enumerate(unique_ids, start=1):
        try:
            change_receipt_billing_status(
                receipt_id,
                BILLING_INVOICED,
                user,
                reason="Validación masiva administrativa",
                observation="Confirmado mediante selección múltiple administrativa.",
                reference="VALIDACION_MASIVA",
                checklist=checklist,
            )
            completed.append(receipt_id)
        except ValueError as exc:
            if "ya está en estado" in str(exc).casefold():
                already_invoiced.append(receipt_id)
            else:
                failed.append({"receipt_id": receipt_id, "error": str(exc)})
        except Exception as exc:
            failed.append({"receipt_id": receipt_id, "error": str(exc)})
        if callable(progress_callback):
            progress_callback(index, total)
    summary = {
        "requested": total,
        "completed": len(completed),
        "already_invoiced": len(already_invoiced),
        "failed": len(failed),
        "completed_ids": completed,
        "already_invoiced_ids": already_invoiced,
        "failures": failed,
    }
    log_action(
        str(user.get("username") or "Administrador"),
        "BULK_RECEIPTS_MARKED_INVOICED",
        (
            f"Solicitados {total}; completados {len(completed)}; "
            f"ya facturados {len(already_invoiced)}; fallidos {len(failed)}."
        ),
    )
    return summary


def get_receipt_billing_history(recibo_id: int):
    with db_connect() as con:
        rows = con.execute(
            """SELECT estado_anterior, estado_nuevo, realizado_por, realizado_at,
                      motivo, observacion, referencia, total_al_momento,
                      ars_al_momento, recibo_version, evento_tipo, motivo_codigo,
                      checklist_json, preflight_json, riesgo
               FROM recibo_facturacion_history
               WHERE recibo_id=%s ORDER BY id DESC""",
            (int(recibo_id),),
        ).fetchall()
        return [dict(row) for row in rows]


def get_billing_status_summary():
    summary = {status: {"receipts": 0, "total": 0.0} for status in BILLING_STATUSES}
    with db_connect() as con:
        rows = con.execute(
            """SELECT estado_facturacion, COUNT(*), COALESCE(SUM(total), 0)
               FROM recibos WHERE is_deleted=0 GROUP BY estado_facturacion"""
        ).fetchall()
    for row in rows:
        status = str(row[0] or BILLING_UNCLASSIFIED)
        if status in summary:
            summary[status] = {"receipts": int(row[1] or 0), "total": float(row[2] or 0)}
    return summary

def _to_float(raw: str):
    if raw is None: return None
    v = re.sub(r'[^0-9,.\-]', '', raw)
    if not v: return None
    if ',' in v and '.' in v:
        if v.rfind('.') > v.rfind(','): v = v.replace(',', '')
        else: v = v.replace('.', '').replace(',', '.')
    elif ',' in v:
        left, right = v.rsplit(',', 1)
        if right.isdigit() and 1 <= len(right) <= 2: v = left.replace(',', '') + '.' + right
        else: v = v.replace(',', '')
    try: return float(v)
    except Exception: return None

def _parse_price(text: str):
    if text is None: return None
    if '$' in text:
        tail = text.rsplit('$', 1)[-1]
        return _to_float(tail)
    nums = re.findall(r'(-?\d[\d.,]*)', text)
    if not nums: return None
    return _to_float(nums[-1])

def _norm_cat(txt: str):
    if not txt: return None
    t = txt.strip().casefold()
    if 'medic' in t: return 'Medicamentos'
    if 'mater' in t: return 'Materiales'
    return None

def _norm_ars_cat(txt: str):
    if not txt: return None
    t = txt.strip().casefold()
    t = t.replace('á', 'a').replace('é', 'e').replace('í', 'i').replace('ó', 'o').replace('ú', 'u')
    if 'laborat' in t: return 'Laboratorios'
    if 'imagen' in t: return 'Imágenes'
    if 'proced' in t: return 'Procedimientos'
    if 'honorario' in t: return 'Honorarios'
    return None

def apply_price_rule(category: str, base_price: float) -> float:
    return round(float(base_price), 2)


MEDICATION_MARKUP_SETTING_KEY = "medication_markup_percent"
DEFAULT_MEDICATION_MARKUP_PERCENT = 35.0
_medication_markup_lock = threading.RLock()
_medication_markup_state = {
    "percent": DEFAULT_MEDICATION_MARKUP_PERCENT,
    "version": 0,
}


def update_medication_markup_cache(percent, version=0) -> float:
    value = max(0.0, min(100.0, float(percent)))
    with _medication_markup_lock:
        _medication_markup_state["percent"] = value
        _medication_markup_state["version"] = int(version or 0)
    return value


def get_medication_markup_percent(*, force_refresh=False) -> float:
    """Return the central markup without doing I/O from normal UI calculations."""
    if force_refresh:
        with db_connect() as con:
            row = con.execute(
                """SELECT numeric_value,version
                   FROM billing_pricing_settings WHERE setting_key=%s""",
                (MEDICATION_MARKUP_SETTING_KEY,),
            ).fetchone()
        if row:
            update_medication_markup_cache(row["numeric_value"], row["version"])
    with _medication_markup_lock:
        return float(_medication_markup_state["percent"])


def calculate_medication_price(base_price: float, percent=None) -> float:
    markup = (
        get_medication_markup_percent()
        if percent is None else max(0.0, min(100.0, float(percent)))
    )
    return round(float(base_price) * (1.0 + markup / 100.0), 2)


def medication_base_price_from_effective(effective_price: float, percent=None) -> float:
    markup = get_medication_markup_percent() if percent is None else float(percent)
    return round(float(effective_price) / (1.0 + markup / 100.0), 2)


def set_medication_markup_percent(percent: float, current_user: dict) -> float:
    if not user_is_admin(current_user):
        raise PermissionError("Solo el administrador puede cambiar el recargo.")
    value = max(0.0, min(100.0, float(percent)))
    username = str(current_user.get("username") or "Sistema")
    device_id, device_name = _local_device_identity()
    with db_connect() as con:
        previous = con.execute(
            """SELECT numeric_value FROM billing_pricing_settings
               WHERE setting_key=%s FOR UPDATE""",
            (MEDICATION_MARKUP_SETTING_KEY,),
        ).fetchone()
        previous_value = float(previous["numeric_value"]) if previous else DEFAULT_MEDICATION_MARKUP_PERCENT
        row = con.execute(
            """INSERT INTO billing_pricing_settings(
                   setting_key,numeric_value,version,updated_at,updated_by
               ) VALUES(%s,%s,1,NOW(),%s)
               ON CONFLICT(setting_key) DO UPDATE SET
                   numeric_value=EXCLUDED.numeric_value,
                   version=billing_pricing_settings.version+1,
                   updated_at=NOW(),updated_by=EXCLUDED.updated_by
               RETURNING version""",
            (MEDICATION_MARKUP_SETTING_KEY, value, username),
        ).fetchone()
        details = (
            f"{previous_value:.2f}% → {value:.2f}% · "
            f"Dispositivo {device_name} ({device_id})"
        )
        _insert_action_history(
            con, username, "MEDICATION_MARKUP_CHANGED", details,
            module="Facturación", entity_type="configuración_precios",
            entity_id=MEDICATION_MARKUP_SETTING_KEY,
            role=current_user.get("role", ""), ars_name="CATÁLOGO UNIVERSAL",
        )
    update_medication_markup_cache(value, row["version"] if row else 0)
    return value


def get_effective_price(category: str, stored_price: float) -> float:
    stored_price = float(stored_price)
    if category == 'Medicamentos':
        return calculate_medication_price(stored_price)
    return round(stored_price, 2)

def set_button_role(button: QPushButton, role: str, *, is_dark: bool = False):
    tokens = visual_theme_tokens(bool(is_dark))
    role_key = {
        "success": "success",
        "danger": "danger",
        "warning": "warning",
        "info": "primary",
        "report": "primary",
        "primary": "primary",
        "neutral": "neutral",
        "secondary": "secondary",
    }.get(str(role or "").lower(), "primary")
    button.setProperty("visualRole", role_key)
    base = tokens[f"button_{role_key}_bg"]
    hover = tokens[f"button_{role_key}_hover"]
    text = tokens[f"button_{role_key}_text"]
    pressed = tokens["button_primary_hover"] if role_key != "neutral" else tokens["border_strong"]
    border = f"1px solid {tokens['border']}" if role_key in {"neutral", "secondary"} else "none"
    disabled_bg = tokens["input_disabled_bg"]
    disabled_text = tokens["text_disabled"]
    disabled_border = tokens["border"]
    button.setStyleSheet(
        f"QPushButton {{ background-color: {base}; color: {text}; "
        f"border: {border}; border-radius: 8px; padding: 8px 14px; "
        "min-height: 20px; font-weight: 700; }"
        f"QPushButton:hover {{ background-color: {hover}; }}"
        f"QPushButton:pressed {{ background-color: {pressed}; padding-top: 9px; padding-bottom: 7px; }}"
        f"QPushButton:focus {{ outline: none; border: 2px solid {tokens['border_focus']}; }}"
        f"QPushButton:disabled {{ background-color: {disabled_bg}; color: {disabled_text}; border-color: {disabled_border}; }}"
    )


def apply_combo_popup_theme(combo: QComboBox, is_dark: bool) -> None:
    """Theme the native popup container owned by a QComboBox."""
    tokens = visual_theme_tokens(bool(is_dark))
    view_qss = (
        f"QAbstractItemView {{ background-color: {tokens['popup_bg']}; "
        f"color: {tokens['text_primary']}; border: 1px solid {tokens['border']}; "
        "outline: 0; padding: 2px; "
        f"selection-background-color: {tokens['selection_bg']}; "
        f"selection-color: {tokens['selection_text']}; }}"
    )
    view = combo.view()
    view.setStyleSheet(view_qss)
    view.viewport().setStyleSheet(
        f"background-color: {tokens['popup_bg']}; color: {tokens['text_primary']};"
    )
    popup = view.window()
    if popup is not None:
        popup.setStyleSheet(
            f"background-color: {tokens['popup_bg']}; "
            f"border: 1px solid {tokens['border']};"
        )


def apply_completer_popup_theme(completer: QCompleter, is_dark: bool) -> None:
    """Apply the shared palette to the real popup owned by ``QCompleter``."""
    tokens = visual_theme_tokens(bool(is_dark))
    view = completer.popup()
    view.setStyleSheet(
        f"QAbstractItemView {{ background-color: {tokens['popup_bg']}; "
        f"color: {tokens['text_primary']}; border: 1px solid {tokens['border']}; "
        "outline: 0; padding: 3px; "
        f"selection-background-color: {tokens['selection_bg']}; "
        f"selection-color: {tokens['selection_text']}; }}"
        f"QAbstractItemView::item {{ min-height: 28px; padding: 4px 8px; }}"
        f"QAbstractItemView::item:hover {{ background: {tokens['input_hover_bg']}; "
        f"color: {tokens['text_primary']}; }}"
    )
    view.viewport().setStyleSheet(
        f"background-color: {tokens['popup_bg']}; color: {tokens['text_primary']};"
    )


def load_boot_theme_preference() -> bool:
    """Read only the last visual mode needed before a user can authenticate."""
    return bool(QSettings("SIGEH", "Visual").value("dark_mode", False, type=bool))


def store_boot_theme_preference(is_dark: bool) -> None:
    """Mirror the current theme for the next pre-login frame."""
    QSettings("SIGEH", "Visual").setValue("dark_mode", bool(is_dark))


def refresh_button_roles(root: QWidget, is_dark: bool) -> None:
    """Reapply semantic button roles after a live theme transition."""
    for button in root.findChildren(QPushButton):
        role = button.property("visualRole")
        if role:
            set_button_role(button, str(role), is_dark=bool(is_dark))


class NoWheelTabBar(QTabBar):
    """Evita cambiar de sección accidentalmente con la rueda del mouse."""

    def wheelEvent(self, event):
        event.ignore()


class MultiSelectFilter(QToolButton):
    """Abre un diálogo transaccional: los cambios solo se guardan al aplicar."""

    selectionChanged = Signal()

    def __init__(self, values, empty_text="Todos", item_name="elemento", feminine=False, parent=None):
        super().__init__(parent)
        self.empty_text = empty_text
        self.item_name = item_name
        self.feminine = feminine
        self._mode = "include"
        self._values = [str(value) for value in values]
        self._selected = set()
        self.setToolButtonStyle(Qt.ToolButtonTextOnly)
        self.setArrowType(Qt.DownArrow)
        self.clicked.connect(self._open_dialog)
        self._refresh_summary(emit=False)

    def mode(self):
        return self._mode

    def set_mode(self, mode):
        self._mode = "exclude" if mode in ("exclude", "excluir") else "include"
        self._refresh_summary()

    def filter_data(self):
        return {"mode": self._mode, "values": self.selected_values()}

    def selected_values(self):
        return [value for value in self._values if value in self._selected]

    def set_values(self, values, preserve=True):
        next_values = list(dict.fromkeys(str(value) for value in values if value))
        previous = set(self._selected) if preserve else set()
        self._values = next_values
        self._selected = previous.intersection(next_values)
        self._refresh_summary(emit=False)

    def clear_selection(self):
        self._selected.clear()
        self._refresh_summary()

    def select_all(self):
        self._selected = set(self._values)
        self._refresh_summary()

    def _refresh_summary(self, emit=True):
        values = self.selected_values()
        if not values:
            self.setText(self.empty_text)
        else:
            noun = self.item_name
            if len(values) != 1 and noun != "ARS":
                noun += "es" if noun.endswith("r") else "s"
            suffix = (
                ("excluida" if self.feminine else "excluido")
                if self._mode == "exclude"
                else ("incluida" if self.feminine else "incluido")
            )
            if len(values) != 1:
                suffix += "s"
            self.setText(f"{len(values)} {noun} {suffix}")
        mode_text = "Excluir" if self._mode == "exclude" else "Incluir"
        self.setToolTip(
            f"{mode_text}: {', '.join(values)}" if values else self.empty_text
        )
        if emit:
            self.selectionChanged.emit()

    def _open_dialog(self):
        dialog = QDialog(self)
        dialog.setObjectName("MultiSelectFilterDialog")
        dialog.setWindowTitle(f"Filtrar {self.item_name}")
        dialog.setMinimumSize(500, 560)
        root = QVBoxLayout(dialog)
        root.setContentsMargins(18, 16, 18, 16)
        root.setSpacing(11)

        title = QLabel(f"Filtrar {self.item_name}")
        title.setObjectName("FilterDialogTitle")
        title.setStyleSheet("font-size: 16pt; font-weight: 900;")
        root.addWidget(title)

        root.addWidget(QLabel("Modo del filtro:"))
        mode_row = QHBoxLayout()
        include_radio = QRadioButton("Incluir seleccionadas")
        exclude_radio = QRadioButton("Excluir seleccionadas")
        include_radio.setChecked(self._mode == "include")
        exclude_radio.setChecked(self._mode == "exclude")
        mode_row.addWidget(include_radio)
        mode_row.addWidget(exclude_radio)
        mode_row.addStretch(1)
        root.addLayout(mode_row)

        search = QLineEdit()
        search.setPlaceholderText(f"Buscar {self.item_name}...")
        root.addWidget(search)

        choices = QListWidget()
        for value in self._values:
            item = QListWidgetItem(value)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(Qt.Checked if value in self._selected else Qt.Unchecked)
            choices.addItem(item)
        root.addWidget(choices, 1)

        def filter_choices(text):
            term = (text or "").strip().casefold()
            for index in range(choices.count()):
                item = choices.item(index)
                item.setHidden(bool(term and term not in item.text().casefold()))

        def set_all(state):
            for index in range(choices.count()):
                choices.item(index).setCheckState(state)

        search.textChanged.connect(filter_choices)

        buttons = QHBoxLayout()
        select_all = QPushButton("Seleccionar todas")
        clear = QPushButton("Limpiar")
        cancel = QPushButton("Cancelar")
        apply_button = QPushButton("Aplicar filtro")
        select_all.clicked.connect(lambda: set_all(Qt.Checked))
        clear.clicked.connect(lambda: set_all(Qt.Unchecked))
        cancel.clicked.connect(dialog.reject)
        apply_button.clicked.connect(dialog.accept)
        for secondary_button in (select_all, clear, cancel):
            secondary_button.setObjectName("FilterSecondaryButton")
        set_button_role(apply_button, "report")
        buttons.addWidget(select_all)
        buttons.addWidget(clear)
        buttons.addStretch(1)
        buttons.addWidget(cancel)
        buttons.addWidget(apply_button)
        root.addLayout(buttons)

        search.setFocus()
        if dialog.exec() != QDialog.Accepted:
            return
        self._mode = "exclude" if exclude_radio.isChecked() else "include"
        self._selected = {
            choices.item(index).text()
            for index in range(choices.count())
            if choices.item(index).checkState() == Qt.Checked
        }
        self._refresh_summary()


class MonthPickerButton(QToolButton):
    monthChanged = Signal(int)
    MONTHS = [
        "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
        "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre",
    ]

    def __init__(self, month=None, parent=None):
        super().__init__(parent)
        self._month = int(month or QDate.currentDate().month())
        self.setPopupMode(QToolButton.InstantPopup)
        menu = QMenu(self)
        for index, label in enumerate(self.MONTHS, 1):
            action = menu.addAction(label)
            action.triggered.connect(lambda _checked=False, value=index: self.set_month(value))
        self.setMenu(menu)
        self._refresh_text()

    def month(self):
        return self._month

    def set_month(self, month):
        month = max(1, min(12, int(month)))
        if month == self._month:
            return
        self._month = month
        self._refresh_text()
        self.monthChanged.emit(month)

    def _refresh_text(self):
        self.setText(self.MONTHS[self._month - 1])


def resolve_period_range(
    period_type,
    year=None,
    period_value=None,
    custom_start=None,
    custom_end=None,
    anchor_date=None,
):
    """Resuelve un período calendario y su período anterior de forma única."""
    period_type = str(period_type or "Mensual")
    today = QDate.currentDate()
    year = int(year or today.year())
    anchor = anchor_date if isinstance(anchor_date, QDate) else today
    start = end = None
    number = None

    if period_type == "Diario":
        start = end = anchor
        label = f"Día {anchor.toString('dd/MM/yyyy')}"
        previous_start = previous_end = anchor.addDays(-1)
        previous_label = previous_start.toString("dd/MM/yyyy")
    elif period_type == "Semanal":
        maximum_week = QDate(year, 12, 28).weekNumber()[0]
        number = max(1, min(maximum_week, int(period_value or anchor.weekNumber()[0])))
        first_week_monday = QDate(year, 1, 4)
        first_week_monday = first_week_monday.addDays(-(first_week_monday.dayOfWeek() - 1))
        start = first_week_monday.addDays((number - 1) * 7)
        end = start.addDays(6)
        label = f"Semana {number} de {year}"
        previous_start, previous_end = start.addDays(-7), end.addDays(-7)
        previous_week, previous_year = previous_start.weekNumber()
        previous_label = f"Semana {previous_week} de {previous_year}"
    elif period_type == "Mensual":
        number = max(1, min(12, int(period_value or today.month())))
        start = QDate(year, number, 1)
        end = start.addMonths(1).addDays(-1)
        label = f"{MonthPickerButton.MONTHS[number - 1]} de {year}"
        previous_start, previous_end = start.addMonths(-1), start.addDays(-1)
        previous_label = (
            f"{MonthPickerButton.MONTHS[previous_start.month() - 1]} de {previous_start.year()}"
        )
    elif period_type == "Trimestral":
        number = max(1, min(4, int(period_value or ((today.month() - 1) // 3 + 1))))
        start = QDate(year, (number - 1) * 3 + 1, 1)
        end = start.addMonths(3).addDays(-1)
        names = ["Primer", "Segundo", "Tercer", "Cuarto"]
        label = f"{names[number - 1]} trimestre de {year}"
        previous_start, previous_end = start.addMonths(-3), start.addDays(-1)
        previous_number = (previous_start.month() - 1) // 3 + 1
        previous_label = f"{names[previous_number - 1]} trimestre de {previous_start.year()}"
    elif period_type == "Semestral":
        number = max(1, min(2, int(period_value or (1 if today.month() <= 6 else 2))))
        start = QDate(year, 1 if number == 1 else 7, 1)
        end = start.addMonths(6).addDays(-1)
        names = ["Primer", "Segundo"]
        label = f"{names[number - 1]} semestre de {year}"
        previous_start, previous_end = start.addMonths(-6), start.addDays(-1)
        previous_number = 1 if previous_start.month() == 1 else 2
        previous_label = f"{names[previous_number - 1]} semestre de {previous_start.year()}"
    elif period_type == "Anual":
        start, end = QDate(year, 1, 1), QDate(year, 12, 31)
        label = f"Año {year}"
        previous_start, previous_end = QDate(year - 1, 1, 1), QDate(year - 1, 12, 31)
        previous_label = f"Año {year - 1}"
    else:
        start = custom_start if isinstance(custom_start, QDate) else today
        end = custom_end if isinstance(custom_end, QDate) else start
        label = "Período personalizado"
        previous_end = start.addDays(-1)
        previous_start = previous_end.addDays(-start.daysTo(end))
        previous_label = (
            f"Período anterior del {previous_start.toString('dd/MM/yyyy')} "
            f"al {previous_end.toString('dd/MM/yyyy')}"
        )

    return {
        "period_type": period_type,
        "period_year": year if period_type in (
            "Semanal", "Mensual", "Trimestral", "Semestral", "Anual"
        ) else start.year(),
        "period_number": number,
        "period_label": label,
        "start_date": start.toString("yyyy-MM-dd"),
        "end_date": end.toString("yyyy-MM-dd"),
        "comparison_label": previous_label,
        "comparison_start": previous_start.toString("yyyy-MM-dd"),
        "comparison_end": previous_end.toString("yyyy-MM-dd"),
    }


class PeriodSelectorWidget(QWidget):
    """Selector reutilizable para panel, reportes y comparaciones."""

    periodChanged = Signal(dict)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._updating = False
        self._layout_mode = None
        self.layout_grid = QGridLayout(self)
        self.layout_grid.setContentsMargins(0, 0, 0, 0)
        self.layout_grid.setHorizontalSpacing(12)
        self.layout_grid.setVerticalSpacing(7)

        # Parent every field immediately. Calling setVisible(True) on a
        # parentless control creates a short-lived top-level window.
        self.period_type = QComboBox(self)
        self.period_type.addItems(
            ["Diario", "Semanal", "Mensual", "Trimestral", "Semestral", "Anual", "Personalizado"]
        )
        self.period_type.setCurrentText("Mensual")
        self.year = QSpinBox(self)
        self.year.setRange(2000, 2100)
        self.year.setValue(QDate.currentDate().year())
        self.month = QComboBox(self)
        self.month.addItems(MonthPickerButton.MONTHS)
        self.month.setCurrentIndex(QDate.currentDate().month() - 1)
        self.week = QComboBox(self)
        self.quarter = QComboBox(self)
        self.quarter.addItems([
            "Primer trimestre - enero a marzo",
            "Segundo trimestre - abril a junio",
            "Tercer trimestre - julio a septiembre",
            "Cuarto trimestre - octubre a diciembre",
        ])
        self.quarter.setCurrentIndex((QDate.currentDate().month() - 1) // 3)
        self.semester = QComboBox(self)
        self.semester.addItems([
            "Primer semestre - enero a junio",
            "Segundo semestre - julio a diciembre",
        ])
        self.semester.setCurrentIndex(0 if QDate.currentDate().month() <= 6 else 1)
        self._refresh_week_options()
        for combo in (self.period_type, self.week, self.month, self.quarter, self.semester):
            combo.setSizeAdjustPolicy(QComboBox.AdjustToMinimumContentsLengthWithIcon)
            combo.setMinimumContentsLength(12)
        self.anchor_date = QDateEdit(QDate.currentDate(), self)
        self.custom_from = QDateEdit(QDate.currentDate(), self)
        self.custom_to = QDateEdit(QDate.currentDate(), self)
        for field in (self.anchor_date, self.custom_from, self.custom_to):
            field.setCalendarPopup(True)
            field.setDisplayFormat("dd/MM/yyyy")

        self.summary = QLabel(self)
        self.summary.setWordWrap(True)
        self.summary.setObjectName("ModernInfoBand")
        self._fields = [
            (QLabel("Tipo de período:"), self.period_type),
            (QLabel("Semana:"), self.week),
            (QLabel("Mes:"), self.month),
            (QLabel("Trimestre:"), self.quarter),
            (QLabel("Semestre:"), self.semester),
            (QLabel("Año:"), self.year),
            (QLabel("Fecha de referencia:"), self.anchor_date),
            (QLabel("Desde:"), self.custom_from),
            (QLabel("Hasta:"), self.custom_to),
        ]
        for _label, field in self._fields:
            _label.setParent(self)
            field.setMinimumWidth(150)
            field.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

        self.period_type.currentTextChanged.connect(self._changed)
        self.year.valueChanged.connect(self._year_changed)
        self.week.currentIndexChanged.connect(self._changed)
        self.month.currentIndexChanged.connect(self._changed)
        self.quarter.currentIndexChanged.connect(self._changed)
        self.semester.currentIndexChanged.connect(self._changed)
        self.anchor_date.dateChanged.connect(self._changed)
        self.custom_from.dateChanged.connect(self._changed)
        self.custom_to.dateChanged.connect(self._changed)
        self._changed()

    def definition(self):
        period_type = self.period_type.currentText()
        value = None
        if period_type == "Mensual":
            value = self.month.currentIndex() + 1
        elif period_type == "Semanal":
            value = self.week.currentData() or self.week.currentIndex() + 1
        elif period_type == "Trimestral":
            value = self.quarter.currentIndex() + 1
        elif period_type == "Semestral":
            value = self.semester.currentIndex() + 1
        return resolve_period_range(
            period_type,
            year=self.year.value(),
            period_value=value,
            custom_start=self.custom_from.date(),
            custom_end=self.custom_to.date(),
            anchor_date=self.anchor_date.date(),
        )

    def _changed(self, *_args):
        if self._updating:
            return
        period_type = self.period_type.currentText()
        visible_widgets = {self.period_type}
        if period_type == "Diario":
            visible_widgets.add(self.anchor_date)
        elif period_type == "Semanal":
            visible_widgets.update((self.week, self.year))
        elif period_type == "Mensual":
            visible_widgets.update((self.year, self.month))
        elif period_type == "Trimestral":
            visible_widgets.update((self.year, self.quarter))
        elif period_type == "Semestral":
            visible_widgets.update((self.year, self.semester))
        elif period_type == "Anual":
            visible_widgets.add(self.year)
        else:
            visible_widgets.update((self.custom_from, self.custom_to))

        visible_fields = [(label, field) for label, field in self._fields if field in visible_widgets]
        self._visible_fields = visible_fields
        self._arrange_fields()
        definition = self.definition()
        display_start = QDate.fromString(definition["start_date"], "yyyy-MM-dd").toString("dd/MM/yyyy")
        display_end = QDate.fromString(definition["end_date"], "yyyy-MM-dd").toString("dd/MM/yyyy")
        self.summary.setText(
            f"{definition['period_label']}   ·   "
            f"Fechas aplicadas: {display_start} al {display_end}"
        )
        self.periodChanged.emit(definition)

    def _year_changed(self, *_args):
        self._refresh_week_options()
        self._changed()

    def _refresh_week_options(self):
        year = self.year.value()
        previous_week = self.week.currentData() if self.week.count() else None
        current_date = QDate.currentDate()
        preferred = (
            current_date.weekNumber()[0] if year == current_date.weekNumber()[1]
            else int(previous_week or 1)
        )
        maximum_week = QDate(year, 12, 28).weekNumber()[0]
        first_monday = QDate(year, 1, 4)
        first_monday = first_monday.addDays(-(first_monday.dayOfWeek() - 1))
        self.week.blockSignals(True)
        self.week.clear()
        for week_number in range(1, maximum_week + 1):
            start = first_monday.addDays((week_number - 1) * 7)
            end = start.addDays(6)
            start_month = MonthPickerButton.MONTHS[start.month() - 1].lower()
            end_month = MonthPickerButton.MONTHS[end.month() - 1].lower()
            if start.month() == end.month():
                dates = f"{start.day()} al {end.day()} de {end_month}"
            else:
                dates = f"{start.day()} de {start_month} al {end.day()} de {end_month}"
            self.week.addItem(f"Semana {week_number} - {dates}", week_number)
        self.week.setCurrentIndex(max(0, min(maximum_week, preferred) - 1))
        self.week.blockSignals(False)

    def _arrange_fields(self):
        visible_fields = getattr(self, "_visible_fields", [])
        for label, field in self._fields:
            # Reparent/layout first and reveal last. This avoids painting a
            # child at a temporary geometry during responsive rearrangement.
            label.hide()
            field.hide()
            self.layout_grid.removeWidget(label)
            self.layout_grid.removeWidget(field)
        self.summary.hide()
        self.layout_grid.removeWidget(self.summary)
        for column in range(4):
            self.layout_grid.setColumnStretch(column, 0)

        width = self.width()
        if width < 480:
            mode = "stacked"
        elif width < 700 and len(visible_fields) == 3:
            mode = "two_rows"
        else:
            mode = "horizontal"
        self._layout_mode = mode

        if mode == "stacked":
            row = 0
            for label, field in visible_fields:
                self.layout_grid.addWidget(label, row, 0)
                self.layout_grid.addWidget(field, row + 1, 0)
                row += 2
            summary_row, summary_span = row, 1
            self.layout_grid.setColumnStretch(0, 1)
        elif mode == "two_rows":
            for column, (label, field) in enumerate(visible_fields[:2]):
                self.layout_grid.addWidget(label, 0, column)
                self.layout_grid.addWidget(field, 1, column)
                self.layout_grid.setColumnStretch(column, 1)
            label, field = visible_fields[2]
            self.layout_grid.addWidget(label, 2, 0, 1, 2)
            self.layout_grid.addWidget(field, 3, 0, 1, 2)
            summary_row, summary_span = 4, 2
        else:
            for column, (label, field) in enumerate(visible_fields):
                self.layout_grid.addWidget(label, 0, column)
                self.layout_grid.addWidget(field, 1, column)
                self.layout_grid.setColumnStretch(column, 1)
            summary_row, summary_span = 2, max(1, len(visible_fields))
        self.layout_grid.addWidget(self.summary, summary_row, 0, 1, summary_span)
        for label, field in visible_fields:
            label.show()
            field.show()
        self.summary.show()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        previous_mode = self._layout_mode
        width = event.size().width()
        new_mode = "stacked" if width < 480 else (
            "two_rows" if width < 700 and len(getattr(self, "_visible_fields", [])) == 3
            else "horizontal"
        )
        if new_mode != previous_mode:
            self._arrange_fields()


class ComparisonPdfDialog(QDialog):
    """Vista previa, guardado e impresión del PDF comparativo ya generado."""

    def __init__(self, pdf_path, parent=None, dialog_title="Reporte comparativo listo", detail_text=None):
        super().__init__(parent)
        self.pdf_path = pdf_path
        self.setWindowTitle("Vista previa de la comparación")
        self.setMinimumWidth(620)
        root = QVBoxLayout(self)
        title = QLabel(dialog_title)
        title.setStyleSheet("font-size: 16pt; font-weight: 900; color: #123F83;")
        detail = QLabel(detail_text or (
            "El documento se generó con la misma información que está visible en el panel. "
            "Revísalo antes de imprimir o guarda una copia en otra ubicación."
        ))
        detail.setWordWrap(True)
        detail.setStyleSheet(
            "background: #F3F7FC; color: #36516E; padding: 12px; border-radius: 8px;"
        )
        filename = QLabel(os.path.basename(pdf_path))
        filename.setWordWrap(True)
        filename.setStyleSheet("font-weight: 800; color: #31475F; padding: 6px 2px;")
        root.addWidget(title)
        root.addWidget(detail)
        root.addWidget(filename)
        buttons_card = QWidget()
        buttons_card.setObjectName("ModernActionBar")
        buttons = QHBoxLayout(buttons_card)
        buttons.setContentsMargins(10, 8, 10, 8)
        preview = QPushButton("Vista previa")
        save = QPushButton("Guardar PDF")
        print_button = QPushButton("Imprimir")
        close = QPushButton("Cerrar")
        set_button_role(preview, "report")
        set_button_role(save, "success")
        set_button_role(print_button, "report")
        set_button_role(close, "neutral")
        buttons.addWidget(preview)
        buttons.addWidget(save)
        buttons.addWidget(print_button)
        buttons.addStretch(1)
        buttons.addWidget(close)
        root.addWidget(buttons_card)
        preview.clicked.connect(self.open_preview)
        save.clicked.connect(self.save_copy)
        print_button.clicked.connect(self.print_pdf)
        close.clicked.connect(self.accept)

    def _printer(self):
        printer = QPrinter(QPrinter.HighResolution)
        printer.setPageOrientation(QPageLayout.Landscape)
        return printer

    def _paint_pdf(self, printer):
        document = QPdfDocument(self)
        document.load(self.pdf_path)
        if document.pageCount() <= 0:
            return
        painter = QPainter(printer)
        try:
            for page_index in range(document.pageCount()):
                if page_index:
                    printer.newPage()
                page_rect = printer.pageRect(QPrinter.Unit.DevicePixel)
                page_size = QSize(int(page_rect.width()), int(page_rect.height()))
                target = QSize(page_size)
                target.scale(QSize(2400, 2400), Qt.KeepAspectRatio)
                image = document.render(page_index, target)
                scaled = image.size().scaled(page_size, Qt.KeepAspectRatio)
                x = page_rect.x() + (page_rect.width() - scaled.width()) // 2
                y = page_rect.y() + (page_rect.height() - scaled.height()) // 2
                painter.drawImage(QRectF(x, y, scaled.width(), scaled.height()), image)
        finally:
            painter.end()

    def open_preview(self):
        printer = self._printer()
        dialog = QPrintPreviewDialog(printer, self)
        dialog.setWindowTitle("Vista previa - Reporte comparativo")
        dialog.resize(1100, 760)
        dialog.paintRequested.connect(self._paint_pdf)
        dialog.exec()

    def print_pdf(self):
        printer = self._printer()
        dialog = QPrintDialog(printer, self)
        if dialog.exec() == QDialog.Accepted:
            self._paint_pdf(printer)

    def save_copy(self):
        default_name = os.path.basename(self.pdf_path)
        destination, _ = QFileDialog.getSaveFileName(
            self, "Guardar reporte comparativo", default_name, "PDF (*.pdf)"
        )
        if not destination:
            return
        if not destination.lower().endswith(".pdf"):
            destination += ".pdf"
        try:
            shutil.copy2(self.pdf_path, destination)
            FloatingToast("Copia del reporte guardada", self).show()
        except Exception as exc:
            QMessageBox.critical(self, "Guardar PDF", f"No se pudo guardar la copia:\n{exc}")

def _clean_name(s: str):
    s = (s or '').strip()
    if '$' in s: s = s.rsplit('$', 1)[0]
    s = re.sub(r'[\s\-\–\—\|\:]+$', '', s).strip()
    s = re.sub(r'\s+', ' ', s)
    return s


