def normalize_catalog_name(raw_name: str) -> str:
    """Normaliza nombres importados sin alterar dosis, tamaños ni marcas."""
    name = str(raw_name or "").strip().upper()
    name = re.sub(r"^[\s•·●▪◦*\-–—]+", "", name)
    name = name.replace("“", '"').replace("”", '"').replace("''", '""')
    name = re.sub(r"\s+", " ", name)
    name = re.sub(r"\(\s+", "(", name)
    name = re.sub(r"\s+\)", ")", name)
    name = re.sub(r"\s*/\s*", "/", name)
    for incorrect, correct in CATALOG_SPELLING_CORRECTIONS.items():
        name = re.sub(rf"\b{re.escape(incorrect)}\b", correct, name)
    return name.strip(" -–—,.;")


def catalog_identity_key(raw_name: str) -> str:
    """Compara ítems ignorando viñetas, acentos y espacios de formato."""
    normalized = remove_accents(normalize_catalog_name(raw_name)).casefold()
    return re.sub(r"[^a-z0-9]+", "", normalized)


def _ditto_base(previous_name: str) -> str:
    """Obtiene el nombre base para líneas Word que usan comillas de repetición."""
    base = normalize_catalog_name(previous_name)
    base = re.sub(r"\s+(?:#\s*)?\d+(?:[.,]\d+)?\s*$", "", base)
    return base.strip()


def _parse_word_price_token(token: str):
    """Interpreta separadores dominicanos sin confundir 3.400 con 3.40."""
    value = str(token or "").strip().replace(" ", "")
    if re.fullmatch(r"\d{1,3}(?:\.\d{3})+", value):
        value = value.replace(".", "")
    return _parse_price(value)


def parse_universal_catalog_line(raw_text: str, previous_name: str = "") -> list[tuple[str, float]]:
    """Convierte una línea Word en uno o varios ítems independientes."""
    text = str(raw_text or "").strip()
    if not text:
        return []
    text = text.replace("RD$", "$")
    ditto = bool(re.match(r'^\s*(?:""|″|〃)', text))
    if ditto:
        text = re.sub(r'^\s*(?:""|″|〃)\s*', f"{_ditto_base(previous_name)} ", text, count=1)

    prices = list(re.finditer(r"\$\s*([0-9][0-9.,]*)", text))
    if not prices:
        return []

    upper = remove_accents(text).upper()
    is_multi_sonda = "SONDA" in upper and "VIA" in upper and len(prices) > 1
    if is_multi_sonda:
        first_prefix = text[:prices[0].start()]
        base_match = re.match(r"^(.*?\b(?:2|3)\s*V[IÍ]AS?)\b(.*)$", first_prefix, re.I)
        base = normalize_catalog_name(base_match.group(1) if base_match else first_prefix)
        variants = []
        prior_end = len(base_match.group(1)) if base_match else 0
        for index, match in enumerate(prices):
            segment_start = prior_end if index == 0 else prices[index - 1].end()
            variant_text = text[segment_start:match.start()]
            size = re.findall(r"#?\s*(\d+(?:[.,]\d+)?)", variant_text)
            if not size:
                continue
            price = _parse_word_price_token(match.group(1))
            if price is not None:
                variants.append((f"{base} (#{size[-1]})", float(price)))
        return variants

    # Explicaciones como "equivale a $ 2.60" no son el precio del ítem;
    # el precio final de la línea es el que se importa.
    match = prices[-1]
    price = _parse_word_price_token(match.group(1))
    if price is None:
        return []
    before = text[:match.start()].strip()
    after = text[match.end():].strip(" ,;.-")
    if after:
        before = f"{before} {after}"
    name = normalize_catalog_name(_clean_name(before))
    return [(name, float(price))] if name else []

def open_file_path(path: str) -> bool:
    try:
        if sys.platform.startswith("win"): os.startfile(path)
        elif sys.platform == "darwin": os.system(f'open "{path}"')
        else: os.system(f'xdg-open "{path}"')
        return True
    except Exception:
        return False

def stable_storage_path(folder: str, stored_path_or_filename: str) -> str:
    """Devuelve una ruta estable en la carpeta actual de la app usando solo el nombre del archivo.
    Esto evita errores cuando un PDF fue creado desde una carpeta temporal de PyInstaller (_MEI...).
    """
    filename = os.path.basename(stored_path_or_filename or "")
    if not filename:
        return ""
    return os.path.join(folder, filename)

_MONTHS_ES = r"(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)"
_MONTH_LINE_RE = re.compile(rf"^\s*\(?\s*{_MONTHS_ES}\s*\)?(?:\s*(?:de)?\s*\d{{4}})?\s*$", re.IGNORECASE)

def _looks_like_month_or_month_year(txt: str) -> bool:
    return bool(txt and _MONTH_LINE_RE.match(txt.strip()))

def user_can_manage_catalog(user: dict) -> bool:
    return bool(user) and user.get("role") in (ROLE_AUX, ROLE_ADMIN, ROLE_AUDIT)

def normalize_role(role) -> str:
    normalized = remove_accents(str(role or "")).strip().lower()
    if normalized in {"admin", "administrator", "administrador"}:
        return ROLE_ADMIN
    return normalized

def is_administrator(user: dict) -> bool:
    return bool(user) and normalize_role(user.get("role")) == ROLE_ADMIN

def user_is_admin(user: dict) -> bool:
    return is_administrator(user)


def _is_privileged_billing_role(user: dict) -> bool:
    return normalize_role((user or {}).get("role")) in {ROLE_ADMIN, ROLE_AUDIT}


def can_access_billing_admission_history(user: dict) -> bool:
    """El historial localiza atenciones; la matriz decide si se pueden usar."""
    return normalize_role((user or {}).get("role")) in {
        ROLE_AUX, ROLE_AUDIT, ROLE_ADMIN,
    }


def evaluate_admission_billing_access(
    attention: dict | None,
    current_user: dict | None,
    current_operational_state: dict | None = None,
) -> dict:
    """Matriz canónica de alcance de turno para Facturación."""
    data = dict(attention or {})
    state = dict(current_operational_state or {})
    role = normalize_role((current_user or {}).get("role"))
    current_turn = state.get("turn_id")
    try:
        is_current = current_turn is not None and int(data.get("turn_id") or 0) == int(current_turn)
    except (TypeError, ValueError):
        is_current = False
    if current_turn is None:
        is_current = str(data.get("turn_scope") or "").upper() in {"CURRENT", "TURNO ACTUAL"}
    inherited = bool(data.get("explicitly_inherited")) or str(
        data.get("turn_scope") or ""
    ).upper() in {"INHERITED", "HEREDADA", "HEREDADA DEL TURNO ANTERIOR"}
    scope = "CURRENT" if is_current else "INHERITED" if inherited else "HISTORICAL"
    receipt_id = data.get("linked_receipt_id") or data.get("receipt_id")
    billing_status = str(
        data.get("linked_billing_status") or data.get("estado_facturacion") or "SIN_RECIBO"
    ).upper()
    completed = billing_status in {"COMPLETO", "FACTURADO", "FINAL"} or bool(
        receipt_id and str(
            data.get("linked_document_status") or data.get("estado_documento") or ""
        ).upper() == "FINAL"
    )
    scope_allowed = scope in {"CURRENT", "INHERITED"} or role in {ROLE_AUDIT, ROLE_ADMIN}
    reason_code = (
        f"{scope}_PENDING_ALLOWED" if scope_allowed and not completed
        else "ALREADY_BILLED" if completed
        else "HISTORICAL_ROLE_DENIED"
    )
    return {
        "turn_scope": scope,
        "billing_status": billing_status,
        "receipt_id": receipt_id,
        "can_use_for_billing": bool(scope_allowed and not completed and not receipt_id),
        "can_continue_receipt": bool(scope_allowed and not completed and receipt_id),
        "can_open_receipt": bool(scope_allowed and completed and receipt_id),
        "can_reopen_completed": bool(scope_allowed and completed and role == ROLE_ADMIN and receipt_id),
        "reason_code": reason_code,
    }


def can_bypass_patient_verification(user: dict) -> bool:
    return _is_privileged_billing_role(user)


def can_confirm_unlinked_receipt(user: dict) -> bool:
    return _is_privileged_billing_role(user)


def can_view_uninsured_patients(user: dict) -> bool:
    return _is_privileged_billing_role(user)

def user_can_manage_sessions(user: dict) -> bool:
    return is_administrator(user)

ROLE_PERMISSIONS = {
    ROLE_AUX: {
        PERMISSION_EDIT_PENDING,
        PERMISSION_VIEW_ADMISSION_QUEUE,
    },
    ROLE_AUDIT: {
        PERMISSION_EDIT_PENDING,
        PERMISSION_DELETE_PENDING,
        PERMISSION_VALIDATE_RECEIPT,
        PERMISSION_MARK_NOT_INVOICED,
        PERMISSION_VIEW_BILLING_AUDIT,
        PERMISSION_MANAGE_BILLING_LISTS,
    },
    ROLE_MEDICAL_AUDIT: {
        PERMISSION_EDIT_PENDING,
        PERMISSION_VALIDATE_RECEIPT,
        PERMISSION_MARK_NOT_INVOICED,
        PERMISSION_REOPEN_RECEIPT,
        PERMISSION_VIEW_BILLING_AUDIT,
        PERMISSION_VIEW_ADMISSION_QUEUE,
        PERMISSION_VIEW_ADMISSION_RECONCILIATION,
    },
    ROLE_ADMIN: {
        PERMISSION_EDIT_PENDING,
        PERMISSION_VALIDATE_RECEIPT,
        PERMISSION_MARK_NOT_INVOICED,
        PERMISSION_REOPEN_RECEIPT,
        PERMISSION_VIEW_BILLING_AUDIT,
        PERMISSION_DELETE_PENDING,
        PERMISSION_MANAGE_TRASH,
        PERMISSION_MANAGE_BILLING_LISTS,
        PERMISSION_VIEW_ADMISSION_QUEUE,
        PERMISSION_VIEW_ADMISSION_RECONCILIATION,
    },
}


def user_has_permission(user: dict, permission: str) -> bool:
    role = normalize_role((user or {}).get("role"))
    return permission in ROLE_PERMISSIONS.get(role, set())


def main_module_labels_for_user(user: dict) -> tuple[str, ...]:
    """Devuelve la navegación principal en el orden operativo esperado."""
    labels = []
    if user_has_permission(user, PERMISSION_VIEW_ADMISSION_QUEUE):
        labels.append("Emergencias")
    labels.append("Facturación")
    if user_has_permission(user, PERMISSION_MANAGE_BILLING_LISTS):
        labels.append("Listados de ARS")
    return tuple(labels)


def user_can_delete_receipts(user: dict) -> bool:
    return user_has_permission(user, PERMISSION_DELETE_PENDING)

def wrap_text(text: str, width: int = 76):
    if not text: return [""]
    words = text.split(); lines, line = [], ""
    for w in words:
        if len(w) > width:
            if line: lines.append(line); line = ""
            for i in range(0, len(w), width):
                seg = w[i:i + width]
                if len(seg) == width: lines.append(seg)
                else: line = seg
            continue
        if not line: line = w
        elif len(line) + 1 + len(w) <= width: line += " " + w
        else: lines.append(line); line = w
    if line: lines.append(line)
    return lines

