_receipt_render_lock = threading.RLock()


def _receipt_snapshot_render_data(document_record):
    snapshot = dict(document_record.get("snapshot") or {})
    header = dict(snapshot.get("header") or {})
    patient = dict(snapshot.get("patient") or {})
    totals = dict(snapshot.get("totals") or {})
    document = dict(snapshot.get("document") or {})
    categories = {}
    category_order = []
    for item in list(snapshot.get("items") or []):
        category = str(item.get("category") or "Otros")
        if category not in categories:
            category_order.append(category)
            categories[category] = []
        categories[category].append(
            {
                "descripcion": str(item.get("name") or ""),
                "cantidad": int(item.get("quantity") or 0),
                "precio": float(item.get("unit_price") or 0),
                "total": float(item.get("subtotal") or 0),
            }
        )
    category_totals = dict(totals.get("by_category") or {})
    rendered_categories = [
        {
            "nombre": category,
            "subtotal": float(category_totals.get(category) or 0),
            "items": categories[category],
        }
        for category in category_order
    ]
    total = float(totals.get("general") or 0)
    try:
        total_words = number_to_text(int(total)).replace("SON:", "").strip()
    except Exception:
        total_words = ""
    return {
        "hospital_line_1": document.get("hospital_line_1"),
        "hospital_line_2": document.get("hospital_line_2"),
        "document_title": document.get("document_title"),
        "numero": header.get("receipt_number"),
        "fecha": header.get("service_date"),
        "paciente": patient.get("name"),
        "diagnostico": header.get("diagnosis"),
        "ars": header.get("ars") or (
            "NO ASEGURADO"
            if str(header.get("coverage") or "").upper() == "NO_ASEGURADO"
            else "N/A"
        ),
        "sala": float(header.get("room_charge") or 0),
        "categorias": rendered_categories,
        "total_general": total,
        "total_letras": total_words,
        "usuario": document.get("visible_user"),
        "generado": header.get("generated_at"),
        "numero_autorizacion": header.get("authorization_number"),
        "estado_documento": header.get("document_state"),
        "logo_path": LOGO_PATH,
    }


def _receipt_snapshot_cache_path(document_record):
    receipt_number = int(document_record["receipt_number"])
    version = int(document_record["version"])
    short_hash = str(document_record["snapshot_hash"])[:12]
    template_tag = re.sub(
        r"[^A-Za-z0-9_-]+",
        "_",
        str(document_record.get("template_version") or "unknown"),
    ).strip("_")
    cache_dir = Path(tempfile.gettempdir()) / "HospitalFacturacion" / "receipt_cache"
    cache_dir.mkdir(parents=True, exist_ok=True)
    return cache_dir / (
        f"recibo_{receipt_number}_v{version}_{short_hash}"
        f"_t{template_tag}.pdf"
    )


def render_receipt_snapshot_pdf(document_record, renderer=None):
    output_path = _receipt_snapshot_cache_path(document_record)
    with _receipt_render_lock:
        if output_path.exists() and output_path.stat().st_size > 0:
            return str(output_path)
        temporary_path = output_path.with_name(
            f".{output_path.stem}_{time.time_ns()}.tmp.pdf"
        )
        owns_renderer = renderer is None
        active_renderer = renderer
        try:
            if active_renderer is None:
                from pdf_engine import ReceiptPDFRenderer
                active_renderer = ReceiptPDFRenderer(persistent=False)
            active_renderer.render_pdf(
                _receipt_snapshot_render_data(document_record),
                str(temporary_path),
                save_html_preview=False,
            )
            if not temporary_path.exists() or temporary_path.stat().st_size <= 0:
                raise ReceiptDocumentError(
                    "El motor documental no generó un PDF válido."
                )
            os.replace(str(temporary_path), str(output_path))
            return str(output_path)
        finally:
            if temporary_path.exists():
                try:
                    temporary_path.unlink()
                except OSError:
                    pass
            if owns_renderer and active_renderer is not None:
                try:
                    active_renderer.close()
                except Exception:
                    pass


def _stored_pdf_blob_path(
    con,
    *,
    filename: str,
    namespace: str,
    identity: str,
    receipt_id: int | None = None,
):
    filename = os.path.basename(str(filename or ""))
    if receipt_id is not None:
        row = con.execute(
            """SELECT file_data
               FROM pdf_storage
               WHERE owner_receipt_id=%s OR filename=%s
               ORDER BY CASE WHEN owner_receipt_id=%s THEN 0 ELSE 1 END
               LIMIT 1""",
            (int(receipt_id), filename, int(receipt_id)),
        ).fetchone()
    elif filename:
        row = con.execute(
            "SELECT file_data FROM pdf_storage WHERE filename=%s LIMIT 1",
            (filename,),
        ).fetchone()
    else:
        row = None
    if not row or row["file_data"] is None:
        raise FileNotFoundError("No existe un binario PDF histórico almacenado.")
    cache = Path(tempfile.gettempdir()) / "HospitalFacturacion" / "legacy_documents"
    return materialize_pdf_blob(
        row["file_data"], cache, namespace=namespace, identity=identity
    )


def _legacy_receipt_pdf_path(receipt: NormalizedReceiptRecord):
    filename = receipt.pdf_filename
    if filename:
        local_path = stable_storage_path(PDFS_DIR, filename)
        if os.path.isfile(local_path) and os.path.getsize(local_path) > 0:
            return local_path
    direct = (
        Path(receipt.legacy_backup_reference)
        if receipt.legacy_backup_reference else None
    )
    if direct and direct.is_file() and direct.stat().st_size > 0:
        return str(direct)
    if not filename:
        raise ReceiptDocumentError("El recibo histórico no tiene un PDF asociado.")
    with db_connect() as con:
        try:
            return str(
                find_external_document(
                    con,
                    filename=filename,
                    source_table="recibos",
                    source_key_value=str(receipt.receipt_id),
                    archive_root=default_archive_root(),
                )
            )
        except ReportDocumentError as exc:
            raise ReceiptDocumentError(str(exc)) from exc


def _structured_receipt_document(con, receipt: NormalizedReceiptRecord):
    snapshot = build_receipt_snapshot(con, receipt.receipt_id)
    header = dict(snapshot.get("header") or {})
    patient = dict(snapshot.get("patient") or {})
    totals = dict(snapshot.get("totals") or {})
    if (
        not str(patient.get("name") or "").strip()
        or not str(header.get("service_date") or "").strip()
        or receipt.receipt_number is None
        or "general" not in totals
    ):
        raise ReceiptDocumentError(
            "Los metadatos estructurados del recibo están incompletos."
        )
    return {
        "receipt_id": receipt.receipt_id,
        "receipt_number": receipt.receipt_number,
        "version": 0,
        "snapshot": snapshot,
        "snapshot_hash": calculate_snapshot_hash(snapshot),
        "template_version": RECEIPT_TEMPLATE_VERSION,
        "schema_version": int(snapshot.get("schema_version") or 1),
        "storage_mode": receipt.storage_mode or STORAGE_LEGACY,
        "pdf_filename": receipt.pdf_filename,
    }


def resolve_receipt_document(receipt_id, action="open", renderer=None):
    """Resolve every receipt action through one backwards-compatible path."""
    attempts = []
    with db_connect() as con:
        raw = con.execute(
            """SELECT id,numero,nombre,fecha,created_at,username,ars,
                      numero_autorizacion,estado_facturacion,
                      admission_atencion_id,document_storage_mode,pdf_filename,
                      legacy_pdf_backup_reference
               FROM recibos WHERE id=%s""",
            (int(receipt_id),),
        ).fetchone()
        if not raw:
            raise ReceiptDocumentError("El recibo no existe.")
        receipt = normalize_receipt_record(raw)
        for loader, origin in (
            (load_current_receipt_snapshot, "snapshot_actual"),
            (load_latest_receipt_snapshot, "snapshot_historico"),
        ):
            try:
                document = loader(con, receipt.receipt_id)
                path = render_receipt_snapshot_pdf(document, renderer=renderer)
                write_runtime_log(
                    f"Recibo documento accion={action} id={receipt.receipt_id} origen={origin}"
                )
                return path
            except SnapshotHashError as exc:
                # An integrity failure is not equivalent to an absent legacy
                # representation and must never be hidden by a fallback.
                if receipt.storage_mode != STORAGE_HYBRID:
                    raise
                attempts.append((origin, type(exc).__name__))
            except Exception as exc:
                attempts.append((origin, type(exc).__name__))

    try:
        path = _legacy_receipt_pdf_path(receipt)
        write_runtime_log(
            f"Recibo documento accion={action} id={receipt.receipt_id} origen=pdf_legado"
        )
        return path
    except Exception as exc:
        attempts.append(("pdf_legado", type(exc).__name__))
    try:
        with db_connect() as con:
            path = _stored_pdf_blob_path(
                con,
                filename=receipt.pdf_filename,
                namespace="receipt",
                identity=str(receipt.receipt_id),
                receipt_id=receipt.receipt_id,
            )
        write_runtime_log(
            f"Recibo documento accion={action} id={receipt.receipt_id} origen=blob_legado"
        )
        return path
    except Exception as exc:
        attempts.append(("blob_legado", type(exc).__name__))
    try:
        with db_connect() as con:
            document = _structured_receipt_document(con, receipt)
        path = render_receipt_snapshot_pdf(document, renderer=renderer)
        write_runtime_log(
            f"Recibo documento accion={action} id={receipt.receipt_id} origen=estructura_historica"
        )
        return path
    except Exception as exc:
        attempts.append(("estructura_historica", type(exc).__name__))
    write_runtime_log(
        "Recibo histórico no resoluble "
        f"id={receipt.receipt_id} intentos="
        + ",".join(f"{origin}:{error}" for origin, error in attempts)
    )
    raise ReceiptDocumentError(
        "Este recibo histórico no contiene información documental suficiente "
        "para reconstruir el documento."
    )


def resolve_receipt_document_path(receipt_id, renderer=None):
    """Compatibility alias retained for existing callers."""
    return resolve_receipt_document(receipt_id, "open", renderer=renderer)


def export_receipt_document(receipt_id, destination):
    source = resolve_receipt_document(int(receipt_id), "save_copy")
    destination_path = os.path.abspath(str(destination))
    os.makedirs(os.path.dirname(destination_path), exist_ok=True)
    shutil.copyfile(source, destination_path)
    return destination_path


def audit_historical_receipt_documents(sample_limit=20):
    with db_connect() as con:
        return audit_historical_receipts(con, sample_limit=sample_limit)


def save_report_pdf_binary(filename, pdf_path):
    """Compatibilidad defensiva: los reportes ya no admiten binarios PostgreSQL."""
    raise ReportDocumentError(
        "El almacenamiento binario de reportes está deshabilitado; "
        "guarde una instantánea documental."
    )


def _report_source_row(con, source_table, source_key_value):
    if source_table == "report_history":
        row = con.execute(
            """SELECT id,filepath AS filename,document_storage_mode,
                      id::text AS source_key,report_type,start_date,end_date,
                      generated_at,generated_by,totals_json
               FROM report_history WHERE id=%s""",
            (int(source_key_value),),
        ).fetchone()
    elif source_table == "daily_reports":
        row = con.execute(
            """SELECT id,filepath AS filename,document_storage_mode,
                      id::text AS source_key,'Diario' AS report_type,
                      report_date AS start_date,report_date AS end_date,
                      generated_at,generated_by,totals_json
               FROM daily_reports WHERE id=%s""",
            (int(source_key_value),),
        ).fetchone()
    elif source_table == "billing_shift_closures":
        try:
            instance_id, turn_id = parse_shift_closure_source_key(
                source_key_value
            )
            rows = con.execute(
                """SELECT turn_id AS id,report_filename AS filename,
                          document_storage_mode,source_instance_id,
                          source_instance_id || '|' || turn_id::text AS source_key,
                      'Cierre automático del turno de ' ||
                      COALESCE(NULLIF(representative,''),NULLIF(closed_by,''),
                               NULLIF(claimed_by,''),'Usuario no identificado') AS report_type,
                          operational_date AS start_date,operational_date AS end_date,
                          generated_at,
                          COALESCE(NULLIF(representative,''),claimed_by) AS generated_by,
                          totals_json
                   FROM billing_shift_closures
                   WHERE source_instance_id=%s AND turn_id=%s""",
                (instance_id, int(turn_id)),
            ).fetchall()
        except ValueError:
            try:
                legacy_turn_id = int(source_key_value)
            except (TypeError, ValueError) as exc:
                raise ReportDocumentError(
                    "La referencia histórica del cierre de turno es inválida."
                ) from exc
            rows = con.execute(
                """SELECT turn_id AS id,report_filename AS filename,
                          document_storage_mode,source_instance_id,
                          source_instance_id || '|' || turn_id::text AS source_key,
                          'Cierre automático del turno de ' ||
                          COALESCE(NULLIF(representative,''),NULLIF(closed_by,''),
                                   NULLIF(claimed_by,''),'Usuario no identificado') AS report_type,
                          operational_date AS start_date,operational_date AS end_date,
                          generated_at,
                          COALESCE(NULLIF(representative,''),claimed_by) AS generated_by,
                          totals_json
                   FROM billing_shift_closures
                   WHERE turn_id=%s ORDER BY generated_at DESC LIMIT 2""",
                (legacy_turn_id,),
            ).fetchall()
        if len(rows) > 1:
            raise ReportDocumentError(
                "La referencia histórica del cierre de turno es ambigua; "
                "actualiza el historial y vuelve a seleccionarlo."
            )
        row = rows[0] if rows else None
    else:
        raise ReportDocumentError("Tipo de reporte no permitido.")
    if not row:
        raise ReportDocumentError("El reporte seleccionado ya no existe.")
    return dict(row)


def _legacy_report_payload(report: NormalizedReportRecord):
    raw = report.metadata.get("totals_json")
    if isinstance(raw, str):
        try:
            raw = json.loads(raw or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            raw = {}
    payload = dict(raw) if isinstance(raw, dict) else {}
    meaningful = any(value not in (None, "", [], {}) for value in payload.values())
    if not meaningful:
        raise ReportDocumentError(
            "El reporte no conserva un resumen histórico estructurado."
        )
    return payload


def _flatten_historical_report(value, prefix=""):
    rows = []
    if isinstance(value, dict):
        for key in sorted(value, key=lambda item: str(item)):
            label = f"{prefix} / {key}" if prefix else str(key)
            rows.extend(_flatten_historical_report(value[key], label))
    elif isinstance(value, list):
        for index, item in enumerate(value, start=1):
            label = f"{prefix} #{index}" if prefix else f"Registro #{index}"
            rows.extend(_flatten_historical_report(item, label))
    else:
        rows.append((prefix or "Valor", "—" if value is None else str(value)))
    return rows


def _render_legacy_report_metadata(report: NormalizedReportRecord):
    """Render only values persisted with the historical report record."""
    payload = _legacy_report_payload(report)
    canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str)
    digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()[:16]
    target = report_cache_root() / (
        f"legacy_{re.sub(r'[^A-Za-z0-9_.-]+', '_', report.source_table)}_"
        f"{re.sub(r'[^A-Za-z0-9_.-]+', '_', report.source_key)}_{digest}.pdf"
    )
    if target.is_file() and target.stat().st_size > 0:
        return str(target)
    temporary = target.with_suffix(".tmp")
    pdf = rl_canvas.Canvas(str(temporary), pagesize=letter)
    width, height = letter
    left = 0.65 * inch
    top = height - 0.55 * inch

    def text(value):
        return str(value or "").encode("latin-1", "replace").decode("latin-1")

    def new_page():
        pdf.showPage()
        pdf.setFont("Helvetica", 8)
        return top

    y = top
    logo = str(LOGO_PATH or "")
    if logo and os.path.isfile(logo):
        try:
            pdf.drawImage(
                logo, left, y - 0.45 * inch,
                width=1.45 * inch, height=0.45 * inch,
                preserveAspectRatio=True, anchor="w", mask="auto",
            )
        except Exception:
            pass
    pdf.setFont("Helvetica-Bold", 13)
    pdf.drawString(left + 1.6 * inch, y - 0.08 * inch, text(report.report_type or "Reporte histórico"))
    y -= 0.62 * inch
    pdf.setFont("Helvetica-Bold", 8)
    pdf.drawString(left, y, "RECONSTRUCCION HISTORICA DESDE DATOS ALMACENADOS")
    y -= 0.22 * inch
    pdf.setFont("Helvetica", 8)
    metadata_rows = (
        ("Período", f"{report.date_from or '—'} a {report.date_to or report.date_from or '—'}"),
        ("Generado", report.generated_at or "—"),
        ("Usuario", report.generated_by or "—"),
        ("Fuente", report.source_table),
    )
    for label, value in metadata_rows:
        pdf.setFont("Helvetica-Bold", 8)
        pdf.drawString(left, y, text(label + ":"))
        pdf.setFont("Helvetica", 8)
        pdf.drawString(left + 1.15 * inch, y, text(value)[:125])
        y -= 0.18 * inch
    y -= 0.08 * inch
    for label, value in _flatten_historical_report(payload):
        chunks = [str(value)[start:start + 105] for start in range(0, max(1, len(str(value))), 105)] or [""]
        if y < 0.55 * inch:
            y = new_page()
        pdf.setFont("Helvetica-Bold", 7.5)
        pdf.drawString(left, y, text(label)[:62])
        pdf.setFont("Helvetica", 7.5)
        pdf.drawString(left + 2.65 * inch, y, text(chunks[0]))
        y -= 0.16 * inch
        for chunk in chunks[1:]:
            if y < 0.55 * inch:
                y = new_page()
            pdf.drawString(left + 2.65 * inch, y, text(chunk))
            y -= 0.16 * inch
    pdf.save()
    if not temporary.is_file() or temporary.stat().st_size <= 4:
        raise ReportDocumentError(
            "No fue posible reconstruir el resumen histórico del reporte."
        )
    os.replace(str(temporary), str(target))
    return str(target)


def _find_cached_report_snapshot_pdf(source_table, source_key_value):
    """Return the newest complete local render for an offline history open."""
    safe_source = re.sub(
        r"[^A-Za-z0-9_.-]+", "_", f"{source_table}_{source_key_value}"
    )[:120]
    candidates = sorted(
        report_cache_root().glob(f"{safe_source}_v*_*.pdf"),
        key=lambda item: item.stat().st_mtime,
        reverse=True,
    )
    for candidate in candidates:
        try:
            if candidate.is_file() and candidate.stat().st_size > 0:
                return str(candidate)
        except OSError:
            continue
    return ""


def _resolve_report_document_online(
    source_table, source_key_value, action="open", filename_hint="", *, logo_path=None
):
    """Resolve all report actions through a stable historical contract."""
    attempts = []
    with db_connect() as con:
        source = _report_source_row(con, source_table, source_key_value)
        source.update(
            {
                "source_table": source_table,
                "source_key": source.get("source_key") or source_key_value,
                "pdf_filename": source.get("filename") or filename_hint,
            }
        )
        report = normalize_report_record(source)
        snapshot_error = None
        for loader, origin in (
            (load_current_report_snapshot, "snapshot_actual"),
            (load_latest_report_snapshot, "snapshot_historico"),
        ):
            try:
                document = loader(
                    con, report.source_table, report.source_key
                )
                path = render_report_snapshot_pdf(
                    document, logo_path=logo_path or LOGO_PATH or ""
                )
                write_runtime_log(
                    f"Reporte documento accion={action} fuente={report.source_table} "
                    f"clave={report.source_key} origen={origin}"
                )
                return path
            except ReportSnapshotHashError as exc:
                if report.storage_mode != REPORT_STORAGE_HYBRID:
                    raise
                snapshot_error = exc
                attempts.append((origin, type(exc).__name__))
            except Exception as exc:
                snapshot_error = exc
                attempts.append((origin, type(exc).__name__))
        if report.storage_mode == REPORT_STORAGE_SNAPSHOT:
            if isinstance(snapshot_error, ReportSnapshotMissingError):
                raise ReportSnapshotMissingError(
                    "Los datos históricos de este reporte no están disponibles."
                ) from snapshot_error
            if isinstance(snapshot_error, ReportSnapshotHashError):
                raise snapshot_error
            raise ReportDocumentError(
                "No fue posible preparar el snapshot histórico del reporte."
            ) from snapshot_error
        if report.pdf_filename:
            try:
                path = str(
                    find_external_document(
                        con,
                        filename=report.pdf_filename,
                        source_table=report.source_table,
                        source_key_value=report.source_key,
                        archive_root=default_archive_root(),
                    )
                )
                write_runtime_log(
                    f"Reporte documento accion={action} fuente={report.source_table} "
                    f"clave={report.source_key} origen=pdf_legado"
                )
                return path
            except Exception as exc:
                attempts.append(("pdf_legado", type(exc).__name__))
            for candidate in (
                stable_storage_path(REPORTS_DIR, report.pdf_filename),
                str(report_cache_root() / report.pdf_filename),
            ):
                if (
                    candidate and os.path.isfile(candidate)
                    and os.path.getsize(candidate) > 0
                ):
                    write_runtime_log(
                        f"Reporte documento accion={action} fuente={report.source_table} "
                        f"clave={report.source_key} origen=pdf_local"
                    )
                    return candidate
        try:
            path = _stored_pdf_blob_path(
                con,
                filename=report.pdf_filename,
                namespace="report",
                identity=f"{report.source_table}_{report.source_key}",
            )
            write_runtime_log(
                f"Reporte documento accion={action} fuente={report.source_table} "
                f"clave={report.source_key} origen=blob_legado"
            )
            return path
        except Exception as exc:
            attempts.append(("blob_legado", type(exc).__name__))
        try:
            path = _render_legacy_report_metadata(report)
            write_runtime_log(
                f"Reporte documento accion={action} fuente={report.source_table} "
                f"clave={report.source_key} origen=estructura_historica"
            )
            return path
        except Exception as exc:
            attempts.append(("estructura_historica", type(exc).__name__))
    write_runtime_log(
        "Reporte histórico no resoluble "
        f"fuente={report.source_table} clave={report.source_key} intentos="
        + ",".join(f"{origin}:{error}" for origin, error in attempts)
    )
    raise ReportDocumentError(
        "Este reporte histórico no contiene información suficiente para "
        "reconstruir el documento. Puede generar un nuevo reporte utilizando "
        "el mismo período."
    )


def resolve_report_document(
    source_table, source_key_value, action="open", filename_hint="", *, logo_path=None
):
    """Resolve online snapshots, with a local cache fallback for offline opening."""
    try:
        return _resolve_report_document_online(
            source_table,
            source_key_value,
            action,
            filename_hint,
            logo_path=logo_path,
        )
    except ReportDocumentError:
        raise
    except Exception as exc:
        cached_path = (
            _find_cached_report_snapshot_pdf(source_table, source_key_value)
            if action == "open"
            else ""
        )
        if cached_path:
            write_runtime_log(
                "Reporte documento accion=open "
                f"fuente={source_table} clave={source_key_value} origen=cache_offline"
            )
            return cached_path
        raise ReportDocumentError(
            "No hay conexión para obtener los datos históricos del reporte. "
            "Conecte la aplicación e inténtelo nuevamente."
        ) from exc


def resolve_report_document_path(
    source_table, source_key_value, filename_hint="", *, logo_path=None
):
    """Compatibility alias retained for existing report callers."""
    return resolve_report_document(
        source_table,
        source_key_value,
        "open",
        filename_hint,
        logo_path=logo_path,
    )


class ReportDocumentOpenWorker(QThread):
    """Render one historical report outside the GUI thread."""

    ready = Signal(str)
    failed = Signal(str)

    def __init__(
        self, source_table: str, source_key_value: str, filename_hint: str = "", parent=None
    ):
        super().__init__(parent)
        self.source_table = str(source_table or "")
        self.source_key_value = str(source_key_value or "")
        self.filename_hint = str(filename_hint or "")

    def run(self):
        try:
            self.ready.emit(
                resolve_report_document(
                    self.source_table,
                    self.source_key_value,
                    "open",
                    self.filename_hint,
                )
            )
        except Exception as exc:
            self.failed.emit(str(exc))


class ReportDocumentExportWorker(QThread):
    """Materialize historical Excel output away from the GUI thread."""

    ready = Signal(str)
    failed = Signal(str)

    def __init__(
        self,
        source_table: str,
        source_key_value: str,
        destination: str,
        logo_path: str = "",
        parent=None,
    ):
        super().__init__(parent)
        self.source_table = str(source_table or "")
        self.source_key_value = str(source_key_value or "")
        self.destination = str(destination or "")
        self.logo_path = str(logo_path or "")

    def run(self):
        try:
            with db_connect() as con:
                try:
                    document = load_current_report_snapshot(
                        con, self.source_table, self.source_key_value
                    )
                except ReportSnapshotMissingError:
                    document = load_latest_report_snapshot(
                        con, self.source_table, self.source_key_value
                    )
            self.ready.emit(
                export_report_snapshot_xlsx(
                    document, self.destination, self.logo_path
                )
            )
        except Exception as exc:
            self.failed.emit(str(exc))


