class PDFStorageSyncWorker(QThread):
    """Compatibilidad: la sincronización binaria fue retirada."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.jobs = queue.Queue()
        self._running = True

    @Slot(int, str, str)
    def enqueue(self, recibo_id, filename, pdf_path):
        return

    def stop(self):
        self._running = False
        self.jobs.put(None)

    def _load_pending(self):
        return

    def run(self):
        return


class PDFWorkerSignals(QObject):
    finished_signal = Signal(bool, str, str, int)
    sync_requested = Signal(int, str, str)


class PDFDatabaseWorker(threading.Thread):
    def __init__(self):
        super().__init__(name="PDFEngineThread", daemon=True)
        self.signals = PDFWorkerSignals()
        self.jobs = queue.Queue()
        self._running = True
        self.renderer = None

    def warm_up(self):
        started = perf_counter()
        try:
            from pdf_engine import ReceiptPDFRenderer

            self.renderer = ReceiptPDFRenderer(persistent=True)
            self.renderer.start()
            write_pdf_performance(
                f"Motor PDF precargado en {perf_counter() - started:.3f}s"
            )
        except Exception as exc:
            self.renderer = None
            write_runtime_log(f"No se pudo precargar Chromium: {exc}")

    def submit(self, job):
        self.jobs.put(dict(job))

    def stop(self):
        self._running = False
        self.jobs.put(None)

    def run(self):
        self.warm_up()
        try:
            while self._running:
                job = self.jobs.get()
                if job is None:
                    break
                self.process(job)
        finally:
            if self.renderer is not None:
                self.renderer.close()
                self.renderer = None

    def _legacy_process_disabled(self, job):
        self.patient = job["patient"]
        self.date_str = job["date_str"]
        self.dx_raw = job["dx_raw"]
        self.ars_name = job["ars_name"]
        self.coverage = job.get("coverage", "ASEGURADO")
        self.sala = job["sala"]
        self.grouped = job["grouped"]
        self.total_general = job["total_general"]
        self.editing_id = job["editing_id"]
        self.editing_num = job["editing_num"]
        self.current_user = job["current_user"]
        self.is_backdated = job["is_backdated"]
        self.authorization_number = str(job.get("authorization_number") or "").strip()
        self.admission_attention = job.get("admission_attention")
        self.admission_session_id = str(job.get("admission_session_id") or "")
        total_started = perf_counter()
        number_elapsed = 0.0
        prepare_started = perf_counter()
        try:
            generated_at = now_str()
            if self.editing_id is not None:
                try:
                    with db_connect() as con:
                        cur = con.execute("SELECT created_at FROM recibos WHERE id=%s", (self.editing_id,))
                        row = cur.fetchone()
                        if row and row["created_at"]:
                            generated_at = row["created_at"]
                except Exception:
                    pass

            number_started = perf_counter()
            if self.editing_id is not None: recibo_number = self.editing_num
            else: recibo_number = get_next_recibo_number()
            number_elapsed = perf_counter() - number_started

            database_started = perf_counter()
            recibo_id = save_receipt_with_items(
                self.editing_id,
                recibo_number,
                self.patient,
                self.date_str,
                self.dx_raw,
                self.ars_name,
                self.sala,
                self.total_general,
                "",
                self.current_user["username"],
                self.is_backdated,
                generated_at,
                self.grouped,
                self.coverage,
                self.authorization_number,
                self.admission_attention,
                self.admission_session_id,
                {
                    "visible_user": self.current_user.get(
                        "full_name", self.current_user["username"]
                    )
                },
            )
            database_elapsed = perf_counter() - database_started
            try:
                render_started = perf_counter()
                pdf_path = resolve_receipt_document_path(
                    recibo_id, renderer=self.renderer
                )
                render_elapsed = perf_counter() - render_started
            except Exception as render_error:
                write_runtime_log(
                    "Recibo guardado; fallo de reconstrucción temporal "
                    f"| recibo_id={recibo_id} | error={type(render_error).__name__}: "
                    f"{str(render_error)[:300]}"
                )
                self.signals.finished_signal.emit(
                    True,
                    "__RECEIPT_SAVED_RENDER_ERROR__:" + str(render_error),
                    "",
                    recibo_number,
                )
                return
            write_pdf_performance(
                f"Recibo {recibo_number} SNAPSHOT | número={number_elapsed:.3f}s "
                f"| base_datos={database_elapsed:.3f}s "
                f"| reconstrucción={render_elapsed:.3f}s"
            )
            self.signals.finished_signal.emit(
                True, "Éxito", pdf_path, recibo_number
            )
            return
            
            pdf_filename = f"recibo_{recibo_number}.pdf"
            pdf_path = os.path.join(PDFS_DIR, pdf_filename)
            temp_pdf_path = os.path.join(
                PDFS_DIR, f".recibo_{recibo_number}_{time.time_ns()}.tmp.pdf"
            )
            
            # =========================================================
            # NUEVO MOTOR PDF HTML/CSS (Jinja2 + Playwright/Chromium)
            # =========================================================
            # Este bloque intenta generar el recibo moderno usando renderer.py.
            # Si algo falla, usa automáticamente el generador ReportLab anterior
            # para no romper el flujo de facturación.

            icon_map_pdf_html = {
                "Medicamentos": "💊",
                "Materiales": "🧤",
                "Laboratorios": "🧪",
                "Imágenes": "📷",
                "Procedimientos": "🩺",
                "Honorarios": "👨‍⚕️",
            }

            color_map_pdf_html = {
                "Medicamentos": "#1A56DB",
                "Materiales": "#059669",
                "Laboratorios": "#7C3AED",
                "Imágenes": "#EA580C",
                "Procedimientos": "#2563EB",
                "Honorarios": "#1D4ED8",
            }

            categorias_pdf_html = []
            for label, lst in self.grouped:
                subtotal_cat = sum(float(total_item or 0) for _name, _pu, _qty, total_item, _ars in lst)
                items_cat = []
                for name, pu, qty, total_item, _ars in lst:
                    items_cat.append({
                        "descripcion": safe_pdf_text(name),
                        "cantidad": int(qty),
                        "precio": float(pu or 0),
                        "total": float(total_item or 0),
                    })

                categorias_pdf_html.append({
                    "nombre": label,
                    "icon": icon_map_pdf_html.get(label, "📄"),
                    "color": color_map_pdf_html.get(label, "#0F3D91"),
                    "subtotal": subtotal_cat,
                    "items": items_cat,
                })

            total_letras_pdf_html = ""
            try:
                total_letras_pdf_html = number_to_text(int(float(self.total_general))).replace("SON:", "").strip()
            except Exception:
                total_letras_pdf_html = ""

            generado_pdf_html = datetime.now().strftime("%d/%m/%Y %H:%M")
            try:
                if generated_at:
                    generado_pdf_html = datetime.strptime(str(generated_at), "%Y-%m-%d %H:%M:%S").strftime("%d/%m/%Y %H:%M")
            except Exception:
                pass

            try:
                recibo_data_pdf_html = {
                    "numero": recibo_number,
                    "fecha": self.date_str,
                    "paciente": self.patient,
                    "diagnostico": self.dx_raw or "N/A",
                    "ars": self.ars_name or ("NO ASEGURADO" if self.coverage == "NO_ASEGURADO" else "N/A"),
                    "sala": float(self.sala or 0),
                    "categorias": categorias_pdf_html,
                    "total_general": float(self.total_general or 0),
                    "total_letras": total_letras_pdf_html,
                    "usuario": self.current_user.get("full_name", "N/A"),
                    "generado": generado_pdf_html,
                    "logo_path": LOGO_PATH,
                    "numero_autorizacion": self.authorization_number,
                    "estado_documento": (
                        DOCUMENT_READY
                        if self.coverage == "NO_ASEGURADO" or self.authorization_number
                        else DOCUMENT_PRELIMINARY
                    ),
                }
                prepare_elapsed = perf_counter() - prepare_started

                # El motor se importa como paquete para que también funcione
                # dentro del ejecutable generado por PyInstaller.
                if self.renderer is None:
                    from pdf_engine import ReceiptPDFRenderer
                    self.renderer = ReceiptPDFRenderer(persistent=True)

                render_started = perf_counter()
                self.renderer.render_pdf(
                    recibo_data_pdf_html,
                    temp_pdf_path,
                    save_html_preview=False,
                )
                render_elapsed = perf_counter() - render_started

                if not os.path.exists(temp_pdf_path) or os.path.getsize(temp_pdf_path) <= 0:
                    raise RuntimeError("El motor HTML/CSS no creó el archivo PDF.")

            except Exception as render_error:
                render_elapsed = perf_counter() - render_started if 'render_started' in locals() else 0.0
                if self.renderer is not None:
                    try:
                        self.renderer.close()
                    except Exception:
                        pass
                    self.renderer = None
                # Fallback seguro: generador ReportLab anterior.
                print(f"Error usando motor HTML/CSS. Se usará ReportLab: {render_error}")
                write_runtime_log(
                    f"Motor PDF HTML/CSS no disponible para recibo {recibo_number}; "
                    f"se usó ReportLab. Detalle: {render_error}"
                )

                c = rl_canvas.Canvas(temp_pdf_path, pagesize=letter)
                page_w, page_h = letter
                bottom_margin = 0.6 * inch
                y = page_h - 0.5 * inch
                current_user_local = self.current_user

                def ensure_space(h=0.25*inch):
                    nonlocal y
                    if y - h < bottom_margin:
                        c.showPage()
                        y = page_h - 0.5 * inch

                y = draw_header(c, page_w, page_h, recibo_number, self.date_str)
                y = draw_patient_info(c, page_w, y, self.patient, self.dx_raw, self.ars_name, self.sala)

                subtotales = {label: sum(sub for _, _, _, sub, _ in lst) for label, lst in self.grouped}

                for label, lst in self.grouped:
                    y = draw_section_table(c, page_w, page_h, y, label, lst, bottom_margin, current_user_local)
                    ensure_space(0.2*inch)

                y = draw_summary_and_total(c, page_w, page_h, y, subtotales, self.total_general, bottom_margin, self.sala)
                draw_footer(c, page_w, current_user_local)
                c.save()
                render_elapsed = perf_counter() - render_started if 'render_started' in locals() else 0.0

            database_started = perf_counter()
            recibo_id = save_receipt_with_items(
                self.editing_id,
                recibo_number,
                self.patient,
                self.date_str,
                self.dx_raw,
                self.ars_name,
                self.sala,
                self.total_general,
                pdf_filename,
                self.current_user['username'],
                self.is_backdated,
                generated_at,
                self.grouped,
                self.coverage,
                self.authorization_number,
                self.admission_attention,
                self.admission_session_id,
            )
            database_elapsed = perf_counter() - database_started
            # Publicar el PDF solo después de que la transacción confirme que el recibo
            # continúa editable. Así una validación concurrente no deja un archivo alterado.
            os.replace(temp_pdf_path, pdf_path)
            visible_elapsed = perf_counter() - total_started
            write_pdf_performance(
                f"Recibo {recibo_number} | número={number_elapsed:.3f}s "
                f"| preparación={prepare_elapsed:.3f}s | render={render_elapsed:.3f}s "
                f"| base_datos={database_elapsed:.3f}s | visible={visible_elapsed:.3f}s"
            )
            self.signals.finished_signal.emit(True, "Éxito", pdf_path, recibo_number)
            self.signals.sync_requested.emit(recibo_id, pdf_filename, pdf_path)

        except AdmissionAttentionUnavailableError as e:
            try:
                if "temp_pdf_path" in locals() and os.path.exists(temp_pdf_path):
                    os.remove(temp_pdf_path)
            except OSError:
                pass
            self.signals.finished_signal.emit(
                False, "__ADMISSION_UNAVAILABLE__:" + str(e), "", 0
            )
        except DuplicateReceiptError as e:
            try:
                if "temp_pdf_path" in locals() and os.path.exists(temp_pdf_path):
                    os.remove(temp_pdf_path)
            except OSError:
                pass
            payload = {
                "message": str(e),
                "receipt": e.receipt,
            }
            self.signals.finished_signal.emit(
                False, "__DUPLICATE_RECEIPT__:" + json.dumps(payload, ensure_ascii=False), "", 0
            )
        except Exception as e:
            try:
                if "temp_pdf_path" in locals() and os.path.exists(temp_pdf_path):
                    os.remove(temp_pdf_path)
            except OSError:
                pass
            write_runtime_log(f"Error generando PDF: {e}")
            self.signals.finished_signal.emit(False, str(e), "", 0)

    def process(self, job):
        """Guarda el snapshot y reconstruye una copia temporal para abrir/imprimir."""
        patient = job["patient"]
        date_str = job["date_str"]
        diagnosis = job["dx_raw"]
        ars_name = job["ars_name"]
        coverage = job.get("coverage", "ASEGURADO")
        room = job["sala"]
        grouped = job["grouped"]
        total = job["total_general"]
        editing_id = job["editing_id"]
        editing_number = job["editing_num"]
        current_user = job["current_user"]
        authorization = str(job.get("authorization_number") or "").strip()
        total_started = perf_counter()
        try:
            generated_at = now_str()
            if editing_id is not None:
                try:
                    with db_connect() as con:
                        existing = con.execute(
                            "SELECT created_at FROM recibos WHERE id=%s",
                            (editing_id,),
                        ).fetchone()
                    if existing and existing["created_at"]:
                        generated_at = existing["created_at"]
                except Exception:
                    pass

            number_started = perf_counter()
            receipt_number = (
                editing_number
                if editing_id is not None
                else get_next_recibo_number()
            )
            number_elapsed = perf_counter() - number_started
            database_started = perf_counter()
            receipt_id = save_receipt_with_items(
                editing_id,
                receipt_number,
                patient,
                date_str,
                diagnosis,
                ars_name,
                room,
                total,
                "",
                current_user["username"],
                job["is_backdated"],
                generated_at,
                grouped,
                coverage,
                authorization,
                job.get("admission_attention"),
                str(job.get("admission_session_id") or ""),
                {
                    "visible_user": current_user.get(
                        "full_name", current_user["username"]
                    )
                },
                verification_bypass=job.get("verification_bypass"),
            )
            database_elapsed = perf_counter() - database_started
            try:
                render_started = perf_counter()
                with db_connect() as con:
                    stored_receipt = con.execute(
                        """SELECT document_storage_mode,pdf_filename
                           FROM recibos WHERE id=%s""",
                        (receipt_id,),
                    ).fetchone()
                    storage_mode = str(
                        stored_receipt["document_storage_mode"]
                        or STORAGE_LEGACY
                    )
                    direct_document = (
                        load_current_receipt_snapshot(con, receipt_id)
                        if storage_mode == STORAGE_LEGACY
                        else None
                    )
                pdf_path = (
                    render_receipt_snapshot_pdf(
                        direct_document, renderer=self.renderer
                    )
                    if direct_document is not None
                    else resolve_receipt_document_path(
                        receipt_id, renderer=self.renderer
                    )
                )
                if storage_mode in (STORAGE_LEGACY, STORAGE_HYBRID):
                    legacy_filename = f"recibo_{int(receipt_number)}.pdf"
                    legacy_path = stable_storage_path(
                        PDFS_DIR, legacy_filename
                    )
                    os.makedirs(os.path.dirname(legacy_path), exist_ok=True)
                    shutil.copyfile(pdf_path, legacy_path)
                    with db_connect() as con:
                        con.execute(
                            """UPDATE recibos
                               SET pdf_filename=%s,pdf_synced=0,
                                   pdf_sync_error=NULL
                               WHERE id=%s""",
                            (legacy_filename, receipt_id),
                        )
                    self.signals.sync_requested.emit(
                        receipt_id, legacy_filename, legacy_path
                    )
                render_elapsed = perf_counter() - render_started
            except Exception as render_error:
                write_runtime_log(
                    "Recibo guardado; fallo de reconstrucción temporal "
                    f"| recibo_id={receipt_id} "
                    f"| error={type(render_error).__name__}: "
                    f"{str(render_error)[:300]}"
                )
                self.signals.finished_signal.emit(
                    True,
                    "__RECEIPT_SAVED_RENDER_ERROR__:" + str(render_error),
                    "",
                    int(receipt_number),
                )
                return
            write_pdf_performance(
                f"Recibo {receipt_number} SNAPSHOT "
                f"| número={number_elapsed:.3f}s "
                f"| base_datos={database_elapsed:.3f}s "
                f"| reconstrucción={render_elapsed:.3f}s "
                f"| total={perf_counter() - total_started:.3f}s"
            )
            self.signals.finished_signal.emit(
                True, "Éxito", pdf_path, int(receipt_number)
            )
        except AdmissionAttentionUnavailableError as exc:
            self.signals.finished_signal.emit(
                False, "__ADMISSION_UNAVAILABLE__:" + str(exc), "", 0
            )
        except DuplicateReceiptError as exc:
            payload = {"message": str(exc), "receipt": exc.receipt}
            self.signals.finished_signal.emit(
                False,
                "__DUPLICATE_RECEIPT__:"
                + json.dumps(payload, ensure_ascii=False),
                "",
                0,
            )
        except Exception as exc:
            write_runtime_log(
                "Error guardando recibo SNAPSHOT "
                f"| error={type(exc).__name__}: {str(exc)[:500]}"
            )
            self.signals.finished_signal.emit(False, str(exc), "", 0)


def number_to_text(num: int) -> str:
    """Convert number to Spanish text (Dominican Republic format)."""
    if num == 0:
        return "CERO PESOS"
    
    units = ["", "UN", "DOS", "TRES", "CUATRO", "CINCO", "SEIS", "SIETE", "OCHO", "NUEVE"]
    teens = ["DIEZ", "ONCE", "DOCE", "TRECE", "CATORCE", "QUINCE", "DIECISÉIS", "DIECISIETE", "DIECIOCHO", "DIECINUEVE"]
    tens = ["", "", "VEINTE", "TREINTA", "CUARENTA", "CINCUENTA", "SESENTA", "SETENTA", "OCHENTA", "NOVENTA"]
    
    def convert_three(n):
        result = []
        c = n % 100
        d = n // 100
        if d > 0:
            result.append(f"{units[d]} CIENTOS")
        if c >= 10 and c <= 19:
            result.append(teens[c - 10])
        else:
            t = c // 10
            u = c % 10
            if t > 0:
                if u > 0:
                    result.append(f"{tens[t]} Y {units[u]}")
                else:
                    result.append(tens[t])
            elif u > 0:
                result.append(units[u])
        return " ".join(result)
    
    thousands = ["", "MIL", "MIL", "MILLONES"]
    parts = []
    
    milions = num // 1000000
    remainder = num % 1000000
    
    if milions > 0:
        if milions == 1:
            parts.append("UN MILLÓN")
        else:
            parts.append(f"{convert_three(milions)} MILLONES")
    
    thousands_val = remainder // 1000
    if thousands_val > 0:
        if thousands_val == 1:
            parts.append("MIL")
        else:
            parts.append(f"{convert_three(thousands_val)} MIL")
    
    remainder = remainder % 1000
    
    if remainder > 0:
        parts.append(convert_three(remainder))
    
    entero_text = " ".join(parts) if parts else "CERO"
    return f"SON: {entero_text} PESOS"


