    @staticmethod
    def _receipt_table():
        table = QTableWidget(0, 8)
        table.setHorizontalHeaderLabels(
            [
                "ID", "Recibo", "Paciente", "NSS", "Comprobante / NCF",
                "Fecha facturación", "ARS", "Total",
            ]
        )
        table.setSelectionBehavior(QAbstractItemView.SelectRows)
        table.setSelectionMode(QAbstractItemView.SingleSelection)
        table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        table.horizontalHeader().setSectionResizeMode(2, QHeaderView.Stretch)
        table.setColumnWidth(0, 55)
        table.setColumnWidth(1, 70)
        table.setColumnWidth(3, 120)
        table.setColumnWidth(4, 145)
        table.setColumnWidth(5, 150)
        table.setColumnWidth(6, 145)
        table.setColumnWidth(7, 100)
        return table

    def load_batches(self, select_id=None):
        rows = list_monthly_billing_batches()
        self.batches.setRowCount(0)
        selected_row = -1
        for data in rows:
            row = self.batches.rowCount()
            self.batches.insertRow(row)
            values = [
                data["id"],
                f"{CreateMonthlyBatchDialog.MONTHS[int(data['period_month']) - 1]} "
                f"{data['period_year']}",
                data["ars"],
                data["version"],
                data["cutoff_at"],
                data["receipts"],
                data.get("comprobantes", 0),
                f"RD$ {float(data['total'] or 0):,.2f}",
                batch_status_label(data["status"]),
            ]
            for column, value in enumerate(values):
                self.batches.setItem(row, column, QTableWidgetItem(str(value)))
            if select_id and int(data["id"]) == int(select_id):
                selected_row = row
        if self.batches.rowCount():
            self.batches.selectRow(selected_row if selected_row >= 0 else 0)
        else:
            self.load_selected_batch()
        self.apply_search_filter()

    def _fill_receipts(self, table, rows):
        table.setRowCount(0)
        for data in rows:
            row = table.rowCount()
            table.insertRow(row)
            receipt_id = data.get("recibo_id")
            values = [
                receipt_id,
                data.get("numero", ""),
                data.get("nombre") or data.get("patient_snapshot") or "",
                data.get("nss_snapshot") or "SIN NSS",
                data.get("comprobante_snapshot") or "PENDIENTE",
                data.get("billing_date_snapshot") or "",
                data.get("ars_snapshot") or "",
                f"RD$ {float(data.get('total_snapshot') or 0):,.2f}",
            ]
            for column, value in enumerate(values):
                table.setItem(row, column, QTableWidgetItem(str(value)))
        self.apply_search_filter()

    def apply_search_filter(self, _text=None):
        text = self.search_edit.text() if hasattr(self, "search_edit") else ""
        for table in (
            getattr(self, "included", None),
            getattr(self, "available", None),
        ):
            if table is not None:
                filter_table_widget(table, text)

    def load_selected_batch(self):
        row = self.batches.currentRow()
        if row < 0:
            self.current_batch_id = None
            self.included.setRowCount(0)
            self.available.setRowCount(0)
            self.batch_summary.setText("No hay listados mensuales generados.")
            self.add_button.setEnabled(False)
            self.remove_button.setEnabled(False)
            self.comprobante_button.setEnabled(False)
            return
        self.current_batch_id = int(self.batches.item(row, 0).text())
        batch = get_monthly_billing_batch(self.current_batch_id)
        included = list_monthly_batch_receipts(self.current_batch_id)
        available = list_available_receipts_for_batch(self.current_batch_id)
        self._fill_receipts(self.included, included)
        self._fill_receipts(self.available, available)
        total = sum(float(item.get("total_snapshot") or 0) for item in included)
        comprobantes = sum(
            1
            for item in included
            if str(item.get("comprobante_snapshot") or "").strip()
        )
        self.batch_summary.setText(
            f"{batch['ars']} · {CreateMonthlyBatchDialog.MONTHS[int(batch['period_month']) - 1]} "
            f"{batch['period_year']} · Corte: {batch['cutoff_at']} · "
            f"{len(included)} recibos · {comprobantes} con comprobante · "
            f"{len(included) - comprobantes} pendientes · RD$ {total:,.2f}"
        )
        editable = batch_is_editable(batch)
        self.add_button.setEnabled(editable and bool(available))
        self.remove_button.setEnabled(editable and bool(included))
        self.comprobante_button.setEnabled(editable and bool(included))

    def create_batch(self):
        dialog = CreateMonthlyBatchDialog(self)
        if dialog.exec() != QDialog.Accepted:
            return
        try:
            batch_id = create_monthly_billing_batch(
                user=self.current_user, **dialog.values()
            )
            self.load_batches(batch_id)
            FloatingToast("Listado mensual generado con el corte actual", self).show()
        except Exception as exc:
            QMessageBox.critical(self, "Generar listado", str(exc))

    def add_selected_receipt(self):
        row = self.available.currentRow()
        if row < 0 or not self.current_batch_id:
            return
        try:
            add_receipt_to_monthly_batch(
                self.current_batch_id,
                int(self.available.item(row, 0).text()),
                self.current_user,
            )
            self.load_batches(self.current_batch_id)
        except Exception as exc:
            QMessageBox.critical(self, "Agregar recibo", str(exc))

    def remove_selected_receipt(self):
        row = self.included.currentRow()
        if row < 0 or not self.current_batch_id:
            return
        reason, accepted = QInputDialog.getText(
            self,
            "Retirar recibo",
            "Motivo del retiro (quedará en el historial):",
        )
        if not accepted:
            return
        try:
            remove_receipt_from_monthly_batch(
                self.current_batch_id,
                int(self.included.item(row, 0).text()),
                self.current_user,
                reason,
            )
            self.load_batches(self.current_batch_id)
        except Exception as exc:
            QMessageBox.critical(self, "Retirar recibo", str(exc))

    def edit_selected_comprobante(self):
        row = self.included.currentRow()
        if row < 0 or not self.current_batch_id:
            FloatingToast(
                "Selecciona un recibo incluido",
                self,
                is_error=True,
            ).show()
            return
        receipt_id = int(self.included.item(row, 0).text())
        current = self.included.item(row, 4).text()
        if current == "PENDIENTE":
            current = ""
        value, accepted = QInputDialog.getText(
            self,
            "Comprobante / NCF",
            "Número de comprobante o NCF:",
            text=current,
        )
        if not accepted:
            return
        try:
            update_monthly_batch_receipt_comprobante(
                self.current_batch_id,
                receipt_id,
                value,
                self.current_user,
            )
            self.load_batches(self.current_batch_id)
            FloatingToast("Comprobante actualizado", self).show()
        except Exception as exc:
            QMessageBox.critical(self, "Comprobante / NCF", str(exc))


