def monthly_batch_candidate_key(candidate: dict) -> str:
    """Return the stable identity used by ARS candidate selection."""
    key = str(candidate.get("candidate_key") or "").strip()
    if key:
        return key
    receipt_id = candidate.get("recibo_id")
    if receipt_id is not None:
        return f"R:{int(receipt_id)}"
    source_id = str(
        candidate.get("admission_source_instance_id")
        or candidate.get("source_instance_id")
        or "LEGACY"
    ).strip()
    attention_id = candidate.get("admission_attention_id") or candidate.get("attention_id")
    if attention_id is not None:
        return f"A:{source_id}:{int(attention_id)}"
    return ""


def normalize_monthly_candidate_name(value) -> str:
    normalized = unicodedata.normalize("NFKD", str(value or "").casefold())
    without_accents = "".join(
        char for char in normalized if not unicodedata.combining(char)
    )
    return " ".join(without_accents.split())


def normalize_monthly_candidate_document(value) -> str:
    return re.sub(r"\D+", "", str(value or ""))


def filter_monthly_batch_candidates(
    candidates,
    search_mode: str = "ALL",
    term: str = "",
) -> tuple[list[dict], str | None]:
    """Filter already loaded ARS candidates without changing eligibility."""
    normalized_mode = str(search_mode or "ALL").upper()
    normalized_term = str(term or "").strip()
    if not normalized_term:
        return list(candidates), None

    if normalized_mode == "NAME" or (
        normalized_mode == "ALL" and not normalize_monthly_candidate_document(normalized_term)
    ):
        words = normalize_monthly_candidate_name(normalized_term).split()
        return [
            candidate for candidate in candidates
            if all(
                word in normalize_monthly_candidate_name(candidate.get("nombre"))
                for word in words
            )
        ], None

    document_term = normalize_monthly_candidate_document(normalized_term)
    if len(document_term) < 4:
        return [], "Escriba al menos 4 dígitos."
    fields = (
        ("nss_snapshot",)
        if normalized_mode == "NSS"
        else ("cedula_snapshot",)
        if normalized_mode == "CEDULA"
        else ("nss_snapshot", "cedula_snapshot")
    )
    exact_matches = [
        candidate for candidate in candidates
        if any(
            normalize_monthly_candidate_document(candidate.get(field)) == document_term
            for field in fields
        )
    ]
    if exact_matches:
        return exact_matches, None
    return [
        candidate for candidate in candidates
        if any(
            document_term in normalize_monthly_candidate_document(candidate.get(field))
            for field in fields
        )
    ], None


class MonthlyBatchCandidateSelectionDialog(QDialog):
    """Local candidate finder with selection persisted by candidate_key."""

    SEARCH_MODES = (
        ("Todos", "ALL", "Nombre, NSS o cédula"),
        ("Nombre", "NAME", "Nombre del paciente"),
        ("NSS", "NSS", "Número de NSS"),
        ("Cédula", "CEDULA", "Número de cédula"),
    )

    def __init__(self, candidates, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Añadir pacientes de la ARS")
        self.resize(1120, 640)
        self.setMinimumSize(860, 460)
        self.setSizeGripEnabled(True)
        self._candidates = [
            dict(candidate) for candidate in candidates
            if monthly_batch_candidate_key(candidate)
        ]
        self._candidate_by_key = {
            monthly_batch_candidate_key(candidate): candidate
            for candidate in self._candidates
        }
        self.selected_candidate_keys: set[str] = set()
        self._show_selected_only = False
        self._updating_checkboxes = False

        layout = QVBoxLayout(self)
        search_layout = QHBoxLayout()
        search_layout.addWidget(QLabel("Buscar por:"))
        self.search_mode = QComboBox()
        for label, value, _placeholder in self.SEARCH_MODES:
            self.search_mode.addItem(label, value)
        search_layout.addWidget(self.search_mode)
        self.search_input = QLineEdit()
        self.search_input.setClearButtonEnabled(True)
        search_layout.addWidget(self.search_input, 1)
        self.search_button = QPushButton("Buscar")
        self.clear_search_button = QPushButton("Limpiar")
        search_layout.addWidget(self.search_button)
        search_layout.addWidget(self.clear_search_button)
        layout.addLayout(search_layout)

        summary_layout = QHBoxLayout()
        self.results_label = QLabel()
        summary_layout.addWidget(self.results_label, 1)
        self.show_selected_button = QPushButton("Ver seleccionados (0)")
        self.clear_selection_button = QPushButton("Limpiar selección")
        summary_layout.addWidget(self.show_selected_button)
        summary_layout.addWidget(self.clear_selection_button)
        layout.addLayout(summary_layout)

        self.table = QTableWidget(0, 11)
        self.table.setHorizontalHeaderLabels([
            "ID", "Seleccionar", "Recibo", "Paciente", "ARS", "Fecha",
            "NSS", "Cédula", "Autorización", "Especialidad", "Monto",
        ])
        self.table.setColumnHidden(0, True)
        self.table.setSelectionBehavior(QAbstractItemView.SelectRows)
        self.table.setSelectionMode(QAbstractItemView.SingleSelection)
        self.table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        header = self.table.horizontalHeader()
        header.setSectionResizeMode(3, QHeaderView.Stretch)
        for column, width in {
            1: 90, 2: 88, 4: 130, 5: 96, 6: 118, 7: 118,
            8: 115, 9: 135, 10: 105,
        }.items():
            self.table.setColumnWidth(column, width)
        layout.addWidget(self.table, 1)

        buttons = QDialogButtonBox(QDialogButtonBox.Cancel | QDialogButtonBox.Ok)
        self.add_selected_button = buttons.button(QDialogButtonBox.Ok)
        buttons.accepted.connect(self._accept_selected)
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)

        self._populate_table()
        self.search_mode.currentIndexChanged.connect(self._search_mode_changed)
        self.search_button.clicked.connect(self._apply_filter)
        self.search_input.returnPressed.connect(self._apply_filter)
        self.clear_search_button.clicked.connect(self._clear_search)
        self.show_selected_button.clicked.connect(self._toggle_selected_view)
        self.clear_selection_button.clicked.connect(self._clear_selection)
        self.table.itemChanged.connect(self._checkbox_changed)
        self._search_mode_changed()
        self._apply_filter()

    def selected_keys_in_source_order(self) -> list[str]:
        return [
            monthly_batch_candidate_key(candidate)
            for candidate in self._candidates
            if monthly_batch_candidate_key(candidate) in self.selected_candidate_keys
        ]

    def _populate_table(self):
        self._updating_checkboxes = True
        try:
            for data in self._candidates:
                candidate_key = monthly_batch_candidate_key(data)
                row = self.table.rowCount()
                self.table.insertRow(row)
                values = [
                    candidate_key,
                    "",
                    data.get("numero", ""),
                    data.get("nombre", ""),
                    data.get("ars_snapshot", ""),
                    data.get("service_date_snapshot", ""),
                    data.get("nss_snapshot", ""),
                    data.get("cedula_snapshot", ""),
                    data.get("authorization_snapshot", ""),
                    data.get("specialty_snapshot", ""),
                    f"RD$ {float(data.get('total_snapshot') or data.get('total') or 0):,.2f}",
                ]
                for column, value in enumerate(values):
                    item = QTableWidgetItem(str(value))
                    if column == 1:
                        item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsUserCheckable)
                        item.setCheckState(Qt.Unchecked)
                    self.table.setItem(row, column, item)
        finally:
            self._updating_checkboxes = False

    def _search_mode_changed(self, _index=None):
        for _label, value, placeholder in self.SEARCH_MODES:
            if value == self.search_mode.currentData():
                self.search_input.setPlaceholderText(placeholder)
                break
        self._apply_filter()

    def _matching_keys(self) -> tuple[set[str], str | None]:
        matches, message = filter_monthly_batch_candidates(
            self._candidates,
            str(self.search_mode.currentData() or "ALL"),
            self.search_input.text(),
        )
        return {monthly_batch_candidate_key(candidate) for candidate in matches}, message

    def _apply_filter(self, _checked=False):
        matching_keys, message = self._matching_keys()
        if self._show_selected_only:
            matching_keys &= self.selected_candidate_keys
        for row in range(self.table.rowCount()):
            key_item = self.table.item(row, 0)
            self.table.setRowHidden(row, not key_item or key_item.text() not in matching_keys)
        self._update_summary(len(matching_keys), message)

    def _update_summary(self, visible_count: int, message: str | None = None):
        selected_count = len(self.selected_candidate_keys)
        selected_total = sum(
            float(self._candidate_by_key[key].get("total_snapshot")
                  or self._candidate_by_key[key].get("total") or 0)
            for key in self.selected_candidate_keys
            if key in self._candidate_by_key
        )
        detail = f"Resultados: {visible_count} · Seleccionados: {selected_count}"
        if selected_count:
            detail += f" · RD$ {selected_total:,.2f}"
        if message:
            detail += f" · {message}"
        self.results_label.setText(detail)
        self.show_selected_button.setText(
            "Ver todos" if self._show_selected_only
            else f"Ver seleccionados ({selected_count})"
        )
        self.clear_selection_button.setEnabled(bool(selected_count))
        self.add_selected_button.setText(f"Añadir seleccionados ({selected_count})")
        self.add_selected_button.setEnabled(bool(selected_count))

    def _checkbox_changed(self, item):
        if self._updating_checkboxes or item.column() != 1:
            return
        key_item = self.table.item(item.row(), 0)
        if key_item is None:
            return
        candidate_key = key_item.text()
        if item.checkState() == Qt.Checked:
            self.selected_candidate_keys.add(candidate_key)
        else:
            self.selected_candidate_keys.discard(candidate_key)
        self._apply_filter()

    def _clear_search(self, _checked=False):
        self.search_input.clear()
        self._show_selected_only = False
        self._apply_filter()

    def _toggle_selected_view(self, _checked=False):
        self._show_selected_only = not self._show_selected_only
        self._apply_filter()

    def _clear_selection(self, _checked=False):
        if not self.selected_candidate_keys:
            return
        if QMessageBox.question(
            self,
            "Limpiar selección",
            "Se desmarcarán todos los pacientes seleccionados. ¿Deseas continuar?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        ) != QMessageBox.Yes:
            return
        self._updating_checkboxes = True
        try:
            self.selected_candidate_keys.clear()
            for row in range(self.table.rowCount()):
                self.table.item(row, 1).setCheckState(Qt.Unchecked)
        finally:
            self._updating_checkboxes = False
        self._apply_filter()

    def _accept_selected(self, _checked=False):
        if not self.selected_candidate_keys:
            return
        self.accept()


class MonthlyBatchWorker(QThread):
    """Ejecuta cargas y mutaciones del expediente sin bloquear la interfaz."""

    succeeded = Signal(object)
    failed = Signal(str)

    def __init__(self, operation, parent=None):
        super().__init__(parent)
        self.operation = operation

    def run(self):
        try:
            self.succeeded.emit(self.operation())
        except Exception as exc:
            self.failed.emit(str(exc))


