    @Slot(bool)
    def apply_monthly_theme(self, is_dark):
        """Aplica la misma gramática visual sin tocar datos ni flujos de listados."""
        tokens = visual_theme_tokens(bool(is_dark))
        self.setStyleSheet(
            get_stylesheet(bool(is_dark))
            + modern_module_stylesheet(bool(is_dark))
            + f"""
            QTabWidget#MonthlySectionTabs::pane {{
                border: 1px solid {tokens['border']}; border-radius: 10px;
                top: -1px; background: {tokens['input_bg']};
            }}
            QTabWidget#MonthlySectionTabs QTabBar::tab {{
                min-height: 26px; padding: 10px 18px; margin: 0 4px 0 0;
                border: 1px solid {tokens['border']}; border-radius: 8px 8px 0 0;
                background: {tokens['alt_bg']}; color: {tokens['text']}; font-weight: 800;
            }}
            QTabWidget#MonthlySectionTabs QTabBar::tab:selected {{
                background: {tokens['input_bg']}; color: {tokens['title_color']};
                border-bottom: 3px solid {tokens['title_color']};
            }}
            QTabWidget#MonthlySectionTabs QTabBar::tab:!selected:hover {{
                background: {tokens['sel_bg']}; color: {tokens['sel_text']};
            }}
            QTableWidget#MonthlySavedTable {{ border-radius: 9px; }}
            QTabWidget#MonthlyWorkflowSteps::pane {{
                background: {tokens['input_bg']}; border: 1px solid {tokens['border']}; border-radius: 9px;
            }}
            QTabWidget#MonthlyWorkflowSteps QTabBar::tab {{
                padding: 8px 14px; min-width: 110px; font-weight: 800;
            }}
            QWidget#MonthlySavedFilters {{
                background: {tokens['input_bg']}; border: 1px solid {tokens['border']}; border-radius: 10px;
            }}
            QSplitter#MonthlyMainSplitter::handle {{
                background: {tokens['border']}; margin: 0 3px;
            }}
            """
        )

    def apply_layout_profile(self, snapshot):
        compact = snapshot.applied_profile in (PROFILE_VERY_COMPACT, PROFILE_COMPACT)
        standard = snapshot.applied_profile == PROFILE_STANDARD
        margin = 7 if compact else 12 if standard else 18
        spacing = 6 if compact else 9
        self.monthly_root_layout.setContentsMargins(
            margin, margin, margin, margin
        )
        self.monthly_root_layout.setSpacing(spacing)
        self.section_tabs.tabBar().setExpanding(not compact)
        self.section_tabs.tabBar().setUsesScrollButtons(compact)
        self.steps.tabBar().setExpanding(not compact)
        self.steps.tabBar().setUsesScrollButtons(compact)
        nav_width = 225 if compact else 280 if standard else 320
        self.monthly_navigator.setMinimumWidth(nav_width)
        self.monthly_navigator.setMaximumWidth(
            285 if compact else 360
        )
        self.monthly_main_splitter.setHandleWidth(5 if compact else 8)
        owner = self.parentWidget()
        while owner is not None and not hasattr(owner, "display_layout"):
            owner = owner.parentWidget()
        if owner is not None:
            owner.display_layout.restore_splitter(
                self.monthly_main_splitter,
                "monthly_lists",
                (0.25 if compact else 0.23, 0.75 if compact else 0.77),
                (nav_width, 480 if compact else 620),
            )
        row_height = 30 if compact else 34
        for table in (self.batches, self.saved_batches):
            table.verticalHeader().setDefaultSectionSize(row_height)
            table.setHorizontalScrollMode(QAbstractItemView.ScrollPerPixel)
            table.setVerticalScrollMode(QAbstractItemView.ScrollPerPixel)
        self.saved_filters_layout.setHorizontalSpacing(6 if compact else 10)
        self.saved_filters_layout.setVerticalSpacing(6)

