    def _selected_saved_batch(self):
        row = self.saved_batches.currentRow()
        if row < 0 or not self.saved_batches.item(row, 0):
            return None
        return self.saved_batches.item(row, 0).data(Qt.UserRole)

    def _selected_saved_batches(self):
        selection = self.saved_batches.selectionModel()
        if selection is None:
            return []
        rows = sorted({index.row() for index in selection.selectedRows(0)})
        return [
            self.saved_batches.item(row, 0).data(Qt.UserRole)
            for row in rows
            if self.saved_batches.item(row, 0)
            and not self.saved_batches.isRowHidden(row)
        ]

    def _fill_saved_batches(self, rows):
        ars_value = self.saved_ars_filter.currentData()
        year_value = self.saved_year_filter.currentData()
        ars_names = sorted(
            {str(row.get("ars_display_name") or row.get("ars") or "") for row in rows},
            key=str.casefold,
        )
        years = sorted({int(row["period_year"]) for row in rows}, reverse=True)
        self.saved_ars_filter.blockSignals(True)
        self.saved_year_filter.blockSignals(True)
        self.saved_ars_filter.clear()
        self.saved_ars_filter.addItem("Todas las ARS", "")
        for name in ars_names:
            self.saved_ars_filter.addItem(name, normalize_monthly_ars_name(name))
        self.saved_year_filter.clear()
        self.saved_year_filter.addItem("Todos los años", None)
        for year in years:
            self.saved_year_filter.addItem(str(year), year)
        ars_index = self.saved_ars_filter.findData(ars_value)
        year_index = self.saved_year_filter.findData(year_value)
        self.saved_ars_filter.setCurrentIndex(max(0, ars_index))
        self.saved_year_filter.setCurrentIndex(max(0, year_index))
        self.saved_ars_filter.blockSignals(False)
        self.saved_year_filter.blockSignals(False)

        self.saved_batches.setRowCount(0)
        for data in rows:
            row = self.saved_batches.rowCount()
            self.saved_batches.insertRow(row)
            period = f"{int(data['period_month']):02d}-{int(data['period_year']):04d}"
            values = [
                data["id"], period,
                data.get("ars_display_name") or data.get("ars") or "",
                data.get("version") or 1, data.get("receipts") or 0,
                f"RD$ {float(data.get('total') or 0):,.2f}",
                batch_status_label(data.get("status")),
                str(data.get("created_at") or ""),
                str(data.get("sent_at") or ""),
                str(data.get("sent_by") or ""),
            ]
            for column, value in enumerate(values):
                item = QTableWidgetItem(str(value))
                item.setData(Qt.UserRole, dict(data))
                if column == 6:
                    sent = batch_status_label(data.get("status")) == BATCH_SENT
                    item.setForeground(QColor("#0B6B45" if sent else "#9A5A00"))
                    item.setBackground(QColor("#DFF4EA" if sent else "#FFF2CC"))
                    font = item.font()
                    font.setBold(True)
                    item.setFont(font)
                self.saved_batches.setItem(row, column, item)
        self._filter_saved_batches()
        if self.saved_batches.rowCount():
            self.saved_batches.selectRow(0)
        else:
            self._update_saved_actions()

    def _filter_saved_batches(self, _index=None):
        ars_filter = str(self.saved_ars_filter.currentData() or "")
        year_filter = self.saved_year_filter.currentData()
        month_filter = self.saved_month_filter.currentData()
        status_filter = str(self.saved_status_filter.currentData() or "")
        for row in range(self.saved_batches.rowCount()):
            data = self.saved_batches.item(row, 0).data(Qt.UserRole) or {}
            normalized_status = batch_status_label(data.get("status"))
            hidden = bool(
                (
                    ars_filter
                    and normalize_monthly_ars_name(
                        data.get("ars_display_name") or data.get("ars")
                    ) != ars_filter
                )
                or (year_filter is not None and int(data.get("period_year") or 0) != int(year_filter))
                or (month_filter is not None and int(data.get("period_month") or 0) != int(month_filter))
                or (status_filter and normalized_status != status_filter)
            )
            self.saved_batches.setRowHidden(row, hidden)
        self._update_saved_actions()

    def _update_saved_actions(self):
        selected = self._selected_saved_batches()
        batch = selected[0] if len(selected) == 1 else None
        editable = bool(batch and batch_is_editable(batch))
        exists = bool(batch)
        pending = bool(
            batch and normalize_batch_status(batch.get("status")) == BATCH_PENDING
        )
        self.saved_open_button.setEnabled(exists)
        self.saved_edit_button.setEnabled(editable)
        self.saved_delete_button.setEnabled(editable)
        self.saved_export_button.setEnabled(exists)
        self.saved_confirm_button.setEnabled(
            pending
            and bool(batch.get("last_export_path"))
            and os.path.isfile(str(batch.get("last_export_path") or ""))
        )
        self.saved_report_button.setEnabled(
            any(batch_status_label(item.get("status")) == BATCH_SENT for item in selected)
        )

    def _select_batch_in_preparation(self, batch_id: int, step=None):
        self.section_tabs.setCurrentIndex(0)
        for row in range(self.batches.rowCount()):
            if int(self.batches.item(row, 0).text()) == int(batch_id):
                self.batches.selectRow(row)
                if step is not None:
                    QTimer.singleShot(250, lambda: self.steps.setCurrentIndex(step))
                return True
        return False

    def _open_saved_batch(self, _index=None):
        batch = self._selected_saved_batch()
        if batch:
            self._select_batch_in_preparation(int(batch["id"]))

    def _edit_saved_batch(self):
        batch = self._selected_saved_batch()
        if batch and self._select_batch_in_preparation(int(batch["id"]), 0):
            QTimer.singleShot(300, self.edit_current_batch)

    def _delete_saved_batch(self):
        batch = self._selected_saved_batch()
        if batch and self._select_batch_in_preparation(int(batch["id"])):
            QTimer.singleShot(300, self.delete_current_batch)

    def _export_saved_batch(self):
        batch = self._selected_saved_batch()
        if not batch:
            return
        if batch_is_editable(batch):
            if self._select_batch_in_preparation(int(batch["id"]), 2):
                QTimer.singleShot(
                    100,
                    lambda batch_id=int(batch["id"]): self._export_when_loaded(batch_id),
                )
        else:
            path = str(batch.get("last_export_path") or "")
            if path and os.path.isfile(path):
                os.startfile(path)
            else:
                QMessageBox.warning(self, "Exportar", "El archivo exportado no está disponible.")

    def _export_when_loaded(self, batch_id: int, attempts: int = 30):
        if int(self.current_batch_id or 0) == int(batch_id) and self.current_batch:
            self.export_workbook()
            return
        if attempts > 0:
            QTimer.singleShot(
                100,
                lambda: self._export_when_loaded(batch_id, attempts - 1),
            )

    def _confirm_saved_batch(self):
        batch = self._selected_saved_batch()
        if batch and self._select_batch_in_preparation(int(batch["id"]), 2):
            QTimer.singleShot(350, self.confirm_current_batch_sent)

    def generate_saved_batches_report(self):
        selected = self._selected_saved_batches()
        sent_ids = [
            int(item["id"]) for item in selected
            if batch_status_label(item.get("status")) == BATCH_SENT
        ]
        if not sent_ids:
            QMessageBox.information(
                self, "Generar reporte",
                "Selecciona uno o varios listados ENVIADOS.",
            )
            return
        output_dir = QFileDialog.getExistingDirectory(
            self, "Guardar reporte de listados enviados", REPORTS_DIR,
        )
        if not output_dir:
            return
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        base_path = os.path.join(output_dir, f"Reporte_Listados_Enviados_{stamp}")
        generated_by = str(self.current_user.get("username") or "Sistema")
        self.saved_report_button.setEnabled(False)

        def operation():
            rows = list_sent_billing_batches_report(batch_ids=sent_ids)
            if not rows:
                raise ValueError("Los listados seleccionados ya no están ENVIADOS.")
            return create_sent_batches_reports(
                base_path, rows, generated_by, LOGO_PATH,
            )

        def completed(paths):
            self._update_saved_actions()
            pdf_path, xlsx_path = paths
            QMessageBox.information(
                self, "Reporte generado",
                "Se generaron correctamente:\n"
                f"• PDF: {pdf_path}\n"
                f"• Excel: {xlsx_path}",
            )

        def failed(message):
            self._update_saved_actions()
            QMessageBox.critical(self, "Generar reporte", message)

        self._start_monthly_worker(operation, completed, failed)

