        cfg.addWidget(QLabel("Filtro Usuario:"), 1, 2)
        cfg.addWidget(self.user_filter, 1, 3)
        
        cfg.addWidget(QLabel("Desde la fecha:"), 2, 0)
        cfg.addWidget(self.date_from, 2, 1)
        cfg.addWidget(QLabel("Hasta la fecha:"), 2, 2)
