    def _report_theme(self):
        return visual_theme_tokens(bool(getattr(self.parent(), "is_dark_mode", False)))

    def _set_dashboard_state_style(self, kind="info"):
        self._dashboard_state_kind = kind
        if not hasattr(self, "dashboard_results_state"):
            return
        theme = self._report_theme()
        is_dark = bool(getattr(self.parent(), "is_dark_mode", False))
        if kind == "warning":
            bg, text = theme["warning_bg"], theme["warning_text"]
            border = "#80652E" if is_dark else "#E7C775"
        elif kind == "error":
            bg, text = theme["danger_bg"], theme["danger_text"]
            border = "#74404A" if is_dark else "#E7B0B0"
        else:
            bg, text, border = theme["audit_bg"], theme["audit_text"], theme["border"]
        self.dashboard_results_state.setStyleSheet(
            f"background: {bg}; color: {text}; border: 1px solid {border}; "
            "border-radius: 8px; padding: 11px 13px; font-weight: 700;"
        )

    @Slot(bool)
    def apply_reports_theme(self, is_dark):
        """Actualiza estilos locales sin recargar datos ni perder filtros."""
        theme = visual_theme_tokens(bool(is_dark))
        surface, alt, text = theme["input_bg"], theme["alt_bg"], theme["text"]
        border, title, muted = (
            theme["border"], theme["title_color"], theme["muted_text"]
        )
        self.setStyleSheet(
            get_stylesheet(bool(is_dark)) + modern_module_stylesheet(bool(is_dark))
        )
        self.tabs.setStyleSheet(
            f"QTabWidget#ReportsMainTabs::pane {{ background: {surface}; "
            f"border: 1px solid {border}; border-radius: 7px; }} "
            f"QTabWidget#ReportsMainTabs QTabBar::tab {{ min-width: 190px; "
            f"padding: 11px 18px; font-weight: 800; color: {text}; "
            f"background: {alt}; border: 1px solid {border}; }} "
            f"QTabWidget#ReportsMainTabs QTabBar::tab:hover {{ background: {theme['sel_bg']}; "
            f"color: {theme['sel_text']}; }} "
            f"QTabWidget#ReportsMainTabs QTabBar::tab:selected {{ background: {surface}; "
            f"color: {title}; border-bottom: 3px solid {title}; }}"
        )
        self.reports_header.setStyleSheet(
            f"QWidget#ReportsHeaderCard {{ background: {surface}; border: 1px solid {border}; "
            "border-radius: 11px; } "
            f"QLabel#ReportsHeaderTitle {{ color: {title}; font-size: 18pt; font-weight: 900; "
            "background: transparent; } "
            f"QLabel#ReportsHeaderSubtitle {{ color: {muted}; font-size: 10.5pt; background: transparent; }}"
        )
        for page in self._reports_tab_pages:
            page.setStyleSheet(f"background: {surface}; color: {text};")
        if hasattr(self, "dashboard_scroll"):
            self.dashboard_scroll.setStyleSheet(
                f"QScrollArea {{ background: {surface}; border: none; }} "
                f"QScrollArea > QWidget > QWidget {{ background: {surface}; }}"
            )
        if hasattr(self, "dashboard_content"):
            self.dashboard_content.setStyleSheet(f"background: {surface}; color: {text};")
        if hasattr(self, "dashboard_actions_widget"):
            self.dashboard_actions_widget.setStyleSheet(
                f"QWidget {{ background: {surface}; border: 1px solid {border}; "
                "border-radius: 9px; } QPushButton { border-radius: 6px; }"
            )
        info_style = (
            f"background: {theme['audit_bg']}; color: {theme['audit_text']}; "
            f"border: 1px solid {border}; border-radius: 8px; "
            "padding: 9px 12px; font-weight: 700;"
        )
        for name in (
            "dashboard_filter_summary", "shift_summary_text",
            "dashboard_comparison_periods", "report_intro", "report_filter_hint",
        ):
            label = getattr(self, name, None)
