    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, "display_layout"):
            self.display_layout.schedule_refresh()

    def _update_responsive_ui(self):
        width = self.width()
        height = self.height()
        mode, low_height = main_window_layout_profile(
            width,
            height,
            self.available_screen_height,
        )
        if mode == self._responsive_mode and low_height == self._low_height_mode:
            return
        self._responsive_mode = mode
        self._low_height_mode = low_height

        catalog_compact = width < 2300
        for index, category in enumerate(ALL_CATEGORIES):
            icon = CAT_EMOJIS.get(category, "")
            if mode == "wide" and not catalog_compact:
                label = f"{icon} {category}"
            elif mode in ("wide", "medium"):
                label = self.compact_tab_labels.get(category, category)
            else:
                label = icon or category[:3]
            self.tabs.setTabText(index, label)
            self.tabs.setTabToolTip(index, category)

        compact = mode == "compact"
        dense = compact or low_height
        self.lbl_modo_visual.setVisible(not dense)
        self.theme_control.setMaximumWidth(42 if dense else 164)
        self.header_subtitle.setVisible(not dense)
        self.cart_table.setColumnHidden(3, compact)
        self.btn_import_meds.setVisible(True)
        self.btn_ars_mgmt.setText("ARS" if dense else "Gestión ARS")
        self.btn_add_catalog_item.setText("Nuevo ítem")
        if self.current_admission_attention:
            attention_id = (
                self.current_admission_attention.get("attention_id")
                or self.current_admission_attention.get("admission_atencion_id")
            )
            inherited = (
                str(self.current_admission_attention.get("turn_scope") or "")
                == "HEREDADA DEL TURNO ANTERIOR"
            )
            self.btn_validate_admission.setText(
                (
                    f"Atención heredada del turno anterior · #{attention_id}"
                    if inherited
                    else f"Paciente validado · #{attention_id}"
                )
            )
        else:
            self.btn_validate_admission.setText(
                "VERIFICAR PACIENTE" if dense
                else "VERIFICAR PACIENTE PARA FACTURAR"
            )
        self.btn_import_meds.setText("Importar" if dense else "Importar Word")
        if self.btn_admin_catalog:
            self.btn_admin_catalog.setText("CATÁLOGO")

        self.header_layout.setContentsMargins(
            12 if dense else 20,
            4 if low_height else 15,
            12 if dense else 20,
            4 if low_height else 15,
        )
        self.header_widget.setMaximumHeight(72 if low_height else 16777215)
        if not self.header_logo_pixmap.isNull():
            logo_width, logo_height = ((84, 46) if low_height else (120, 70))
            self.header_logo.setPixmap(
                self.header_logo_pixmap.scaled(
                    logo_width,
                    logo_height,
                    Qt.KeepAspectRatio,
                    Qt.SmoothTransformation,
                )
            )
        self.header_title.setStyleSheet(
            f"font-size: {18 if dense else 24}pt; font-weight: 800;"
        )

        self.nav_layout.setContentsMargins(
            12 if dense else 20,
            2 if low_height else 5,
            12 if dense else 20,
            2 if low_height else 5,
        )
        nav_buttons = [
            self.btn_view_history,
            self.btn_receipts_history,
            self.btn_audit_workspace,
            self.btn_view_reports,
            self.btn_ars_mgmt,
            self.btn_import_meds,
            self.btn_admin_catalog,
            self.btn_admin_users,
        ]
        for button in nav_buttons:
            if button:
                button.setMaximumHeight(32 if low_height else 16777215)
        if self.btn_view_history:
            self.btn_view_history.setText("Acciones" if dense else "Historial de Acciones")
        self.btn_receipts_history.setText("Recibos" if dense else "Recibos Guardados")
        if self.btn_audit_workspace:
            self.btn_audit_workspace.setText(
                "Auditoría" if dense else "Auditoría Médica"
            )
        self.btn_view_reports.setText("Reportes")
        self.nav_widget.setFixedWidth(150 if dense else 190)
        if self.btn_admin_users:
            self.btn_admin_users.setText("Usuarios" if dense else "Gestión de Usuarios")
