def probe_database_connection(database_url=None) -> None:
    """Comprueba PostgreSQL con SELECT 1 sin migrar ni modificar datos."""
    value = validate_database_url(database_url or resolve_database_url())
    if psycopg2 is None:
        raise RuntimeError("El controlador PostgreSQL no está disponible.")
    connection = psycopg2.connect(value, connect_timeout=8)
    try:
        connection.autocommit = True
        with connection.cursor() as cursor:
            cursor.execute("SELECT 1")
            if cursor.fetchone() != (1,):
                raise RuntimeError("PostgreSQL devolvió una respuesta inesperada.")
    finally:
        connection.close()


def run_database_connection_check() -> int:
    """Diagnóstico silencioso usado por pruebas de Python y del EXE."""
    try:
        probe_database_connection()
        return 0
    except RuntimeError:
        return 2
    except Exception:
        return 3


def run_v15_packaging_check(output_path: str) -> int:
    """Verify the actual V15 module selected by source or a frozen build."""
    try:
        from PySide6.QtCore import QEventLoop
        from admission_v15_adapter import (
            _EXPECTED_V15_SOURCE_BUILD_ID,
            AdmissionV15EventBus,
            AdmissionV15Factory,
            load_v15_application_module,
        )

        module = load_v15_application_module()
        build_id = str(getattr(module, "V15_SOURCE_BUILD_ID", "") or "").strip()
        result = {
            "status": "PASS" if build_id == _EXPECTED_V15_SOURCE_BUILD_ID else "FAIL",
            "expected_build_id": _EXPECTED_V15_SOURCE_BUILD_ID,
            "loaded_build_id": build_id or "SIN_MARCADOR",
            "loaded_module_file": str(getattr(module, "__file__", "<frozen-module>")),
            "frozen": bool(getattr(sys, "frozen", False)),
        }
        original_data_dir = os.environ.get("EMERGENCIAS_DATA_DIR")
        try:
            with tempfile.TemporaryDirectory(prefix="hospital_v15_check_") as temp_dir:
                os.environ["EMERGENCIAS_DATA_DIR"] = temp_dir
                os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")
                qt_app = QApplication.instance() or QApplication([])
                host = SimpleNamespace(
                    connection_factory=lambda: None,
                    user={
                        "id": 1,
                        "username": "package_check",
                        "full_name": "Package Check",
                        "role": ROLE_ADMIN,
                    },
                    session_id="v15-package-check",
                    device_id="v15-package-device",
                    device_name="v15-package-device",
                    current_shift={},
                    configuration={},
                    logger=None,
                    event_bus=AdmissionV15EventBus(),
                )
                factory = AdmissionV15Factory(
                    host,
                    session_checker=lambda: True,
                    users_provider=lambda: [dict(host.user)],
                    credential_verifier=lambda _username, _password: None,
                )
                widget = factory.create_widget()
                try:
                    admission = getattr(widget, "admission", None)
                    result["admission_widget_constructed"] = bool(admission)
                    result["qt_application"] = bool(qt_app)
                    result["pink_admission_error_panel"] = False
                    result["history_opened"] = False
                    result["configuration_opened"] = False
                    if admission is not None:
                        admission.abrir_historial()
                        result["history_opened"] = bool(
                            getattr(admission, "historial_win", None)
                        )
                        admission._abrir_configuracion_interna()
                        result["configuration_opened"] = bool(
                            getattr(admission, "configuracion_interna_win", None)
                        )
                        smoke_loop = QEventLoop()
                        QTimer.singleShot(650, smoke_loop.quit)
                        smoke_loop.exec()
                        for attribute in (
                            "historial_win",
                            "configuracion_interna_win",
                        ):
                            window = getattr(admission, attribute, None)
                            if window is not None:
                                try:
                                    window.destroy()
                                except Exception:
                                    pass
                finally:
                    widget.shutdown()
                    widget.deleteLater()
        finally:
            if original_data_dir is None:
                os.environ.pop("EMERGENCIAS_DATA_DIR", None)
            else:
                os.environ["EMERGENCIAS_DATA_DIR"] = original_data_dir
        if not all(
            result.get(name)
            for name in (
                "admission_widget_constructed",
                "history_opened",
                "configuration_opened",
            )
        ):
            result["status"] = "FAIL"
        write_admission_integration_log(
            "V15_LOAD_OK "
            f"build_id={result['loaded_build_id']} "
            f"loaded_module_file={result['loaded_module_file']} "
            f"frozen={str(result['frozen']).lower()}"
        )
        Path(output_path).resolve().write_text(
            json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        return 0 if result["status"] == "PASS" else 2
    except Exception as exc:
        write_admission_integration_log(
            "V15_LOAD_ERROR "
            f"exception_type={type(exc).__name__} exception={exc}"
        )
        Path(output_path).resolve().write_text(
            json.dumps(
                {
                    "status": "FAIL",
                    "exception_type": type(exc).__name__,
                    "exception": str(exc),
                    "traceback": traceback.format_exc(),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        return 3


def run_active_system_users_check(output_path: str) -> int:
    """Verify the packaged user catalogue without opening a login dialog."""
    try:
        users = list_active_system_users()
        result = {
            "status": "PASS" if users else "FAIL",
            "active_system_users": len(users),
            "users": [
                {
                    "username": str(user.get("username") or ""),
                    "role": str(user.get("role") or ""),
                }
                for user in users
            ],
        }
        Path(output_path).resolve().write_text(
            json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        return 0 if users else 2
    except Exception as exc:
        Path(output_path).resolve().write_text(
            json.dumps(
                {
                    "status": "FAIL",
                    "exception_type": type(exc).__name__,
                    "exception": _sanitize_boot_log(exc),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        return 3


def run_config_users_ui_check(output_path: str) -> int:
    """Open the V15 configuration off-screen and verify its user rows."""
    original_data_dir = os.environ.get("EMERGENCIAS_DATA_DIR")
    widget = None
    try:
        from PySide6.QtCore import QEventLoop
        from PySide6.QtWidgets import QTabWidget, QTableWidget
        from admission_v15_adapter import AdmissionV15EventBus, AdmissionV15Factory

        # V15 keeps its rotating logger open for the process lifetime on
        # Windows.  This disposable diagnostic directory is intentionally not
        # removed synchronously, avoiding a false smoke-test failure on its
        # open log handle.
        with nullcontext(tempfile.mkdtemp(prefix="hospital_config_users_")) as data_dir:
            os.environ["EMERGENCIAS_DATA_DIR"] = data_dir
            os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")
            qt_app = QApplication.instance() or QApplication([])
            host = SimpleNamespace(
                connection_factory=lambda: None,
                user={
                    "id": 1,
                    "username": "admin",
                    "full_name": "Administrador del sistema",
                    "role": ROLE_ADMIN,
                },
                session_id="config-users-check",
                device_id="config-users-device",
                device_name="config-users-device",
                current_shift={},
                configuration={},
                logger=None,
                event_bus=AdmissionV15EventBus(),
            )
            factory = AdmissionV15Factory(
                host,
                session_checker=lambda: True,
                users_provider=list_active_system_users,
                credential_verifier=lambda _username, _password: None,
            )
            widget = factory.create_widget()
            admission = widget.admission
            admission._abrir_configuracion_interna()

            bootstrap_loop = QEventLoop()
            QTimer.singleShot(1000, bootstrap_loop.quit)
            bootstrap_loop.exec()
            configuration_window = admission.configuracion_interna_win
            notebook = next(
                item
                for item in configuration_window.findChildren(QTabWidget)
                if item.count() >= 8
            )
            representative_index = next(
                index
                for index in range(notebook.count())
                if notebook.tabText(index) == "Representante del turno"
            )
            notebook.setCurrentIndex(representative_index)

            load_loop = QEventLoop()
            QTimer.singleShot(2500, load_loop.quit)
            load_loop.exec()
            row_count = max(
                (table.rowCount() for table in configuration_window.findChildren(QTableWidget)),
                default=0,
            )
            expected_count = len(list_active_system_users())
            result = {
                "status": "PASS" if row_count == expected_count and row_count else "FAIL",
                "active_system_users": expected_count,
                "visible_config_users": row_count,
            }
            try:
                configuration_window.destroy()
            except Exception:
                pass
            widget.shutdown()
            widget.deleteLater()
            qt_app.processEvents()

        Path(output_path).resolve().write_text(
            json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        return 0 if result["status"] == "PASS" else 2
    except Exception as exc:
        Path(output_path).resolve().write_text(
            json.dumps(
                {
                    "status": "FAIL",
                    "exception_type": type(exc).__name__,
                    "exception": _sanitize_boot_log(exc),
                    "traceback": traceback.format_exc(),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        return 3
    finally:
        if original_data_dir is None:
            os.environ.pop("EMERGENCIAS_DATA_DIR", None)
        else:
            os.environ["EMERGENCIAS_DATA_DIR"] = original_data_dir


def request_database_retry(parent, error_code="DB-PROD-001") -> bool:
    box = QMessageBox(parent)
    box.setIcon(QMessageBox.Critical)
    box.setWindowTitle("Base de datos central")
    box.setText(
        "No fue posible conectar con la base de datos central de producción."
    )
    box.setInformativeText(
        "Verifica la conexión a internet o red e inténtalo nuevamente.\n\n"
        f"Código técnico: {error_code}"
    )
    retry_button = box.addButton("Reintentar", QMessageBox.AcceptRole)
    box.addButton("Cerrar", QMessageBox.RejectRole)
    box.exec()
    return box.clickedButton() is retry_button


def main():
    global DB_URL, CENTRAL_OFFLINE_BOOT, BOOTSTRAP_OPERATIONAL_SNAPSHOT
    global BOOTSTRAP_LOGIN_USERNAMES
    cleanup_old_updates()

    app = QApplication.instance() or QApplication(sys.argv)
    if ICON_PATH:
        app.setWindowIcon(QIcon(ICON_PATH))

    startup_action = {"value": "bootstrap"}
    gui_monitor = GuiResponsivenessMonitor(
        lambda: startup_action["value"], app, interval_ms=250, threshold_ms=750
    )
    app._global_gui_responsiveness_monitor = gui_monitor

    if not psycopg2:
        QMessageBox.critical(None, "Error de Configuración",
            "No está disponible el controlador de PostgreSQL (psycopg2)."
        )
        return 1

    while True:
        startup_action["value"] = "bootstrap central"
        result, failure = run_application_bootstrap()
        if result is not None:
            CENTRAL_OFFLINE_BOOT = not bool(result.central_online)
            BOOTSTRAP_OPERATIONAL_SNAPSHOT = dict(
                result.operational_snapshot or {}
            )
            BOOTSTRAP_LOGIN_USERNAMES = list(result.login_usernames or ())
            break
        failure = dict(failure or {})
        error_code = str(failure.get("code") or "DB-PROD-002")
        if error_code == "DB-PROD-CANCELLED":
            return 0
        if error_code == "DB-PROD-001":
            device_id, _device_name = _local_device_identity()
            if _OFFLINE_AUTH_CACHE.list_valid_usernames(device_id):
                CENTRAL_OFFLINE_BOOT = True
                write_runtime_log("OFFLINE_MODE_ENTERED login cache disponible")
                break
            if not request_database_retry(None, error_code):
                return 1
            continue
        stage = str(failure.get("stage") or "UNKNOWN")
        exception_type = str(failure.get("exception_type") or "Error")
        QMessageBox.critical(
            None,
            "Base de datos central",
            "La conexión fue establecida, pero no fue posible inicializar "
            "los servicios de datos.\n\n"
            f"Etapa: {stage}\nTipo: {exception_type}\n"
            "Código técnico: DB-PROD-002\n\n"
            f"Detalle completo: {MAIN_APP_LOG_PATH}",
        )
        return 1

    startup_action["value"] = "login"
    write_main_app_log("BOOT_STAGE_START", stage="UI_READY")
    controller = AppController(app)
    write_main_app_log(
        "BOOT_STAGE_OK",
        stage="UI_READY",
        elapsed_ms=0.0,
        success=True,
        details=f"gui_freeze_max_ms={gui_monitor.max_observed_lag_ms:.1f}",
    )
    return int(controller.run())

if __name__ == "__main__":
    if len(sys.argv) == 3 and sys.argv[1] == "--validate-responsive-ui":
        from responsive_validation import run as run_responsive_validation
        try:
            validation_exit = run_responsive_validation(
                sys.modules[__name__],
                sys.argv[2],
            )
        except Exception:
            validation_output = Path(sys.argv[2]).resolve()
            validation_output.mkdir(parents=True, exist_ok=True)
            (validation_output / "validation_error.txt").write_text(
                traceback.format_exc(), encoding="utf-8"
            )
            raise
        raise SystemExit(validation_exit)
    if len(sys.argv) == 2 and sys.argv[1] == "--check-database-connection":
        raise SystemExit(run_database_connection_check())
    if len(sys.argv) == 3 and sys.argv[1] == "--check-v15-package":
        raise SystemExit(run_v15_packaging_check(sys.argv[2]))
    if len(sys.argv) == 3 and sys.argv[1] == "--check-active-system-users":
        raise SystemExit(run_active_system_users_check(sys.argv[2]))
    if len(sys.argv) == 3 and sys.argv[1] == "--check-config-users-ui":
        raise SystemExit(run_config_users_ui_check(sys.argv[2]))
    if len(sys.argv) == 3 and sys.argv[1] == "--self-test-pdf":
        raise SystemExit(run_pdf_self_test(sys.argv[2]))
    if len(sys.argv) == 3 and sys.argv[1] == "--self-test-reports":
        raise SystemExit(run_report_exports_self_test(sys.argv[2]))
    raise SystemExit(main())
